    def _task_routing_eligibility_response(self, stored: Dict[str, Any], *, idempotent_replay: bool) -> Dict[str, Any]:
        contract = stored["eligibility_contract"]
        if not verify_task_routing_eligibility_contract(contract):
            raise RuntimeError("persisted Stage-3.4.3 routing eligibility contract integrity verification failed")
        head = self.repository.get_plan_version_head(stored["mission_id"])
        effective_status = "SUPERSEDED"
        if head is not None and head["active_plan_version_record_id"] == stored["plan_version_record_id"]:
            effective_status = "ACTIVE"
        gate = contract["eligibility_gate"]
        semantics = contract["semantics"]
        return {
            "status": "completed",
            "component_id": COMPONENT_ID,
            "control_version": CONTROL_VERSION,
            "idempotent_replay": bool(idempotent_replay),
            "mission_id": stored["mission_id"],
            "eligibility_gate_id": stored["eligibility_gate_id"],
            "routing_intent_id": stored["routing_intent_id"],
            "plan_version_record_id": stored["plan_version_record_id"],
            "plan_version": int(stored["plan_version"]),
            "planned_task_id": stored["planned_task_id"],
            "task_key": stored["task_key"],
            "effective_status": effective_status,
            "gate_result": stored["gate_result"],
            "eligibility_status": stored["eligibility_status"],
            "candidate_count": int(stored["candidate_count"]),
            "eligible_candidate_count": int(stored["eligible_candidate_count"]),
            "ineligible_candidate_count": int(stored["ineligible_candidate_count"]),
            "eligible_candidates": list(gate["eligible_candidates"]),
            "ineligible_candidates": list(gate["ineligible_candidates"]),
            "candidate_evaluations": list(gate["candidate_evaluations"]),
            "gate_rejection_reasons": list(gate["gate_rejection_reasons"]),
            "canonical_sha256": stored["canonical_sha256"],
            "eligibility_contract": contract,
            "eligibility_gate_performed": True,
            "compatibility_gate_performed": True,
            "eligible_candidate_is_selected_route": False,
            "eligibility_is_authorization": False,
            "eligibility_is_runtime_availability": False,
            "route_selection_performed": False,
            "route_ranking_performed": False,
            "selected_subsystem": None,
            "runtime_endpoint_resolution_performed": False,
            "runtime_health_probe_performed": False,
            "resource_assignment_performed": False,
            "governance_query_performed": False,
            "authorization_granted": False,
            "delegation_performed": False,
            "dispatch_performed": False,
            "governance_authorization_authority": semantics["governance_authorization_authority"],
            "target_action_dispatch_enabled": False,
            "target_actuation": False,
        }

    @_serialized_mission_mutation
    def create_task_routing_eligibility_gate(self, mission_id: str, payload: Any) -> Dict[str, Any]:
        stored_mission = self.repository.get_by_mission_id(mission_id)
        if stored_mission is None:
            raise MissionNotFound(mission_id)
        normalized = normalize_task_routing_eligibility_request(payload)
        req_hash = task_routing_eligibility_request_fingerprint(normalized)

        replay = self.repository.get_task_routing_eligibility_by_idempotency(mission_id, normalized["idempotency_key"])
        if replay is not None:
            if replay["request_sha256"] != req_hash:
                raise MissionTaskRoutingEligibilityConflict(
                    "task-routing eligibility idempotency_key was already used with a different canonical request"
                )
            return self._task_routing_eligibility_response(replay, idempotent_replay=True)

        state = self.repository.get_state(mission_id)
        if state is None or state["state"] not in TASK_ROUTING_ELIGIBILITY_ALLOWED_STATES:
            raise MissionTaskRoutingEligibilityGuardRejected(
                "Stage-3.4.3 eligibility gate requires Mission state PLANNING or REPLANNING"
            )
        if int(state["state_version"]) != int(normalized["expected_state_version"]):
            raise MissionConcurrencyConflict("task-routing eligibility expected_state_version is stale")
        before = self.get_mission_version_vector(mission_id)
        if before["version_sha256"] != normalized["expected_version_sha256"]:
            raise MissionConcurrencyConflict("task-routing eligibility expected_version_sha256 is stale")

        active = self.repository.get_active_plan_version(mission_id)
        if active is None or not verify_plan_version_contract(active["plan_version_contract"]):
            raise MissionTaskRoutingEligibilityGuardRejected(
                "Stage-3.4.3 eligibility gate requires a valid active Stage-3.3.7 Plan version"
            )
        if active["plan_version_record_id"] != normalized["expected_active_plan_version_record_id"]:
            raise MissionConcurrencyConflict("expected_active_plan_version_record_id does not match active Plan head")
        if int(active["plan_version"]) != int(normalized["expected_active_plan_version"]):
            raise MissionConcurrencyConflict("expected_active_plan_version does not match active Plan head")
        if active["canonical_sha256"] != normalized["expected_active_plan_sha256"]:
            raise MissionConcurrencyConflict("expected_active_plan_sha256 does not match active Plan head")

        readiness = self.repository.get_task_readiness_projection_for_plan_version(mission_id, int(active["plan_version"]))
        if readiness is None or not verify_task_readiness_projection_contract(readiness["projection_contract"]):
            raise MissionTaskRoutingEligibilityGuardRejected(
                "Stage-3.4.3 eligibility gate requires a valid active Stage-3.3.8 task-readiness projection"
            )
        if readiness["projection_id"] != normalized["expected_task_readiness_projection_id"]:
            raise MissionConcurrencyConflict("expected_task_readiness_projection_id does not match active readiness projection")
        if readiness["canonical_sha256"] != normalized["expected_task_readiness_projection_sha256"]:
            raise MissionConcurrencyConflict("expected_task_readiness_projection_sha256 does not match active readiness projection")

        routing_intent = self.repository.get_task_routing_intent(mission_id, normalized["expected_routing_intent_id"])
        if routing_intent is None:
            raise MissionTaskRoutingEligibilityNotFound(normalized["expected_routing_intent_id"])
        if not verify_task_routing_intent_contract(routing_intent["routing_intent_contract"]):
            raise MissionTaskRoutingEligibilityGuardRejected("Stage-3.4.2 routing intent failed integrity verification")
        if routing_intent["canonical_sha256"] != normalized["expected_routing_intent_sha256"]:
            raise MissionConcurrencyConflict("expected_routing_intent_sha256 is stale")
        if routing_intent["plan_version_record_id"] != active["plan_version_record_id"] or int(routing_intent["plan_version"]) != int(active["plan_version"]):
            raise MissionTaskRoutingEligibilityGuardRejected("Stage-3.4.2 routing intent is not bound to the active Plan version")
        if routing_intent["readiness_projection_id"] != readiness["projection_id"]:
            raise MissionTaskRoutingEligibilityGuardRejected("Stage-3.4.2 routing intent is not bound to the active readiness projection")
        if routing_intent["planned_task_id"] != normalized["planned_task_id"]:
            raise MissionTaskRoutingEligibilityGuardRejected("planned_task_id does not match the Stage-3.4.2 routing intent")

        readiness_items = list(readiness["projection_contract"]["projection"].get("task_readiness") or [])
        ready_item = next((x for x in readiness_items if x.get("planned_task_id") == normalized["planned_task_id"]), None)
        if ready_item is None or ready_item.get("readiness_status") != TASK_READY or ready_item.get("structurally_ready") is not True:
            raise MissionTaskRoutingEligibilityGuardRejected("Stage-3.4.3 eligibility is allowed only for a canonical READY task")

        required_subsystems = list(stored_mission.envelope.get("mission", {}).get("required_subsystems") or [])
        required_subsystem = routing_intent["routing_intent_contract"]["routing_intent"]["required_subsystem"]
        if required_subsystem not in {str(x).upper() for x in required_subsystems}:
            raise MissionTaskRoutingEligibilityGuardRejected(
                "routing intent required_subsystem is outside immutable Mission required_subsystems"
            )

        existing = self.repository.get_task_routing_eligibility_for_intent(mission_id, routing_intent["routing_intent_id"])
        if existing is not None:
            raise MissionTaskRoutingEligibilityConflict(
                "Stage-3.4.2 routing intent already has an immutable Stage-3.4.3 eligibility gate"
            )

        registry = self._verified_subsystem_registry()
        if routing_intent["registry_id"] != registry["identity"]["registry_id"] or int(routing_intent["registry_version"]) != int(registry["identity"]["registry_version"]) or routing_intent["registry_sha256"] != registry["integrity"]["canonical_sha256"]:
            raise MissionTaskRoutingEligibilityGuardRejected(
                "Stage-3.4.2 routing intent registry binding is not the current canonical Stage-3.4.1 registry"
            )

        eligibility_gate_id = new_task_routing_eligibility_id()
        created_at = utcnow_iso()
        contract = build_task_routing_eligibility_contract(
            eligibility_gate_id=eligibility_gate_id,
            mission_id=mission_id,
            request_sha256=req_hash,
            source_state=state,
            source_version_sha256=before["version_sha256"],
            active_plan=active,
            readiness_projection=readiness,
            routing_intent=routing_intent,
            registry_snapshot=registry,
            mission_required_subsystems=required_subsystems,
            created_by=normalized["created_by"],
            reason=normalized.get("reason"),
            metadata=normalized["metadata"],
            created_at=created_at,
        )
        if not verify_task_routing_eligibility_contract(contract):
            raise RuntimeError("new Stage-3.4.3 routing eligibility contract failed self-verification")

        stored = self.repository.store_task_routing_eligibility(
            mission_id=mission_id,
            eligibility_gate_id=eligibility_gate_id,
            routing_intent_id=routing_intent["routing_intent_id"],
            plan_version_record_id=active["plan_version_record_id"],
            plan_version=int(active["plan_version"]),
            readiness_projection_id=readiness["projection_id"],
            planned_task_id=normalized["planned_task_id"],
            task_key=routing_intent["task_key"],
            request_sha256=req_hash,
            idempotency_key=normalized["idempotency_key"],
            registry_id=registry["identity"]["registry_id"],
            registry_version=int(registry["identity"]["registry_version"]),
            registry_sha256=registry["integrity"]["canonical_sha256"],
            routing_intent_sha256=routing_intent["canonical_sha256"],
            eligibility_contract=contract,
            expected_state_version=int(normalized["expected_state_version"]),
            source_version_sha256=before["version_sha256"],
            expected_active_plan_sha256=active["canonical_sha256"],
            expected_readiness_projection_sha256=readiness["canonical_sha256"],
            actor=normalized["created_by"],
            reason=normalized.get("reason"),
            created_at=created_at,
        )
        self._record_mission_event(
            mission_id,
            "MISSION_TASK_ROUTING_ELIGIBILITY_EVALUATED",
            stored["eligibility_gate_id"],
            payload={
                "eligibility_gate_id": stored["eligibility_gate_id"],
                "routing_intent_id": stored["routing_intent_id"],
                "plan_version_record_id": stored["plan_version_record_id"],
                "plan_version": int(stored["plan_version"]),
                "planned_task_id": stored["planned_task_id"],
                "task_key": stored["task_key"],
                "gate_result": stored["gate_result"],
                "eligibility_status": stored["eligibility_status"],
                "candidate_count": int(stored["candidate_count"]),
                "eligible_candidate_count": int(stored["eligible_candidate_count"]),
                "ineligible_candidate_count": int(stored["ineligible_candidate_count"]),
                "eligible_candidate_is_selected_route": False,
                "eligibility_is_authorization": False,
                "runtime_endpoint_resolution_performed": False,
                "runtime_health_probe_performed": False,
                "governance_query_performed": False,
                "authorization_granted": False,
                "delegation_performed": False,
                "dispatch_performed": False,
            },
            occurred_at=stored["created_at"],
            state_version=int(stored["source_state_version"]),
            plan_version=int(stored["plan_version"]),
        )
        return self._task_routing_eligibility_response(stored, idempotent_replay=False)

