    def _task_route_selection_response(self, stored: Dict[str, Any], *, idempotent_replay: bool) -> Dict[str, Any]:
        contract = stored["route_selection_contract"]
        if not verify_task_route_selection_contract(contract):
            raise RuntimeError("persisted Stage-3.4.4 route-selection decision contract integrity verification failed")
