    @staticmethod
    def _execution_delivery_response(stored: Dict[str, Any], *, idempotent_replay: bool) -> Dict[str, Any]:
        contract = stored["execution_delivery_contract"]
        if not verify_execution_delivery_contract(contract):
            raise RuntimeError("persisted Stage-3.5.5 execution-delivery contract integrity verification failed")
        semantics = contract["semantics"]
        return {
            "status": "completed",
            "component_id": COMPONENT_ID,
            "control_version": CONTROL_VERSION,
            "idempotent_replay": bool(idempotent_replay),
            "mission_id": stored["mission_id"],
            "execution_delivery_id": stored["execution_delivery_id"],
            "execution_attempt_id": stored["execution_attempt_id"],
            "dispatch_envelope_id": stored["dispatch_envelope_id"],
            "execution_dispatch_id": stored["execution_dispatch_id"],
            "plan_version_record_id": stored["plan_version_record_id"],
            "plan_version": int(stored["plan_version"]),
            "planned_task_id": stored["planned_task_id"],
            "task_key": stored["task_key"],
            "delivery_status": stored["delivery_status"],
            "acknowledgement_status": stored["acknowledgement_status"],
            "execution_attempt_status": stored["execution_attempt_status"],
            "recipient_subsystem_id": stored["recipient_subsystem_id"],
            "recipient_capability_id": stored["recipient_capability_id"],
            "runtime_endpoint": stored["runtime_endpoint"],
            "runtime_endpoint_resolution_performed": True,
            "runtime_health_probe_performed": True,
            "runtime_health_sha256": stored["runtime_health_sha256"],
            "target_delivery_performed": True,
            "delivery_acknowledgement_performed": True,
            "execution_start_acknowledged": True,
            "execution_started": False,
            "running_state_recorded": False,
            "heartbeat_recorded": False,
            "external_target_network_io_performed": True,
            "target_action_dispatch_performed": True,
            "target_actuation": False,
            "governance_query_performed": False,
            "acknowledgement_id": stored["acknowledgement_id"],
            "acknowledgement_sha256": stored["acknowledgement_sha256"],
            "canonical_sha256": stored["canonical_sha256"],
            "execution_delivery_contract": contract,
            "semantics": semantics,
        }

