    def _execution_recovery_checkpoint_response(self, stored: Dict[str, Any], *, idempotent_replay: bool) -> Dict[str, Any]:
        contract = stored["recovery_checkpoint"]
        if not verify_execution_recovery_checkpoint_contract(contract):
            raise RuntimeError("persisted Stage-3.5.9 execution recovery checkpoint integrity verification failed")
        latest = self.repository.get_latest_execution_recovery_checkpoint(stored["mission_id"])
        effective_status = "ACTIVE" if latest is not None and latest["checkpoint_id"] == stored["checkpoint_id"] else "SUPERSEDED"
        event = self.repository.get_mission_event_by_causation(stored["mission_id"], EXECUTION_RECOVERY_EVENT_TYPE, stored["checkpoint_id"])
        return {
            "status": "completed",
            "component_id": COMPONENT_ID,
            "control_version": CONTROL_VERSION,
            "idempotent_replay": bool(idempotent_replay),
            "mission_id": stored["mission_id"],
            "checkpoint_id": stored["checkpoint_id"],
            "checkpoint_version": int(stored["checkpoint_version"]),
            "outcome_propagation_id": stored["outcome_propagation_id"],
            "result_capture_id": stored["result_capture_id"],
            "termination_control_id": stored.get("termination_control_id"),
            "execution_attempt_id": stored["execution_attempt_id"],
            "plan_version_record_id": stored["plan_version_record_id"],
            "plan_version": int(stored["plan_version"]),
            "planned_task_id": stored["planned_task_id"],
            "effective_status": effective_status,
            "source_event_count": int(stored["source_event_count"]),
            "source_event_tip_sha256": stored["source_event_tip_sha256"],
            "canonical_sha256": stored["canonical_sha256"],
            "recovery_state": contract["recovery_state"],
            "replay": contract["replay"],
            "recovery_checkpoint": contract,
            "checkpoint_event": event,
            "durable_repository_is_source_of_truth": True,
            **contract["semantics"],
        }

