    @_serialized_mission_mutation
    def create_execution_recovery_checkpoint(self, mission_id: str, payload: Any) -> Dict[str, Any]:
        if self.repository.get_by_mission_id(mission_id) is None:
            raise MissionNotFound(mission_id)
        normalized = normalize_execution_recovery_request(payload)
        req_hash = execution_recovery_request_fingerprint(normalized)
        replay_row = self.repository.get_execution_recovery_checkpoint_by_idempotency(mission_id, normalized["idempotency_key"])
        if replay_row is not None:
            if replay_row["request_sha256"] != req_hash:
                raise MissionExecutionRecoveryConflict("execution recovery idempotency_key was already used with a different canonical request")
            self._record_mission_event(
                mission_id, EXECUTION_RECOVERY_EVENT_TYPE, replay_row["checkpoint_id"],
                payload={
                    "checkpoint_id": replay_row["checkpoint_id"], "checkpoint_version": int(replay_row["checkpoint_version"]),
                    "outcome_propagation_id": replay_row["outcome_propagation_id"], "result_capture_id": replay_row["result_capture_id"],
                    "execution_attempt_id": replay_row["execution_attempt_id"], "canonical_sha256": replay_row["canonical_sha256"],
                    "source_execution_event_count": int(replay_row["source_event_count"]),
                    "source_execution_event_tip_sha256": replay_row["source_event_tip_sha256"],
                    "replay_is_execution": False, "recovery_is_authorization": False, "recovery_is_dispatch": False,
                    "recovery_is_runtime_resumption": False, "mission_state_transition_performed": False, "target_actuation": False,
                }, occurred_at=replay_row["created_at"], state_version=int(replay_row["source_state_version"]),
                plan_version=int(replay_row["plan_version"]),
            )
            return self._execution_recovery_checkpoint_response(replay_row, idempotent_replay=True)

        state = self.repository.get_state(mission_id)
        if state is None or state["state"] not in EXECUTION_RECOVERY_ALLOWED_STATES:
            raise MissionExecutionRecoveryGuardRejected("Stage-3.5.9 execution recovery requires a Stage-3.5.8 terminal outcome in Mission state RUNNING, FAILED, or ABORTED")
        if int(state["state_version"]) != int(normalized["expected_state_version"]):
            raise MissionConcurrencyConflict("execution recovery expected_state_version is stale")
        vector = self.get_mission_version_vector(mission_id)
        if vector["version_sha256"] != normalized["expected_version_sha256"]:
            raise MissionConcurrencyConflict("execution recovery expected_version_sha256 is stale")

        head = self.repository.get_plan_version_head(mission_id)
        if head is None or head["active_plan_version_record_id"] != normalized["expected_active_plan_version_record_id"] or int(head["active_plan_version"]) != int(normalized["expected_active_plan_version"]) or head["active_plan_sha256"] != normalized["expected_active_plan_sha256"]:
            raise MissionConcurrencyConflict("active Plan head changed before execution recovery checkpoint")
        active_plan = next((x for x in self.repository.list_plan_versions(mission_id) if x["plan_version_record_id"] == head["active_plan_version_record_id"]), None)
        if active_plan is None or active_plan["canonical_sha256"] != normalized["expected_active_plan_sha256"]:
            raise MissionExecutionRecoveryGuardRejected("active Plan version record is missing or corrupted")

        attempt = self.repository.get_execution_attempt(mission_id, normalized["expected_execution_attempt_id"])
        delivery = self.repository.get_execution_delivery(mission_id, normalized["expected_execution_delivery_id"])
        running = self.repository.get_execution_running_projection(mission_id, normalized["expected_running_projection_id"])
        result = self.repository.get_execution_result_capture(mission_id, normalized["expected_result_capture_id"])
        outcome = self.repository.get_execution_outcome_propagation(mission_id, normalized["expected_outcome_propagation_id"])
        if attempt is None or not verify_execution_attempt_contract(attempt["execution_attempt_contract"]):
            raise MissionExecutionRecoveryGuardRejected("Stage-3.5.4 execution attempt is missing or failed integrity verification")
        if delivery is None or not verify_execution_delivery_contract(delivery["execution_delivery_contract"]):
            raise MissionExecutionRecoveryGuardRejected("Stage-3.5.5 execution delivery is missing or failed integrity verification")
        if running is None or not verify_running_execution_projection_contract(running["running_execution_projection_contract"]):
            raise MissionExecutionRecoveryGuardRejected("Stage-3.5.6 running projection is missing or failed integrity verification")
        if result is None or not verify_execution_result_capture_contract(result["execution_result_capture_contract"]):
            raise MissionExecutionRecoveryGuardRejected("Stage-3.5.7 result capture is missing or failed integrity verification")
        if outcome is None or not verify_outcome_propagation_contract(outcome["outcome_propagation_contract"]):
            raise MissionExecutionRecoveryGuardRejected("Stage-3.5.8 outcome propagation is missing or failed integrity verification")
        expected_hashes = (
            (attempt, normalized["expected_execution_attempt_sha256"], "execution attempt"),
            (delivery, normalized["expected_execution_delivery_sha256"], "execution delivery"),
            (running, normalized["expected_running_projection_sha256"], "running projection"),
            (result, normalized["expected_result_capture_sha256"], "result capture"),
            (outcome, normalized["expected_outcome_propagation_sha256"], "outcome propagation"),
        )
        for row, expected, label in expected_hashes:
            if row["canonical_sha256"] != expected:
                raise MissionConcurrencyConflict(f"expected {label} SHA-256 does not match durable artifact")
        attempt_id = attempt["execution_attempt_id"]
        if any(x["execution_attempt_id"] != attempt_id for x in (delivery, running, result, outcome)):
            raise MissionExecutionRecoveryGuardRejected("Stage-3.5.4 through Stage-3.5.8 execution artifacts do not share one execution attempt")
        if delivery["execution_attempt_id"] != attempt_id or running["execution_delivery_id"] != delivery["execution_delivery_id"] or result["running_projection_id"] != running["running_projection_id"] or outcome["result_capture_id"] != result["result_capture_id"]:
            raise MissionExecutionRecoveryGuardRejected("execution trajectory source bindings are not contiguous")
        if attempt["plan_version_record_id"] != active_plan["plan_version_record_id"]:
            raise MissionExecutionRecoveryGuardRejected("execution attempt is not bound to active Plan head")
        if outcome["resulting_mission_state"] != state["state"] or int(outcome["resulting_state_version"]) != int(state["state_version"]):
            raise MissionExecutionRecoveryGuardRejected("Stage-3.5.8 outcome propagation is not authoritative for current Mission state/version")

        term = self.repository.get_execution_termination_control_for_attempt(mission_id, attempt_id)
        term_count = 0 if term is None else 1
        if term_count != int(normalized["expected_termination_control_count"]):
            raise MissionConcurrencyConflict("expected_termination_control_count does not match durable Stage-3.5.8 control evidence")
        if term is not None and (not verify_termination_control_contract(term["termination_control_contract"]) or term["execution_attempt_id"] != attempt_id):
            raise MissionExecutionRecoveryGuardRejected("Stage-3.5.8 termination control failed integrity/binding verification")
        if outcome.get("termination_control_id") != (None if term is None else term["termination_control_id"]):
            raise MissionExecutionRecoveryGuardRejected("Stage-3.5.8 outcome/termination-control binding mismatch")

        verified_events = self._verified_mission_events(mission_id)
        exec_replay = build_execution_event_replay(verified_events)
        if int(exec_replay["execution_event_count"]) != int(normalized["expected_execution_event_count"]):
            raise MissionConcurrencyConflict("execution event count changed before recovery checkpoint")
        if exec_replay["execution_event_tip_sha256"] != normalized["expected_execution_event_tip_sha256"]:
            raise MissionConcurrencyConflict("execution event tip changed before recovery checkpoint")
        if int(exec_replay["execution_event_count"]) < 8 or exec_replay["execution_event_tip_event_id"] is None:
            raise MissionExecutionRecoveryGuardRejected("execution event lineage is incomplete for Stage-3.5.1 through Stage-3.5.8 terminal trajectory")
        existing = self.repository.get_execution_recovery_checkpoint_for_outcome(mission_id, outcome["outcome_propagation_id"])
        if existing is not None:
            raise MissionExecutionRecoveryConflict("Stage-3.5.8 outcome propagation already has an immutable Stage-3.5.9 recovery checkpoint")

        checkpoint_id = new_execution_recovery_checkpoint_id()
        checkpoint_version = len(self.repository.list_execution_recovery_checkpoints(mission_id)) + 1
        now = utcnow_iso()
        contract = build_execution_recovery_checkpoint_contract(
            checkpoint_id=checkpoint_id, checkpoint_version=checkpoint_version, mission_id=mission_id,
            request_sha256=req_hash, source_state=state, source_version_sha256=normalized["expected_version_sha256"],
            active_plan=active_plan, execution_attempt=attempt, execution_delivery=delivery, running_projection=running,
            result_capture=result, termination_control=term, outcome_propagation=outcome, replay=exec_replay,
            created_by=normalized["created_by"], reason=normalized["reason"], metadata=normalized["metadata"], created_at=now,
        )
        if not verify_execution_recovery_checkpoint_contract(contract):
            raise MissionExecutionRecoveryGuardRejected("Stage-3.5.9 recovery checkpoint self-verification failed")
        mission_tip = None if not verified_events else verified_events[-1]["canonical_sha256"]
        if mission_tip is None:
            raise MissionExecutionRecoveryGuardRejected("Mission event lineage is empty")
        stored = self.repository.store_execution_recovery_checkpoint(
            mission_id=mission_id, checkpoint_id=checkpoint_id, checkpoint_version=checkpoint_version,
            outcome_propagation_id=outcome["outcome_propagation_id"], result_capture_id=result["result_capture_id"],
            termination_control_id=None if term is None else term["termination_control_id"], execution_attempt_id=attempt_id,
            plan_version_record_id=active_plan["plan_version_record_id"], plan_version=int(active_plan["plan_version"]),
            planned_task_id=attempt["planned_task_id"], request_sha256=req_hash, idempotency_key=normalized["idempotency_key"],
            contract=contract, expected_state=state["state"], expected_state_version=int(state["state_version"]),
            source_version_sha256=normalized["expected_version_sha256"], source_event_count=int(exec_replay["execution_event_count"]),
            source_event_tip_sha256=exec_replay["execution_event_tip_sha256"], expected_mission_event_tip_sha256=mission_tip,
            created_by=normalized["created_by"], reason=normalized["reason"], created_at=now,
        )
        self._record_mission_event(
            mission_id, EXECUTION_RECOVERY_EVENT_TYPE, stored["checkpoint_id"],
            payload={
                "checkpoint_id": stored["checkpoint_id"], "checkpoint_version": int(stored["checkpoint_version"]),
                "outcome_propagation_id": stored["outcome_propagation_id"], "result_capture_id": stored["result_capture_id"],
                "execution_attempt_id": stored["execution_attempt_id"], "termination_control_id": stored.get("termination_control_id"),
                "canonical_sha256": stored["canonical_sha256"], "source_execution_event_count": int(stored["source_event_count"]),
                "source_execution_event_tip_sha256": stored["source_event_tip_sha256"], "replay_is_execution": False,
                "recovery_is_authorization": False, "recovery_is_dispatch": False, "recovery_is_runtime_resumption": False,
                "runtime_health_probe_performed": False, "runtime_result_query_performed": False, "runtime_control_io_performed": False,
                "external_network_io_performed": False, "governance_query_performed": False, "dispatch_redelivery_performed": False,
                "new_execution_attempt_created": False, "new_target_action_dispatch_performed": False,
                "mission_state_transition_performed": False, "failure_propagation_performed": False,
                "mission_success_completion_authority_exercised": False, "target_actuation": False,
            }, occurred_at=stored["created_at"], state_version=int(stored["source_state_version"]),
            plan_version=int(stored["plan_version"]), policy_version=int(attempt["policy_version"]),
        )
        return self._execution_recovery_checkpoint_response(stored, idempotent_replay=False)

    def get_execution_recovery_checkpoint(self, mission_id: str, checkpoint_id: str) -> Dict[str, Any]:
        if self.repository.get_by_mission_id(mission_id) is None:
            raise MissionNotFound(mission_id)
        row = self.repository.get_execution_recovery_checkpoint(mission_id, checkpoint_id)
        if row is None:
            raise MissionExecutionRecoveryNotFound(checkpoint_id)
        return self._execution_recovery_checkpoint_response(row, idempotent_replay=False)

