    @_serialized_mission_mutation
    def evaluate_task_terminality_completion_eligibility(self, mission_id: str, payload: Any) -> Dict[str, Any]:
        if self.repository.get_by_mission_id(mission_id) is None:
            raise MissionNotFound(mission_id)
        normalized = normalize_task_terminality_eligibility_request(payload)
        req_hash = task_terminality_eligibility_request_fingerprint(normalized)

        replay = self.repository.get_task_terminality_eligibility_by_idempotency(
            mission_id, normalized["idempotency_key"]
        )
        if replay is not None:
            if replay["request_sha256"] != req_hash:
                raise MissionTaskTerminalityEligibilityConflict(
                    "task terminality/completion eligibility idempotency_key was already used with a different canonical request"
                )
            self._record_task_terminality_eligibility_event(replay)
            return self._task_terminality_eligibility_response(replay, idempotent_replay=True)

        state = self.repository.get_state(mission_id)
        if state is None or state["state"] not in TASK_TERMINALITY_ALLOWED_MISSION_STATES:
            raise MissionTaskTerminalityEligibilityGuardRejected(
                "Stage-3.6.2 terminality/completion eligibility requires Mission state RUNNING, FAILED, or ABORTED with an immutable Stage-3.6.1 task outcome"
            )
        if int(state["state_version"]) != int(normalized["expected_state_version"]):
            raise MissionConcurrencyConflict("task terminality/completion eligibility expected_state_version is stale")
        vector = self.get_mission_version_vector(mission_id)
        if vector["version_sha256"] != normalized["expected_version_sha256"]:
            raise MissionConcurrencyConflict("task terminality/completion eligibility expected_version_sha256 is stale")

        head = self.repository.get_plan_version_head(mission_id)
        if (
            head is None
            or head["active_plan_version_record_id"] != normalized["expected_active_plan_version_record_id"]
            or int(head["active_plan_version"]) != int(normalized["expected_active_plan_version"])
            or head["active_plan_sha256"] != normalized["expected_active_plan_sha256"]
        ):
            raise MissionConcurrencyConflict("active Plan head changed before task terminality/completion eligibility evaluation")
        active_plan = next(
            (
                x for x in self.repository.list_plan_versions(mission_id)
                if x["plan_version_record_id"] == head["active_plan_version_record_id"]
            ),
            None,
        )
        if active_plan is None or active_plan["canonical_sha256"] != normalized["expected_active_plan_sha256"]:
            raise MissionTaskTerminalityEligibilityGuardRejected("active Plan version record is missing or corrupted")

        task_outcome = self.repository.get_task_outcome(mission_id, normalized["expected_task_outcome_id"])
        if task_outcome is None:
            raise MissionTaskTerminalityEligibilityGuardRejected("Stage-3.6.1 task outcome is missing")
        if task_outcome["canonical_sha256"] != normalized["expected_task_outcome_sha256"]:
            raise MissionConcurrencyConflict("expected Stage-3.6.1 task outcome SHA-256 does not match durable artifact")
        if not verify_task_outcome_contract(task_outcome["task_outcome_contract"]):
            raise MissionTaskTerminalityEligibilityGuardRejected("Stage-3.6.1 task outcome failed integrity verification")
        if (
            task_outcome["plan_version_record_id"] != active_plan["plan_version_record_id"]
            or int(task_outcome["plan_version"]) != int(active_plan["plan_version"])
        ):
            raise MissionTaskTerminalityEligibilityGuardRejected("Stage-3.6.1 task outcome is not bound to the active Plan")
        if (
            task_outcome["source_state"] != state["state"]
            or int(task_outcome["source_state_version"]) != int(state["state_version"])
            or task_outcome["source_version_sha256"] != vector["version_sha256"]
        ):
            raise MissionTaskTerminalityEligibilityGuardRejected(
                "Stage-3.6.1 task outcome is stale relative to current Mission state/version"
            )
        if task_outcome["source_task_outcome_status"] not in TERMINALITY_BY_SOURCE_STATUS:
            raise MissionTaskTerminalityEligibilityGuardRejected(
                "Stage-3.6.1 task outcome source status is not terminal-classifiable"
            )
        if self.repository.get_task_terminality_eligibility_for_outcome(
            mission_id, task_outcome["task_outcome_id"]
        ) is not None:
            raise MissionTaskTerminalityEligibilityConflict(
                "Stage-3.6.1 task outcome already has an immutable Stage-3.6.2 terminality/completion eligibility gate"
            )

        now = utcnow_iso()
        eligibility_gate_id = new_task_terminality_eligibility_id()
        contract = build_task_terminality_eligibility_contract(
            eligibility_gate_id=eligibility_gate_id,
            mission_id=mission_id,
            request=normalized,
            request_sha256=req_hash,
            source_state=state,
            source_version_sha256=vector["version_sha256"],
            active_plan=active_plan,
            task_outcome=task_outcome,
            evaluated_at=now,
        )
        if not verify_task_terminality_eligibility_contract(contract):
            raise MissionTaskTerminalityEligibilityGuardRejected(
                "Stage-3.6.2 terminality/completion eligibility contract failed self-verification"
            )
        stored = self.repository.store_task_terminality_eligibility(
            mission_id=mission_id,
            eligibility_gate_id=eligibility_gate_id,
            plan_version_record_id=active_plan["plan_version_record_id"],
            plan_version=int(active_plan["plan_version"]),
            planned_task_id=task_outcome["planned_task_id"],
            task_key=task_outcome["task_key"],
            task_outcome_id=task_outcome["task_outcome_id"],
            request_sha256=req_hash,
            idempotency_key=normalized["idempotency_key"],
            contract=contract,
            expected_state=state["state"],
            expected_state_version=int(state["state_version"]),
            source_version_sha256=vector["version_sha256"],
            evaluated_by=normalized["evaluated_by"],
            reason=normalized.get("reason"),
            evaluated_at=now,
        )
        self._record_task_terminality_eligibility_event(stored)
        return self._task_terminality_eligibility_response(stored, idempotent_replay=False)

    def get_task_terminality_completion_eligibility(
        self, mission_id: str, eligibility_gate_id: str
    ) -> Dict[str, Any]:
        if self.repository.get_by_mission_id(mission_id) is None:
            raise MissionNotFound(mission_id)
        row = self.repository.get_task_terminality_eligibility(mission_id, eligibility_gate_id)
        if row is None:
            raise MissionTaskTerminalityEligibilityNotFound(eligibility_gate_id)
        return self._task_terminality_eligibility_response(row, idempotent_replay=False)

