    @_serialized_mission_mutation
    def verify_task_evidence_binding(self, mission_id: str, payload: Any) -> Dict[str, Any]:
        if self.repository.get_by_mission_id(mission_id) is None:
            raise MissionNotFound(mission_id)
        normalized = normalize_task_evidence_binding_verification_request(payload)
        req_hash = task_evidence_binding_verification_request_fingerprint(normalized)

        replay = self.repository.get_task_evidence_binding_verification_by_idempotency(
            mission_id, normalized["idempotency_key"]
        )
        if replay is not None:
            if replay["request_sha256"] != req_hash:
                raise MissionTaskEvidenceBindingConflict(
                    "task evidence-binding verification idempotency_key was already used with a different canonical request"
                )
            self._record_task_evidence_binding_verification_event(replay)
            return self._task_evidence_binding_verification_response(replay, idempotent_replay=True)

        state = self.repository.get_state(mission_id)
        if state is None or state["state"] not in TASK_EVIDENCE_BINDING_ALLOWED_MISSION_STATES:
            raise MissionTaskEvidenceBindingGuardRejected(
                "Stage-3.6.3 evidence-binding verification requires Mission state RUNNING, FAILED, or ABORTED"
            )
        if int(state["state_version"]) != int(normalized["expected_state_version"]):
            raise MissionConcurrencyConflict("task evidence-binding verification expected_state_version is stale")
        vector = self.get_mission_version_vector(mission_id)
        if vector["version_sha256"] != normalized["expected_version_sha256"]:
            raise MissionConcurrencyConflict("task evidence-binding verification expected_version_sha256 is stale")

        head = self.repository.get_plan_version_head(mission_id)
        if (
            head is None
            or head["active_plan_version_record_id"] != normalized["expected_active_plan_version_record_id"]
            or int(head["active_plan_version"]) != int(normalized["expected_active_plan_version"])
            or head["active_plan_sha256"] != normalized["expected_active_plan_sha256"]
        ):
            raise MissionConcurrencyConflict("active Plan head changed before task evidence-binding verification")
        active_plan = next(
            (x for x in self.repository.list_plan_versions(mission_id) if x["plan_version_record_id"] == head["active_plan_version_record_id"]),
            None,
        )
        if active_plan is None or active_plan["canonical_sha256"] != normalized["expected_active_plan_sha256"]:
            raise MissionTaskEvidenceBindingGuardRejected("active Plan version record is missing or corrupted")

        task_outcome = self.repository.get_task_outcome(mission_id, normalized["expected_task_outcome_id"])
        if task_outcome is None:
            raise MissionTaskEvidenceBindingGuardRejected("Stage-3.6.1 task outcome is missing")
        if task_outcome["canonical_sha256"] != normalized["expected_task_outcome_sha256"]:
            raise MissionConcurrencyConflict("expected Stage-3.6.1 task outcome SHA-256 does not match durable artifact")
        if not verify_task_outcome_contract(task_outcome["task_outcome_contract"]):
            raise MissionTaskEvidenceBindingGuardRejected("Stage-3.6.1 task outcome failed integrity verification")

        gate = self.repository.get_task_terminality_eligibility(mission_id, normalized["expected_eligibility_gate_id"])
        if gate is None:
            raise MissionTaskEvidenceBindingGuardRejected("Stage-3.6.2 terminality/completion eligibility gate is missing")
        if gate["canonical_sha256"] != normalized["expected_eligibility_gate_sha256"]:
            raise MissionConcurrencyConflict("expected Stage-3.6.2 eligibility gate SHA-256 does not match durable artifact")
        if not verify_task_terminality_eligibility_contract(gate["task_terminality_eligibility_contract"]):
            raise MissionTaskEvidenceBindingGuardRejected("Stage-3.6.2 eligibility gate failed integrity verification")
        if gate["task_outcome_id"] != task_outcome["task_outcome_id"] or gate["task_outcome_sha256"] != task_outcome["canonical_sha256"]:
            raise MissionTaskEvidenceBindingGuardRejected("Stage-3.6.2 gate is not bound to the supplied Stage-3.6.1 task outcome")
        if not gate["completion_eligible"] or gate["terminality_status"] != "TERMINAL_SUCCESS":
            raise MissionTaskEvidenceBindingGuardRejected("Stage-3.6.3 requires a completion-eligible TERMINAL_SUCCESS gate")

        result_capture = self.repository.get_execution_result_capture(mission_id, normalized["expected_result_capture_id"])
        if result_capture is None:
            raise MissionTaskEvidenceBindingGuardRejected("Stage-3.5.7 execution result capture is missing")
        if result_capture["canonical_sha256"] != normalized["expected_result_capture_sha256"]:
            raise MissionConcurrencyConflict("expected Stage-3.5.7 result capture SHA-256 does not match durable artifact")
        if task_outcome["result_capture_id"] != result_capture["result_capture_id"]:
            raise MissionTaskEvidenceBindingGuardRejected("Stage-3.6.1 task outcome is not bound to the supplied Stage-3.5.7 result capture")
        if task_outcome["task_outcome_contract"]["source_bindings"]["result_capture_sha256"] != result_capture["canonical_sha256"]:
            raise MissionTaskEvidenceBindingGuardRejected("Stage-3.6.1 result-capture hash binding is stale or inconsistent")
        if (
            task_outcome["plan_version_record_id"] != active_plan["plan_version_record_id"]
            or gate["plan_version_record_id"] != active_plan["plan_version_record_id"]
            or result_capture["plan_version_record_id"] != active_plan["plan_version_record_id"]
            or task_outcome["planned_task_id"] != gate["planned_task_id"]
            or task_outcome["planned_task_id"] != result_capture["planned_task_id"]
        ):
            raise MissionTaskEvidenceBindingGuardRejected("evidence-binding source artifacts do not share the active Plan/task lineage")
        if (
            task_outcome["source_state"] != state["state"]
            or int(task_outcome["source_state_version"]) != int(state["state_version"])
            or task_outcome["source_version_sha256"] != vector["version_sha256"]
            or gate["source_state"] != state["state"]
            or int(gate["source_state_version"]) != int(state["state_version"])
            or gate["source_version_sha256"] != vector["version_sha256"]
        ):
            raise MissionTaskEvidenceBindingGuardRejected("Stage-3.6.1/3.6.2 sources are stale relative to current Mission state/version")
        if self.repository.get_task_evidence_binding_verification_for_gate(mission_id, gate["eligibility_gate_id"]) is not None:
            raise MissionTaskEvidenceBindingConflict(
                "Stage-3.6.2 eligibility gate already has an immutable Stage-3.6.3 evidence-binding verification"
            )

        now = utcnow_iso()
        verification_id = new_task_evidence_binding_verification_id()
        try:
            contract = build_task_evidence_binding_verification_contract(
                verification_id=verification_id,
                mission_id=mission_id,
                request=normalized,
                request_sha256=req_hash,
                source_state=state,
                source_version_sha256=vector["version_sha256"],
                active_plan=active_plan,
                task_outcome=task_outcome,
                eligibility_gate=gate,
                result_capture=result_capture,
                verified_at=now,
            )
        except MissionValidationError as exc:
            raise MissionTaskEvidenceBindingGuardRejected(str(exc)) from exc
        if not verify_task_evidence_binding_verification_contract(contract):
            raise MissionTaskEvidenceBindingGuardRejected("Stage-3.6.3 evidence-binding verification contract failed self-verification")
        stored = self.repository.store_task_evidence_binding_verification(
            mission_id=mission_id,
            verification_id=verification_id,
            plan_version_record_id=active_plan["plan_version_record_id"],
            plan_version=int(active_plan["plan_version"]),
            planned_task_id=task_outcome["planned_task_id"],
            task_key=task_outcome["task_key"],
            task_outcome_id=task_outcome["task_outcome_id"],
            eligibility_gate_id=gate["eligibility_gate_id"],
            result_capture_id=result_capture["result_capture_id"],
            request_sha256=req_hash,
            idempotency_key=normalized["idempotency_key"],
            contract=contract,
            expected_state=state["state"],
            expected_state_version=int(state["state_version"]),
            source_version_sha256=vector["version_sha256"],
            verified_by=normalized["verified_by"],
            reason=normalized.get("reason"),
            verified_at=now,
        )
        self._record_task_evidence_binding_verification_event(stored)
        return self._task_evidence_binding_verification_response(stored, idempotent_replay=False)

    def get_task_evidence_binding_verification(self, mission_id: str, verification_id: str) -> Dict[str, Any]:
        if self.repository.get_by_mission_id(mission_id) is None:
            raise MissionNotFound(mission_id)
        row = self.repository.get_task_evidence_binding_verification(mission_id, verification_id)
        if row is None:
            raise MissionTaskEvidenceBindingNotFound(verification_id)
        return self._task_evidence_binding_verification_response(row, idempotent_replay=False)

