    @_serialized_mission_mutation
    def aggregate_mission_outcome(self, mission_id: str, payload: Any) -> Dict[str, Any]:
        if self.repository.get_by_mission_id(mission_id) is None:
            raise MissionNotFound(mission_id)
        normalized = normalize_mission_outcome_aggregation_request(payload)
        req_hash = mission_outcome_aggregation_request_fingerprint(normalized)
        replay = self.repository.get_mission_outcome_aggregation_by_idempotency(mission_id, normalized["idempotency_key"])
        if replay is not None:
            if replay["request_sha256"] != req_hash:
                raise MissionOutcomeAggregationConflict(
                    "mission outcome aggregation idempotency_key was already used with a different canonical request"
                )
            self._record_mission_outcome_aggregation_event(replay)
            return self._mission_outcome_aggregation_response(replay, idempotent_replay=True)

        state = self.repository.get_state(mission_id)
        if state is None or state["state"] not in MISSION_OUTCOME_ALLOWED_MISSION_STATES:
            raise MissionOutcomeAggregationGuardRejected(
                "Stage-3.6.5 mission outcome aggregation requires Mission state RUNNING, FAILED, or ABORTED"
            )
        if int(state["state_version"]) != int(normalized["expected_state_version"]):
            raise MissionConcurrencyConflict("mission outcome aggregation expected_state_version is stale")
        vector = self.get_mission_version_vector(mission_id)
        if vector["version_sha256"] != normalized["expected_version_sha256"]:
            raise MissionConcurrencyConflict("mission outcome aggregation expected_version_sha256 is stale")

        head = self.repository.get_plan_version_head(mission_id)
        if (
            head is None
            or head["active_plan_version_record_id"] != normalized["expected_active_plan_version_record_id"]
            or int(head["active_plan_version"]) != int(normalized["expected_active_plan_version"])
            or head["active_plan_sha256"] != normalized["expected_active_plan_sha256"]
        ):
            raise MissionConcurrencyConflict("active Plan head changed before mission outcome aggregation")
        active_plan = next((x for x in self.repository.list_plan_versions(mission_id)
                            if x["plan_version_record_id"] == head["active_plan_version_record_id"]), None)
        if active_plan is None or active_plan["canonical_sha256"] != normalized["expected_active_plan_sha256"] or not verify_plan_version_contract(active_plan["plan_version_contract"]):
            raise MissionOutcomeAggregationGuardRejected("active Plan version record is missing or corrupted")

        plan_id = active_plan["plan_version_record_id"]
        plan_ver = int(active_plan["plan_version"])
        task_outcomes = [x for x in self.repository.list_task_outcomes(mission_id)
                         if x["plan_version_record_id"] == plan_id and int(x["plan_version"]) == plan_ver]
        task_completions = [x for x in self.repository.list_task_completions(mission_id)
                            if x["plan_version_record_id"] == plan_id and int(x["plan_version"]) == plan_ver]
        running_projections = [x for x in self.repository.list_execution_running_projections(mission_id)
                               if x["plan_version_record_id"] == plan_id and int(x["plan_version"]) == plan_ver]
        now = utcnow_iso()
        aggregation_id = new_mission_outcome_aggregation_id()
        try:
            contract = build_mission_outcome_aggregation_contract(
                aggregation_id=aggregation_id,
                mission_id=mission_id,
                request=normalized,
                request_sha256=req_hash,
                source_state=state,
                source_version_sha256=vector["version_sha256"],
                active_plan=active_plan,
                task_outcomes=task_outcomes,
                task_completions=task_completions,
                running_projections=running_projections,
                aggregated_at=now,
            )
        except MissionValidationError as exc:
            raise MissionOutcomeAggregationGuardRejected(str(exc)) from exc
        if not verify_mission_outcome_aggregation_contract(contract):
            raise MissionOutcomeAggregationGuardRejected("Stage-3.6.5 mission outcome aggregation contract failed self-verification")
        stored = self.repository.store_mission_outcome_aggregation(
            mission_id=mission_id,
            aggregation_id=aggregation_id,
            plan_version_record_id=plan_id,
            plan_version=plan_ver,
            request_sha256=req_hash,
            idempotency_key=normalized["idempotency_key"],
            contract=contract,
            expected_state=state["state"],
            expected_state_version=int(state["state_version"]),
            source_version_sha256=vector["version_sha256"],
            aggregated_by=normalized["aggregated_by"],
            reason=normalized.get("reason"),
            aggregated_at=now,
        )
        self._record_mission_outcome_aggregation_event(stored)
        return self._mission_outcome_aggregation_response(stored, idempotent_replay=False)

    def get_mission_outcome_aggregation(self, mission_id: str, aggregation_id: str) -> Dict[str, Any]:
        if self.repository.get_by_mission_id(mission_id) is None:
            raise MissionNotFound(mission_id)
        row = self.repository.get_mission_outcome_aggregation(mission_id, aggregation_id)
        if row is None:
            raise MissionOutcomeAggregationNotFound(aggregation_id)
        return self._mission_outcome_aggregation_response(row, idempotent_replay=False)

