    @staticmethod
    def _mission_success_evaluation_response(stored: Dict[str, Any], *, idempotent_replay: bool) -> Dict[str, Any]:
        contract = stored["mission_success_evaluation_contract"]
        if not verify_mission_success_evaluation_contract(contract):
            raise RuntimeError("persisted Stage-3.6.6 mission success criteria evaluation contract integrity verification failed")
        ev = contract["success_criteria_evaluation"]
        b = contract["authority_boundary"]
        return {
            "status": "completed", "component_id": COMPONENT_ID, "control_version": CONTROL_VERSION,
            "idempotent_replay": bool(idempotent_replay), "mission_id": stored["mission_id"],
            "evaluation_id": stored["evaluation_id"], "plan_version_record_id": stored["plan_version_record_id"],
            "plan_version": int(stored["plan_version"]), "aggregation_id": stored["aggregation_id"],
            "evaluation_status": stored["evaluation_status"], "overall_result": stored["overall_result"],
            "criterion_count": int(stored["criterion_count"]), "satisfied_count": int(stored["satisfied_count"]),
            "not_satisfied_count": int(stored["not_satisfied_count"]), "indeterminate_count": int(stored["indeterminate_count"]),
            "criteria_results": list(ev["criteria_results"]), "success_criteria_sha256": stored["success_criteria_sha256"],
            "aggregation_sha256": stored["aggregation_sha256"], "canonical_sha256": stored["canonical_sha256"],
            "mission_success_evaluation_contract": contract, "source_state": stored["source_state"],
            "source_state_version": int(stored["source_state_version"]), "source_version_sha256": stored["source_version_sha256"],
            **{k: bool(v) for k, v in b.items()},
        }

    def _record_mission_success_evaluation_event(self, stored: Dict[str, Any]) -> Dict[str, Any]:
        ev=stored["mission_success_evaluation_contract"]["success_criteria_evaluation"]
        return self._record_mission_event(stored["mission_id"], "MISSION_SUCCESS_CRITERIA_EVALUATED", stored["evaluation_id"],
            payload={"evaluation_id": stored["evaluation_id"], "aggregation_id": stored["aggregation_id"],
                     "evaluation_status": stored["evaluation_status"], "overall_result": stored["overall_result"],
                     "criterion_count": int(stored["criterion_count"]), "satisfied_count": int(stored["satisfied_count"]),
                     "not_satisfied_count": int(stored["not_satisfied_count"]), "indeterminate_count": int(stored["indeterminate_count"]),
                     "success_criteria_sha256": stored["success_criteria_sha256"], "aggregation_sha256": stored["aggregation_sha256"],
                     "canonical_sha256": stored["canonical_sha256"], "mission_completion_readiness_decision_performed": False,
                     "mission_success_completion_authority_exercised": False, "mission_state_transition_performed": False},
            occurred_at=stored["evaluated_at"], state_version=int(stored["source_state_version"]), plan_version=int(stored["plan_version"]))

    @_serialized_mission_mutation
    def evaluate_mission_success_criteria(self, mission_id: str, payload: Any) -> Dict[str, Any]:
        stored_mission=self.repository.get_by_mission_id(mission_id)
        if stored_mission is None: raise MissionNotFound(mission_id)
        normalized=normalize_mission_success_evaluation_request(payload); req_hash=mission_success_evaluation_request_fingerprint(normalized)
        replay=self.repository.get_mission_success_evaluation_by_idempotency(mission_id, normalized["idempotency_key"])
        if replay is not None:
            if replay["request_sha256"] != req_hash: raise MissionSuccessEvaluationConflict("mission success criteria evaluation idempotency_key was already used with a different canonical request")
            self._record_mission_success_evaluation_event(replay)
            return self._mission_success_evaluation_response(replay,idempotent_replay=True)
        state=self.repository.get_state(mission_id)
        if state is None or state["state"] not in MISSION_SUCCESS_ALLOWED_MISSION_STATES:
            raise MissionSuccessEvaluationGuardRejected("Stage-3.6.6 success criteria evaluation requires Mission state RUNNING, FAILED, or ABORTED")
        if int(state["state_version"]) != int(normalized["expected_state_version"]): raise MissionConcurrencyConflict("mission success criteria evaluation expected_state_version is stale")
        vector=self.get_mission_version_vector(mission_id)
        if vector["version_sha256"] != normalized["expected_version_sha256"]: raise MissionConcurrencyConflict("mission success criteria evaluation expected_version_sha256 is stale")
        head=self.repository.get_plan_version_head(mission_id)
        if head is None or head["active_plan_version_record_id"] != normalized["expected_active_plan_version_record_id"] or int(head["active_plan_version"]) != int(normalized["expected_active_plan_version"]) or head["active_plan_sha256"] != normalized["expected_active_plan_sha256"]:
            raise MissionConcurrencyConflict("active Plan head changed before mission success criteria evaluation")
        active_plan=next((x for x in self.repository.list_plan_versions(mission_id) if x["plan_version_record_id"]==head["active_plan_version_record_id"]),None)
        if active_plan is None: raise MissionSuccessEvaluationGuardRejected("active Plan version record is missing")
        aggregation=self.repository.get_mission_outcome_aggregation(mission_id, normalized["expected_aggregation_id"] )
        if aggregation is None: raise MissionSuccessEvaluationGuardRejected("referenced Stage-3.6.5 mission outcome aggregation is missing")
        if aggregation["canonical_sha256"] != normalized["expected_aggregation_sha256"]: raise MissionConcurrencyConflict("referenced Stage-3.6.5 aggregation hash changed or mismatched")
        if aggregation["plan_version_record_id"] != active_plan["plan_version_record_id"] or int(aggregation["plan_version"]) != int(active_plan["plan_version"]): raise MissionSuccessEvaluationGuardRejected("referenced Stage-3.6.5 aggregation belongs to a stale/superseded Plan")
        success_criteria=list(stored_mission.envelope.get("mission",{}).get("success_criteria") or [])
        now=utcnow_iso(); evaluation_id=new_mission_success_evaluation_id()
        try:
            contract=build_mission_success_evaluation_contract(evaluation_id=evaluation_id, mission_id=mission_id, request=normalized, request_sha256=req_hash, source_state=state, source_version_sha256=vector["version_sha256"], active_plan=active_plan, aggregation=aggregation, success_criteria=success_criteria, evaluated_at=now)
        except MissionValidationError as exc: raise MissionSuccessEvaluationGuardRejected(str(exc)) from exc
        if not verify_mission_success_evaluation_contract(contract): raise MissionSuccessEvaluationGuardRejected("Stage-3.6.6 mission success criteria evaluation contract failed self-verification")
        row=self.repository.store_mission_success_evaluation(mission_id=mission_id,evaluation_id=evaluation_id,plan_version_record_id=active_plan["plan_version_record_id"],plan_version=int(active_plan["plan_version"]),aggregation_id=aggregation["aggregation_id"],request_sha256=req_hash,idempotency_key=normalized["idempotency_key"],contract=contract,source_state=state["state"],source_state_version=int(state["state_version"]),source_version_sha256=vector["version_sha256"],evaluated_by=normalized["evaluated_by"],reason=normalized.get("reason"),evaluated_at=now)
        self._record_mission_success_evaluation_event(row)
        return self._mission_success_evaluation_response(row,idempotent_replay=False)

