    @_serialized_mission_mutation
    def evaluate_completion_readiness(self, mission_id: str, payload: Any) -> Dict[str, Any]:
        if self.repository.get_by_mission_id(mission_id) is None: raise MissionNotFound(mission_id)
        normalized=normalize_completion_readiness_request(payload); req_hash=completion_readiness_request_fingerprint(normalized)
        replay=self.repository.get_completion_readiness_by_idempotency(mission_id,normalized["idempotency_key"])
        if replay is not None:
            if replay["request_sha256"] != req_hash: raise MissionCompletionReadinessConflict("completion readiness idempotency_key was already used with a different canonical request")
            self._record_completion_readiness_event(replay); return self._completion_readiness_response(replay,idempotent_replay=True)
        state=self.repository.get_state(mission_id)
        if state is None or state["state"] not in COMPLETION_READINESS_ALLOWED_MISSION_STATES:
            raise MissionCompletionReadinessGuardRejected("Stage-3.6.7 completion readiness requires Mission state RUNNING, FAILED, or ABORTED")
        if int(state["state_version"]) != int(normalized["expected_state_version"]): raise MissionConcurrencyConflict("completion readiness expected_state_version is stale")
        vector=self.get_mission_version_vector(mission_id)
        if vector["version_sha256"] != normalized["expected_version_sha256"]: raise MissionConcurrencyConflict("completion readiness expected_version_sha256 is stale")
        head=self.repository.get_plan_version_head(mission_id)
        if head is None or head["active_plan_version_record_id"] != normalized["expected_active_plan_version_record_id"] or int(head["active_plan_version"]) != int(normalized["expected_active_plan_version"]) or head["active_plan_sha256"] != normalized["expected_active_plan_sha256"]:
            raise MissionConcurrencyConflict("active Plan head changed before completion readiness evaluation")
        active_plan=next((x for x in self.repository.list_plan_versions(mission_id) if x["plan_version_record_id"]==head["active_plan_version_record_id"]),None)
        if active_plan is None: raise MissionCompletionReadinessGuardRejected("active Plan version record is missing")
        evaluation=self.repository.get_mission_success_evaluation(mission_id,normalized["expected_evaluation_id"])
        if evaluation is None: raise MissionCompletionReadinessGuardRejected("referenced Stage-3.6.6 success criteria evaluation is missing")
        if evaluation["canonical_sha256"] != normalized["expected_evaluation_sha256"]: raise MissionConcurrencyConflict("referenced Stage-3.6.6 evaluation hash changed or mismatched")
        if evaluation["plan_version_record_id"] != active_plan["plan_version_record_id"] or int(evaluation["plan_version"]) != int(active_plan["plan_version"]): raise MissionCompletionReadinessGuardRejected("referenced Stage-3.6.6 evaluation belongs to a stale/superseded Plan")
        now=utcnow_iso(); readiness_id=new_completion_readiness_id()
        try:
            contract=build_completion_readiness_contract(readiness_id=readiness_id,mission_id=mission_id,request=normalized,request_sha256=req_hash,source_state=state,source_version_sha256=vector["version_sha256"],active_plan=active_plan,evaluation=evaluation,decided_at=now)
        except MissionValidationError as exc: raise MissionCompletionReadinessGuardRejected(str(exc)) from exc
        if not verify_completion_readiness_contract(contract): raise MissionCompletionReadinessGuardRejected("Stage-3.6.7 completion readiness contract failed self-verification")
        row=self.repository.store_completion_readiness(mission_id=mission_id,readiness_id=readiness_id,plan_version_record_id=active_plan["plan_version_record_id"],plan_version=int(active_plan["plan_version"]),evaluation_id=evaluation["evaluation_id"],request_sha256=req_hash,idempotency_key=normalized["idempotency_key"],contract=contract,source_state=state["state"],source_state_version=int(state["state_version"]),source_version_sha256=vector["version_sha256"],decided_by=normalized["decided_by"],reason=normalized.get("reason"),decided_at=now)
        self._record_completion_readiness_event(row); return self._completion_readiness_response(row,idempotent_replay=False)

