        if self.repository.get_by_mission_id(mission_id) is None: raise MissionNotFound(mission_id)
        row=self.repository.get_completion_readiness(mission_id,readiness_id)
        if row is None: raise MissionCompletionReadinessNotFound(readiness_id)
        return self._completion_readiness_response(row,idempotent_replay=False)

