    def _record_verified_completion_declared_event(self, stored: Dict[str, Any]) -> Dict[str, Any]:
        return self._record_mission_event(
            stored["mission_id"],
            "MISSION_VERIFIED_COMPLETION_DECLARED",
            stored["declaration_id"],
            payload={
                "declaration_id": stored["declaration_id"],
                "readiness_id": stored["readiness_id"],
                "evaluation_id": stored["evaluation_id"],
                "declaration_status": stored["declaration_status"],
                "readiness_sha256": stored["readiness_sha256"],
                "evaluation_sha256": stored["evaluation_sha256"],
                "canonical_sha256": stored["canonical_sha256"],
                "declaration_persisted_before_lifecycle_handoff": True,
                "direct_state_transition_bypass_used": False,
            },
            occurred_at=stored["declared_at"],
            state_version=int(stored["source_state_version"]),
            plan_version=int(stored["plan_version"]),
        )

    def _verified_completion_command(self, stored: Dict[str, Any], command: str) -> Dict[str, Any] | None:
        plan = stored["verified_completion_contract"]["lifecycle_handoff_plan"]
        command_id = plan["begin_cleanup_command_id"] if command == "BEGIN_CLEANUP" else plan["complete_command_id"]
        row = self.repository.get_mission_command(stored["mission_id"], command_id)
        if row is None:
            return None
        out = self._mission_command_payload(row, idempotent_replay=False)
        result = out.get("result") or {}
        out["status"] = out.get("command_status") or out.get("status")
        for key in ("mission_state", "transition", "lifecycle_guard", "cleanup_control", "completion_verification", "terminal_control"):
            out[key] = result.get(key)
        out["lifecycle_command"] = (result.get("lifecycle_guard") or {}).get("command") or (row.get("metadata") or {}).get("lifecycle_command")
        return out

    def _verified_completion_response(self, stored: Dict[str, Any], *, idempotent_replay: bool) -> Dict[str, Any]:
        contract = stored["verified_completion_contract"]
        if not verify_verified_completion_contract(contract):
            raise RuntimeError("persisted Stage-3.6.8 verified completion declaration contract integrity verification failed")
        state = self.repository.get_state(stored["mission_id"])
        cleanup_command = self._verified_completion_command(stored, "BEGIN_CLEANUP")
        complete_command = self._verified_completion_command(stored, "COMPLETE")
        final_completed = bool(state is not None and state["state"] == VERIFIED_COMPLETION_FINAL_STATE and complete_command is not None and complete_command.get("command_status") == "COMPLETED")
        boundary = contract["authority_boundary"]
        vc = contract["verified_completion"]
        return {
            "status": "completed" if final_completed else "declared",
            "component_id": COMPONENT_ID,
            "control_version": CONTROL_VERSION,
            "idempotent_replay": bool(idempotent_replay),
            "mission_id": stored["mission_id"],
            "declaration_id": stored["declaration_id"],
            "declaration_status": stored["declaration_status"],
            "verification_status": vc["verification_status"],
            "readiness_id": stored["readiness_id"],
            "evaluation_id": stored["evaluation_id"],
            "plan_version_record_id": stored["plan_version_record_id"],
            "plan_version": int(stored["plan_version"]),
            "canonical_sha256": stored["canonical_sha256"],
            "success_criteria_count": int(vc["success_criteria_count"]),
            "verified_completion_contract": contract,
            "cleanup_command": cleanup_command,
            "complete_command": complete_command,
            "lifecycle_handoff_performed": final_completed,
            "stage32_lifecycle_command_path_used": bool(cleanup_command is not None or complete_command is not None),
            "lifecycle_handoff_commands": list(LIFECYCLE_HANDOFF_COMMANDS),
            "final_mission_state": None if state is None else dict(state),
            "mission_state_transition_performed": bool(cleanup_command is not None or complete_command is not None),
            **{k: bool(v) for k, v in boundary.items()},
        }

    def _resume_verified_completion_handoff(self, stored: Dict[str, Any], *, idempotent_replay: bool) -> Dict[str, Any]:
        contract = stored["verified_completion_contract"]
        if not verify_verified_completion_contract(contract):
            raise MissionVerifiedCompletionGuardRejected("Stage-3.6.8 verified completion declaration failed integrity verification")
        state = self.repository.get_state(stored["mission_id"])
        if state is None:
            raise MissionVerifiedCompletionGuardRejected("canonical Mission state is missing")
        plan = contract["lifecycle_handoff_plan"]
        actor = contract["request"]["declared_by"]
        reason = contract["request"].get("reason") or "Stage 3.6.8 verified completion lifecycle handoff"

        if state["state"] == "RUNNING":
            vector = self.get_mission_version_vector(stored["mission_id"])
            self.execute_mission_lifecycle_command(
                stored["mission_id"],
                {
                    "command_id": plan["begin_cleanup_command_id"],
                    "idempotency_key": plan["begin_cleanup_idempotency_key"],
                    "expected_version_sha256": vector["version_sha256"],
                    "command": "BEGIN_CLEANUP",
                    "expected_state_version": int(state["state_version"]),
                    "actor": actor,
                    "reason_code": "STAGE3_6_8_VERIFIED_COMPLETION_BEGIN_CLEANUP",
                    "reason": reason,
                    "evidence_refs": [f"stage3.6.8:declaration:{stored['declaration_id']}:{stored['canonical_sha256']}"],
                    "metadata": {"stage": "3.6.8", "verified_completion_declaration_id": stored["declaration_id"]},
                },
            )
            state = self.repository.get_state(stored["mission_id"])

        if state is not None and state["state"] == "CLEANING_UP":
            evidence = completion_evidence_refs(contract)
            vector = self.get_mission_version_vector(stored["mission_id"])
            self.execute_mission_lifecycle_command(
                stored["mission_id"],
                {
                    "command_id": plan["complete_command_id"],
                    "idempotency_key": plan["complete_idempotency_key"],
                    "expected_version_sha256": vector["version_sha256"],
                    "command": "COMPLETE",
                    "expected_state_version": int(state["state_version"]),
                    "actor": actor,
                    "reason_code": "STAGE3_6_8_VERIFIED_COMPLETION_COMPLETE",
                    "reason": reason,
                    "evidence_refs": evidence["evidence_refs"],
                    "metadata": {"stage": "3.6.8", "verified_completion_declaration_id": stored["declaration_id"], "completion": evidence["completion"]},
                },
            )
            state = self.repository.get_state(stored["mission_id"])

        if state is None or state["state"] != VERIFIED_COMPLETION_FINAL_STATE:
            raise MissionVerifiedCompletionGuardRejected(
                f"Stage-3.6.8 lifecycle handoff cannot resume from Mission state={None if state is None else state['state']}"
            )

        handoff_event = self._record_mission_event(
            stored["mission_id"],
            "MISSION_COMPLETION_LIFECYCLE_HANDOFF_COMPLETED",
            stored["declaration_id"],
            payload={
                "declaration_id": stored["declaration_id"],
                "lifecycle_handoff_commands": list(LIFECYCLE_HANDOFF_COMMANDS),
                "final_mission_state": VERIFIED_COMPLETION_FINAL_STATE,
                "stage32_lifecycle_command_path_used": True,
                "direct_state_transition_bypass_used": False,
                "canonical_sha256": stored["canonical_sha256"],
            },
            state_version=int(state["state_version"]),
            plan_version=int(stored["plan_version"]),
        )
        _ = handoff_event
        return self._verified_completion_response(stored, idempotent_replay=idempotent_replay)

    @_serialized_mission_mutation
    def declare_verified_completion(self, mission_id: str, payload: Any) -> Dict[str, Any]:
        if self.repository.get_by_mission_id(mission_id) is None:
            raise MissionNotFound(mission_id)
        normalized = normalize_verified_completion_request(payload)
        req_hash = verified_completion_request_fingerprint(normalized)
        replay = self.repository.get_verified_completion_by_idempotency(mission_id, normalized["idempotency_key"])
        if replay is not None:
            if replay["request_sha256"] != req_hash:
                raise MissionVerifiedCompletionConflict("verified completion idempotency_key was already used with a different canonical request")
            self._record_verified_completion_declared_event(replay)
            return self._resume_verified_completion_handoff(replay, idempotent_replay=True)

        state = self.repository.get_state(mission_id)
        if state is None or state["state"] != VERIFIED_COMPLETION_ALLOWED_SOURCE_STATE:
            raise MissionVerifiedCompletionGuardRejected("Stage-3.6.8 verified completion declaration requires Mission state RUNNING")
        if int(state["state_version"]) != int(normalized["expected_state_version"]):
            raise MissionConcurrencyConflict("verified completion expected_state_version is stale")
        vector = self.get_mission_version_vector(mission_id)
        if vector["version_sha256"] != normalized["expected_version_sha256"]:
            raise MissionConcurrencyConflict("verified completion expected_version_sha256 is stale")
        head = self.repository.get_plan_version_head(mission_id)
        if head is None or head["active_plan_version_record_id"] != normalized["expected_active_plan_version_record_id"] or int(head["active_plan_version"]) != int(normalized["expected_active_plan_version"]) or head["active_plan_sha256"] != normalized["expected_active_plan_sha256"]:
            raise MissionConcurrencyConflict("active Plan head changed before verified completion declaration")
        active_plan = next((x for x in self.repository.list_plan_versions(mission_id) if x["plan_version_record_id"] == head["active_plan_version_record_id"]), None)
        if active_plan is None:
            raise MissionVerifiedCompletionGuardRejected("active Plan version record is missing")
        readiness = self.repository.get_completion_readiness(mission_id, normalized["expected_readiness_id"])
        if readiness is None:
            raise MissionVerifiedCompletionGuardRejected("referenced Stage-3.6.7 completion readiness decision is missing")
        if readiness["canonical_sha256"] != normalized["expected_readiness_sha256"]:
            raise MissionConcurrencyConflict("referenced Stage-3.6.7 readiness hash changed or mismatched")
        if readiness["plan_version_record_id"] != active_plan["plan_version_record_id"] or int(readiness["plan_version"]) != int(active_plan["plan_version"]):
            raise MissionVerifiedCompletionGuardRejected("referenced Stage-3.6.7 readiness belongs to a stale/superseded Plan")
        evaluation = self.repository.get_mission_success_evaluation(mission_id, readiness["evaluation_id"])
        if evaluation is None:
            raise MissionVerifiedCompletionGuardRejected("referenced Stage-3.6.6 success criteria evaluation is missing")
        aggregation = self.repository.get_mission_outcome_aggregation(mission_id, evaluation["aggregation_id"])
        if aggregation is None:
            raise MissionVerifiedCompletionGuardRejected("referenced Stage-3.6.5 mission outcome aggregation is missing")
        now = utcnow_iso()
        declaration_id = new_verified_completion_declaration_id()
        try:
            contract = build_verified_completion_contract(
                declaration_id=declaration_id,
                mission_id=mission_id,
                request=normalized,
                request_sha256=req_hash,
                source_state=state,
                source_version_sha256=vector["version_sha256"],
                active_plan=active_plan,
                readiness=readiness,
                evaluation=evaluation,
                aggregation=aggregation,
                declared_at=now,
            )
        except MissionValidationError as exc:
            raise MissionVerifiedCompletionGuardRejected(str(exc)) from exc
        if not verify_verified_completion_contract(contract):
            raise MissionVerifiedCompletionGuardRejected("Stage-3.6.8 verified completion declaration contract failed self-verification")
        row = self.repository.store_verified_completion_declaration(
            mission_id=mission_id,
            declaration_id=declaration_id,
            plan_version_record_id=active_plan["plan_version_record_id"],
            plan_version=int(active_plan["plan_version"]),
            readiness_id=readiness["readiness_id"],
            evaluation_id=evaluation["evaluation_id"],
            request_sha256=req_hash,
            idempotency_key=normalized["idempotency_key"],
            contract=contract,
            source_state=state["state"],
            source_state_version=int(state["state_version"]),
            source_version_sha256=vector["version_sha256"],
            declared_by=normalized["declared_by"],
            reason=normalized.get("reason"),
            declared_at=now,
        )
        self._record_verified_completion_declared_event(row)
        return self._resume_verified_completion_handoff(row, idempotent_replay=False)

    def get_verified_completion_declaration(self, mission_id: str, declaration_id: str) -> Dict[str, Any]:
        if self.repository.get_by_mission_id(mission_id) is None:
            raise MissionNotFound(mission_id)
        row = self.repository.get_verified_completion_declaration(mission_id, declaration_id)
        if row is None:
            raise MissionVerifiedCompletionNotFound(declaration_id)
        return self._verified_completion_response(row, idempotent_replay=False)

