    @_serialized_mission_mutation
    def classify_adaptation_trigger(self, mission_id: str, adaptation_episode_id: str, payload: Any) -> Dict[str, Any]:
        if self.repository.get_by_mission_id(mission_id) is None:
            raise MissionNotFound(mission_id)
        normalized = normalize_adaptation_trigger_classification_request(payload)
        if normalized["expected_adaptation_episode_id"] != adaptation_episode_id:
            raise MissionAdaptationTriggerClassificationGuardRejected(
                "expected_adaptation_episode_id does not match the classification route"
            )
        req_hash = adaptation_trigger_classification_request_fingerprint(normalized)
        existing = self.repository.get_adaptation_trigger_classification_by_idempotency(
            mission_id, normalized["idempotency_key"]
        )
        if existing is not None:
            if existing["request_sha256"] != req_hash:
                raise MissionAdaptationTriggerClassificationConflict(
                    "adaptation trigger classification idempotency_key was already used with different canonical request material"
                )
            self._record_adaptation_trigger_classification_event(existing)
            return self._adaptation_trigger_classification_response(existing, idempotent_replay=True)

        source = self.repository.get_adaptation_replan(mission_id, adaptation_episode_id)
        if source is None:
            raise MissionAdaptationReplanNotFound(adaptation_episode_id)
        if source["replan_trigger_id"] != normalized["expected_replan_trigger_id"]:
            raise MissionAdaptationTriggerClassificationGuardRejected("expected_replan_trigger_id does not match Stage-3.7.1 source")
        if source["canonical_sha256"] != normalized["expected_adaptation_replan_sha256"]:
            raise MissionConcurrencyConflict("Stage-3.7.1 adaptation/replan contract hash changed or mismatched")
        if not verify_adaptation_replan_contract(source["adaptation_replan_contract"]):
            raise MissionAdaptationTriggerClassificationGuardRejected("Stage-3.7.1 source contract failed integrity verification")
        already = self.repository.get_adaptation_trigger_classification_by_episode(mission_id, adaptation_episode_id)
        if already is not None:
            raise MissionAdaptationTriggerClassificationConflict("adaptation episode is already classified")

        detection_event = self.repository.get_mission_event_by_causation(
            mission_id, "MISSION_ADAPTATION_REPLAN_DETECTED", adaptation_episode_id
        )
        if detection_event is None:
            raise MissionAdaptationTriggerClassificationGuardRejected("Stage-3.7.1 detection event is missing")
        if not verify_event(detection_event):
            raise MissionEventIntegrityError("Stage-3.7.1 detection event failed integrity verification")
        if detection_event["canonical_sha256"] != normalized["expected_detection_event_sha256"]:
            raise MissionConcurrencyConflict("Stage-3.7.1 detection event hash changed or mismatched")
        detection_payload = detection_event.get("payload") or {}
        if (
            detection_event.get("causation_id") != adaptation_episode_id
            or detection_payload.get("replan_trigger_id") != source["replan_trigger_id"]
            or detection_payload.get("canonical_sha256") != source["canonical_sha256"]
        ):
            raise MissionAdaptationTriggerClassificationGuardRejected("Stage-3.7.1 detection event does not bind the source contract")

        state = self.repository.get_state(mission_id)
        if state is None:
            raise MissionAdaptationTriggerClassificationGuardRejected("current Mission state is missing")
        if int(state["state_version"]) != int(normalized["expected_state_version"]):
            raise MissionConcurrencyConflict("adaptation trigger classification expected_state_version is stale")
        vector = self.get_mission_version_vector(mission_id)
        if vector["version_sha256"] != normalized["expected_version_sha256"]:
            raise MissionConcurrencyConflict("adaptation trigger classification expected_version_sha256 is stale")
        source_contract = source["adaptation_replan_contract"]
        source_binding = source_contract["source_bindings"]
        if (
            state["state"] != source_binding["source_state"]
            or int(state["state_version"]) != int(source_binding["source_state_version"])
            or vector["version_sha256"] != source_binding["source_version_sha256"]
        ):
            raise MissionAdaptationTriggerClassificationGuardRejected(
                "Mission state/version changed since Stage-3.7.1 detection; classify only the exact detected state"
            )

        head = self.repository.get_plan_version_head(mission_id)
        if (
            head is None
            or head["active_plan_version_record_id"] != normalized["expected_active_plan_version_record_id"]
            or int(head["active_plan_version"]) != int(normalized["expected_active_plan_version"])
            or head["active_plan_sha256"] != normalized["expected_active_plan_sha256"]
        ):
            raise MissionConcurrencyConflict("active Plan head changed before adaptation trigger classification")
        active_plan = self.repository.get_active_plan_version(mission_id)
        if active_plan is None or not verify_plan_version_contract(active_plan["plan_version_contract"]):
            raise MissionAdaptationTriggerClassificationGuardRejected("active Stage-3.3.7 Plan version is missing or failed integrity verification")
        if (
            active_plan["plan_version_record_id"] != source["source_plan_version_record_id"]
            or int(active_plan["plan_version"]) != int(source["source_plan_version"])
            or active_plan["canonical_sha256"] != source_contract["source_bindings"]["source_plan_sha256"]
        ):
            raise MissionAdaptationTriggerClassificationGuardRejected(
                "active Plan no longer matches the exact Plan generation bound by Stage-3.7.1 detection"
            )

        classification_id = new_adaptation_trigger_classification_id()
        now = utcnow_iso()
        try:
            contract = build_adaptation_trigger_classification_contract(
                classification_id=classification_id,
                mission_id=mission_id,
                request=normalized,
                request_sha256=req_hash,
                adaptation_replan=source,
                detection_event=detection_event,
                current_state=state,
                current_version_sha256=vector["version_sha256"],
                active_plan=active_plan,
                classified_at=now,
            )
        except MissionValidationError as exc:
            raise MissionAdaptationTriggerClassificationGuardRejected(str(exc)) from exc
        if not verify_adaptation_trigger_classification_contract(contract):
            raise MissionAdaptationTriggerClassificationGuardRejected(
                "Stage-3.7.2 canonical adaptation trigger classification contract failed self-verification"
            )

        trigger = contract["trigger_classification"]
        source_bindings = contract["source_bindings"]
        row = self.repository.store_adaptation_trigger_classification(
            mission_id=mission_id,
            classification_id=classification_id,
            adaptation_episode_id=adaptation_episode_id,
            replan_trigger_id=source["replan_trigger_id"],
            source_plan_version_record_id=active_plan["plan_version_record_id"],
            source_plan_version=int(active_plan["plan_version"]),
            source_plan_generation=int(source_bindings["source_plan_generation"]),
            canonical_plan_id=active_plan["canonical_plan_id"],
            request_sha256=req_hash,
            idempotency_key=normalized["idempotency_key"],
            contract=contract,
            source_state=state["state"],
            source_state_version=int(state["state_version"]),
            source_version_sha256=vector["version_sha256"],
            reason_code=trigger["reason_code"],
            severity=trigger["severity"],
            replan_scope_level=trigger["replan_scope_level"],
            source_stage=trigger["source_stage"],
            source_event_id=trigger.get("source_event_id"),
            source_event_sha256=None if source_bindings.get("source_event") is None else source_bindings["source_event"].get("canonical_sha256"),
            evidence_refs=list(trigger["evidence_refs"]),
            detection_event_id=detection_event["event_id"],
            detection_event_sha256=detection_event["canonical_sha256"],
            source_adaptation_replan_sha256=source["canonical_sha256"],
            classified_by=normalized["classified_by"],
            reason=normalized.get("reason"),
            classified_at=now,
        )
        self._record_adaptation_trigger_classification_event(row)
        return self._adaptation_trigger_classification_response(row, idempotent_replay=False)

    def get_adaptation_trigger_classification(self, mission_id: str, classification_id: str) -> Dict[str, Any]:
        if self.repository.get_by_mission_id(mission_id) is None:
            raise MissionNotFound(mission_id)
        row = self.repository.get_adaptation_trigger_classification(mission_id, classification_id)
        if row is None:
            raise MissionAdaptationTriggerClassificationNotFound(classification_id)
        return self._adaptation_trigger_classification_response(row, idempotent_replay=False)

    def get_adaptation_trigger_classification_for_episode(self, mission_id: str, adaptation_episode_id: str) -> Dict[str, Any]:
        if self.repository.get_by_mission_id(mission_id) is None:
            raise MissionNotFound(mission_id)
        if self.repository.get_adaptation_replan(mission_id, adaptation_episode_id) is None:
            raise MissionAdaptationReplanNotFound(adaptation_episode_id)
        row = self.repository.get_adaptation_trigger_classification_by_episode(mission_id, adaptation_episode_id)
        if row is None:
            raise MissionAdaptationTriggerClassificationNotFound(adaptation_episode_id)
        return self._adaptation_trigger_classification_response(row, idempotent_replay=False)

    def get_adaptation_trigger_classification_history(self, mission_id: str) -> Dict[str, Any]:
        if self.repository.get_by_mission_id(mission_id) is None:
            raise MissionNotFound(mission_id)
        rows = self.repository.list_adaptation_trigger_classifications(mission_id)
        return {
            "status": "completed",
            "component_id": COMPONENT_ID,
            "control_version": CONTROL_VERSION,
            "mission_id": mission_id,
            "classification_count": len(rows),
            "classifications": [
                self._adaptation_trigger_classification_response(x, idempotent_replay=False) for x in rows
            ],
        }

    def get_adaptation_trigger_classification_definition(self, mission_id: str) -> Dict[str, Any]:
        if self.repository.get_by_mission_id(mission_id) is None:
            raise MissionNotFound(mission_id)
        return {
            "status": "completed",
            "component_id": COMPONENT_ID,
            "control_version": CONTROL_VERSION,
            "mission_id": mission_id,
            "registered_classification_count": len(self.repository.list_adaptation_trigger_classifications(mission_id)),
            "adaptation_trigger_classification_definition": canonical_adaptation_trigger_classification_definition(),
        }

    @staticmethod
    def _replan_eligibility_response(stored: Dict[str, Any], *, idempotent_replay: bool, event: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
        contract = stored["replan_eligibility_governance_contract"]
        if not verify_replan_eligibility_contract(contract):
            raise RuntimeError("persisted Stage-3.7.3 replan eligibility/governance contract integrity verification failed")
        eligibility = contract["eligibility"]
        governance = contract["governance_decision"]
        static = contract["static_eligibility"]
        boundary = contract["authority_boundary"]
        return {
            "status": "completed",
            "component_id": COMPONENT_ID,
            "control_version": CONTROL_VERSION,
            "idempotent_replay": bool(idempotent_replay),
            "mission_id": stored["mission_id"],
            "eligibility_gate_id": stored["eligibility_gate_id"],
            "classification_id": stored["classification_id"],
            "adaptation_episode_id": stored["adaptation_episode_id"],
            "replan_trigger_id": stored["replan_trigger_id"],
            "source_plan_version_record_id": stored["source_plan_version_record_id"],
            "source_plan_version": int(stored["source_plan_version"]),
            "static_eligibility_status": static["status"],
            "eligibility_status": eligibility["eligibility_status"],
            "replan_eligible": bool(eligibility["replan_eligible"]),
            "effective_episode_state": eligibility["effective_episode_state"],
            "governance_decision": governance["decision"],
            "policy_decision_id": governance["decision_id"],
            "policy_decision_hash": governance["decision_hash"],
            "policy_version": int(governance["policy_version"]),
            "canonical_sha256": stored["canonical_sha256"],
            "replan_eligibility_governance_contract": contract,
            "eligibility_event": event,
            "governance_query_performed": True,
            "authoritative_governance_bound": True,
            "lifecycle_replan_requested": boundary["lifecycle_replan_requested"],
            "replan_snapshot_bound": boundary["replan_snapshot_bound"],
            "planner_invocation_performed": boundary["planner_invocation_performed"],
            "replan_candidate_created": boundary["replan_candidate_created"],
            "plan_delta_computed": boundary["plan_delta_computed"],
            "plan_validation_performed": boundary["plan_validation_performed"],
            "replan_decision_committed": boundary["replan_decision_committed"],
            "plan_supersession_performed": boundary["plan_supersession_performed"],
            "mission_state_transition_performed": boundary["mission_state_transition_performed"],
            "dispatch_performed": boundary["dispatch_performed"],
            "target_actuation": boundary["target_actuation"],
        }

    def _record_replan_eligibility_event(self, stored: Dict[str, Any]) -> Dict[str, Any]:
        contract = stored["replan_eligibility_governance_contract"]
        eligibility = contract["eligibility"]
        governance = contract["governance_decision"]
