    @staticmethod
    def _replan_candidate_response(stored: Dict[str, Any], *, idempotent_replay: bool, event: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
        contract = stored["replan_candidate_contract"]
        if not verify_replan_candidate_contract(contract):
            raise RuntimeError("persisted Stage-3.7.5 deterministic ReplanCandidate integrity verification failed")
        candidate = contract["candidate_successor_plan"]
        boundary = contract["authority_boundary"]
        invocation = contract["planner_invocation"]
        return {
            "status": "completed",
            "component_id": COMPONENT_ID,
            "control_version": CONTROL_VERSION,
            "idempotent_replay": bool(idempotent_replay),
            "mission_id": stored["mission_id"],
            "replan_candidate_id": stored["replan_candidate_id"],
            "planner_invocation_id": stored["planner_invocation_id"],
            "replan_snapshot_id": stored["replan_snapshot_id"],
            "adaptation_episode_id": stored["adaptation_episode_id"],
            "source_plan_version_record_id": stored["source_plan_version_record_id"],
            "source_plan_version": int(stored["source_plan_version"]),
            "candidate_plan_version": int(stored["candidate_plan_version"]),
            "candidate_plan_generation": int(stored["candidate_plan_generation"]),
            "candidate_status": stored["candidate_status"],
            "candidate_only": bool(candidate["candidate_only"]),
            "candidate_task_count": int(candidate["candidate_task_count"]),
            "candidate_dependency_edge_count": int(candidate["candidate_dependency_edge_count"]),
            "completed_source_task_count": int(candidate["completed_source_task_count"]),
            "candidate_payload_sha256": stored["candidate_payload_sha256"],
            "planner_invocation_sha256": stored["planner_invocation_sha256"],
            "canonical_sha256": stored["canonical_sha256"],
            "replan_candidate_contract": contract,
            "candidate_event": event,
            "planner_profile": invocation["planner_profile"],
            "deterministic": bool(invocation["deterministic"]),
            "external_context_refresh_performed": boundary["external_context_refresh_performed"],
            "governance_query_performed": boundary["governance_query_performed"],
            "planner_invocation_performed": boundary["planner_invocation_performed"],
            "replan_candidate_created": boundary["replan_candidate_created"],
            "plan_delta_computed": boundary["plan_delta_computed"],
            "successor_plan_created": boundary["successor_plan_created"],
            "plan_validation_performed": boundary["plan_validation_performed"],
            "replan_decision_committed": boundary["replan_decision_committed"],
            "plan_supersession_performed": boundary["plan_supersession_performed"],
            "mission_state_transition_performed": boundary["mission_state_transition_performed"],
            "dispatch_performed": boundary["dispatch_performed"],
            "target_actuation": boundary["target_actuation"],
        }

    def _record_replan_candidate_event(self, stored: Dict[str, Any]) -> Dict[str, Any]:
        contract = stored["replan_candidate_contract"]
        candidate = contract["candidate_successor_plan"]
        boundary = contract["authority_boundary"]
        return self._record_mission_event(
            stored["mission_id"],
            REPLAN_CANDIDATE_EVENT_TYPE,
            stored["replan_candidate_id"],
            payload={
                "replan_candidate_id": stored["replan_candidate_id"],
                "planner_invocation_id": stored["planner_invocation_id"],
                "replan_snapshot_id": stored["replan_snapshot_id"],
                "adaptation_episode_id": stored["adaptation_episode_id"],
                "candidate_status": stored["candidate_status"],
                "source_plan_version": int(stored["source_plan_version"]),
                "candidate_plan_version": int(stored["candidate_plan_version"]),
                "candidate_plan_generation": int(stored["candidate_plan_generation"]),
                "candidate_task_count": int(candidate["candidate_task_count"]),
                "candidate_dependency_edge_count": int(candidate["candidate_dependency_edge_count"]),
                "completed_source_task_count": int(candidate["completed_source_task_count"]),
                "candidate_payload_sha256": stored["candidate_payload_sha256"],
                "planner_invocation_sha256": stored["planner_invocation_sha256"],
                "canonical_sha256": stored["canonical_sha256"],
                "deterministic": True,
                "candidate_only": True,
                "external_context_refresh_performed": False,
                "governance_query_performed": False,
                "planner_invocation_performed": True,
                "replan_candidate_created": True,
                "plan_delta_computed": True,
                "successor_plan_created": False,
                "plan_validation_performed": False,
                "replan_decision_committed": False,
                "plan_supersession_performed": False,
                "mission_state_transition_performed": False,
                "dispatch_performed": False,
                "target_actuation": False,
            },
            occurred_at=stored["generated_at"],
            state_version=int(stored["source_state_version"]),
            plan_version=int(stored["source_plan_version"]),
        )

    @_serialized_mission_mutation
    def generate_replan_candidate(self, mission_id: str, replan_snapshot_id: str, payload: Any) -> Dict[str, Any]:
        if self.repository.get_by_mission_id(mission_id) is None:
            raise MissionNotFound(mission_id)
        normalized = normalize_replan_candidate_request(payload)
        if normalized["expected_replan_snapshot_id"] != replan_snapshot_id:
            raise MissionReplanCandidateGuardRejected("expected_replan_snapshot_id does not match the ReplanSnapshot route")
        req_hash = replan_candidate_request_fingerprint(normalized)

        replay = self.repository.get_replan_candidate_by_idempotency(mission_id, normalized["idempotency_key"])
        if replay is not None:
            if replay["request_sha256"] != req_hash:
                raise MissionReplanCandidateConflict("replan candidate idempotency_key was already used with different request material")
            event = self._record_replan_candidate_event(replay)
            return self._replan_candidate_response(replay, idempotent_replay=True, event=event)

        if self.repository.get_replan_candidate_by_snapshot(mission_id, replan_snapshot_id) is not None:
            raise MissionReplanCandidateConflict("ReplanSnapshot already has a deterministic ReplanCandidate")
        snapshot = self.repository.get_replan_snapshot(mission_id, replan_snapshot_id)
        if snapshot is None:
            raise MissionReplanSnapshotNotFound(replan_snapshot_id)
        if not verify_replan_snapshot_contract(snapshot["replan_snapshot_contract"]):
            raise MissionReplanCandidateGuardRejected("Stage-3.7.4 ReplanSnapshot failed integrity verification")
        if snapshot["snapshot_status"] != "SNAPSHOT_BOUND":
            raise MissionReplanCandidateGuardRejected("Stage-3.7.4 ReplanSnapshot is not SNAPSHOT_BOUND")

        if snapshot["canonical_sha256"] != normalized["expected_replan_snapshot_sha256"]:
            raise MissionConcurrencyConflict("Stage-3.7.4 ReplanSnapshot hash changed before candidate generation")
        if snapshot["task_context_sha256"] != normalized["expected_task_context_sha256"]:
            raise MissionConcurrencyConflict("Stage-3.7.4 task context hash changed before candidate generation")
        if snapshot["source_plan_version_record_id"] != normalized["expected_source_plan_version_record_id"]:
            raise MissionConcurrencyConflict("source Plan-version identity changed before candidate generation")
        if int(snapshot["source_plan_version"]) != int(normalized["expected_source_plan_version"]):
            raise MissionConcurrencyConflict("source Plan version changed before candidate generation")
        contract = snapshot["replan_snapshot_contract"]
        src = contract["source_bindings"]
        if src["source_plan_sha256"] != normalized["expected_source_plan_sha256"]:
            raise MissionConcurrencyConflict("source Plan hash changed before candidate generation")
        if int(src["source_state_version"]) != int(normalized["expected_source_state_version"]):
            raise MissionConcurrencyConflict("source Mission state version changed before candidate generation")
        if src["source_version_sha256"] != normalized["expected_source_version_sha256"]:
            raise MissionConcurrencyConflict("source Mission version hash changed before candidate generation")

        # Stage 3.7.5 is deliberately bound to the current predecessor Plan head. A head change
        # means another control advanced planning and this candidate must fail closed.
        active = self.repository.get_active_plan_version(mission_id)
        if active is None:
            raise MissionReplanCandidateGuardRejected("active Plan-version head is unavailable")
        if (active["plan_version_record_id"] != src["source_plan_version_record_id"]
                or int(active["plan_version"]) != int(src["source_plan_version"])
                or active["canonical_sha256"] != src["source_plan_sha256"]):
            raise MissionConcurrencyConflict("active Plan head changed after ReplanSnapshot capture")

        state = self.repository.get_state(mission_id)
        vector = self.get_mission_version_vector(mission_id)
        if state is None or vector is None:
            raise MissionReplanCandidateGuardRejected("Mission state/version is unavailable")
        if (state["state"] != src["source_state"]
                or int(state["state_version"]) != int(src["source_state_version"])
                or vector["version_sha256"] != src["source_version_sha256"]):
            raise MissionConcurrencyConflict("Mission state/version changed after ReplanSnapshot capture")

        generated_at = utcnow_iso()
        candidate_contract = build_replan_candidate_contract(
            replan_candidate_id=new_replan_candidate_id(),
            planner_invocation_id=new_replan_planner_invocation_id(),
            mission_id=mission_id,
            request=normalized,
            request_sha256=req_hash,
            snapshot_record=snapshot,
            generated_at=generated_at,
        )
        if not verify_replan_candidate_contract(candidate_contract):
            raise MissionReplanCandidateGuardRejected("Stage-3.7.5 deterministic ReplanCandidate failed self-verification")
        stored = self.repository.store_replan_candidate(
            contract=candidate_contract,
            request_sha256=req_hash,
            idempotency_key=normalized["idempotency_key"],
            generated_by=normalized["generated_by"],
            reason=normalized.get("reason"),
            generated_at=generated_at,
        )
        event = self._record_replan_candidate_event(stored)
        return self._replan_candidate_response(stored, idempotent_replay=False, event=event)

    def get_replan_candidate(self, mission_id: str, replan_candidate_id: str) -> Dict[str, Any]:
        if self.repository.get_by_mission_id(mission_id) is None:
            raise MissionNotFound(mission_id)
        row = self.repository.get_replan_candidate(mission_id, replan_candidate_id)
        if row is None:
            raise MissionReplanCandidateNotFound(replan_candidate_id)
        event = self.repository.get_mission_event_by_causation(mission_id, REPLAN_CANDIDATE_EVENT_TYPE, replan_candidate_id)
        return self._replan_candidate_response(row, idempotent_replay=False, event=event)

