    @staticmethod
    def _replan_validation_response(stored: Dict[str, Any], *, idempotent_replay: bool, event: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
        contract = stored["replan_validation_contract"]
        if not verify_replan_validation_contract(contract):
            raise RuntimeError("persisted Stage-3.7.6 ReplanValidation integrity verification failed")
        validation = contract["validation"]
        boundary = contract["authority_boundary"]
        return {
            "status": "completed",
            "component_id": COMPONENT_ID,
            "control_version": CONTROL_VERSION,
            "idempotent_replay": bool(idempotent_replay),
            "mission_id": stored["mission_id"],
            "replan_validation_id": stored["replan_validation_id"],
            "replan_candidate_id": stored["replan_candidate_id"],
            "replan_snapshot_id": stored["replan_snapshot_id"],
            "adaptation_episode_id": stored["adaptation_episode_id"],
            "source_plan_version_record_id": stored["source_plan_version_record_id"],
            "source_plan_version": int(stored["source_plan_version"]),
            "candidate_plan_version": int(stored["candidate_plan_version"]),
            "candidate_plan_generation": int(stored["candidate_plan_generation"]),
            "validation_status": stored["validation_status"],
            "feasible": bool(stored["feasible"]),
            "failed_check_count": int(stored["failed_check_count"]),
            "rejection_codes": list(validation["rejection_codes"]),
            "canonical_sha256": stored["canonical_sha256"],
            "replan_validation_contract": contract,
            "validation_event": event,
            "plan_validation_performed": boundary["plan_validation_performed"],
            "delta_feasibility_evaluated": boundary["delta_feasibility_evaluated"],
            "validated_for_commit": boundary["validated_for_commit"],
            "successor_plan_created": boundary["successor_plan_created"],
            "replan_decision_committed": boundary["replan_decision_committed"],
            "plan_supersession_performed": boundary["plan_supersession_performed"],
            "mission_state_transition_performed": boundary["mission_state_transition_performed"],
            "governance_query_performed": boundary["governance_query_performed"],
            "external_context_refresh_performed": boundary["external_context_refresh_performed"],
            "dispatch_performed": boundary["dispatch_performed"],
            "target_actuation": boundary["target_actuation"],
        }

    def _record_replan_validation_event(self, stored: Dict[str, Any]) -> Dict[str, Any]:
        contract = stored["replan_validation_contract"]
        val = contract["validation"]
        return self._record_mission_event(
            stored["mission_id"],
            REPLAN_VALIDATION_EVENT_TYPE,
            stored["replan_validation_id"],
            payload={
                "replan_validation_id": stored["replan_validation_id"],
                "replan_candidate_id": stored["replan_candidate_id"],
                "replan_snapshot_id": stored["replan_snapshot_id"],
                "validation_status": stored["validation_status"],
                "feasible": bool(stored["feasible"]),
                "check_count": int(val["check_count"]),
                "failed_check_count": int(stored["failed_check_count"]),
                "rejection_codes": list(val["rejection_codes"]),
                "source_plan_version": int(stored["source_plan_version"]),
                "candidate_plan_version": int(stored["candidate_plan_version"]),
                "candidate_plan_generation": int(stored["candidate_plan_generation"]),
                "source_replan_candidate_sha256": stored["source_replan_candidate_sha256"],
                "candidate_payload_sha256": stored["candidate_payload_sha256"],
                "canonical_sha256": stored["canonical_sha256"],
                "plan_validation_performed": True,
                "delta_feasibility_evaluated": True,
                "validated_for_commit": bool(stored["feasible"]),
                "successor_plan_created": False,
                "replan_decision_committed": False,
                "plan_supersession_performed": False,
                "mission_state_transition_performed": False,
                "dispatch_performed": False,
                "target_actuation": False,
            },
            occurred_at=stored["validated_at"],
            state_version=int(stored["source_state_version"]),
            plan_version=int(stored["source_plan_version"]),
        )

    @_serialized_mission_mutation
    def validate_replan_candidate(self, mission_id: str, replan_candidate_id: str, payload: Any) -> Dict[str, Any]:
        if self.repository.get_by_mission_id(mission_id) is None:
            raise MissionNotFound(mission_id)
        normalized = normalize_replan_validation_request(payload)
        if normalized["expected_replan_candidate_id"] != replan_candidate_id:
            raise MissionReplanValidationGuardRejected("expected_replan_candidate_id does not match the ReplanCandidate route")
        req_hash = replan_validation_request_fingerprint(normalized)

        replay = self.repository.get_replan_validation_by_idempotency(mission_id, normalized["idempotency_key"])
        if replay is not None:
            if replay["request_sha256"] != req_hash:
                raise MissionReplanValidationConflict("replan validation idempotency_key was already used with different request material")
            event = self._record_replan_validation_event(replay)
            return self._replan_validation_response(replay, idempotent_replay=True, event=event)

        if self.repository.get_replan_validation_by_candidate(mission_id, replan_candidate_id) is not None:
            raise MissionReplanValidationConflict("ReplanCandidate already has a Stage-3.7.6 validation decision")
        candidate = self.repository.get_replan_candidate(mission_id, replan_candidate_id)
        if candidate is None:
            raise MissionReplanCandidateNotFound(replan_candidate_id)
        if not verify_replan_candidate_contract(candidate["replan_candidate_contract"]):
            raise MissionReplanValidationGuardRejected("Stage-3.7.5 ReplanCandidate failed integrity verification")
        if candidate["candidate_status"] != REPLAN_CANDIDATE_STATUS:
            raise MissionReplanValidationGuardRejected("Stage-3.7.5 ReplanCandidate is not CANDIDATE_GENERATED")

        if candidate["canonical_sha256"] != normalized["expected_replan_candidate_sha256"]:
            raise MissionConcurrencyConflict("Stage-3.7.5 ReplanCandidate hash changed before validation")
        if candidate["candidate_payload_sha256"] != normalized["expected_candidate_payload_sha256"]:
            raise MissionConcurrencyConflict("Stage-3.7.5 candidate payload hash changed before validation")
        if candidate["replan_snapshot_id"] != normalized["expected_replan_snapshot_id"]:
            raise MissionConcurrencyConflict("source ReplanSnapshot identity changed before validation")

        snapshot = self.repository.get_replan_snapshot(mission_id, candidate["replan_snapshot_id"])
        if snapshot is None:
            raise MissionReplanSnapshotNotFound(candidate["replan_snapshot_id"])
        if snapshot["canonical_sha256"] != normalized["expected_replan_snapshot_sha256"]:
            raise MissionConcurrencyConflict("source ReplanSnapshot hash changed before validation")

        c = candidate["replan_candidate_contract"]
        src = c["source_bindings"]
        if src["source_plan_version_record_id"] != normalized["expected_source_plan_version_record_id"]:
            raise MissionConcurrencyConflict("source Plan-version identity changed before validation")
        if int(src["source_plan_version"]) != int(normalized["expected_source_plan_version"]):
            raise MissionConcurrencyConflict("source Plan version changed before validation")
        if src["source_plan_sha256"] != normalized["expected_source_plan_sha256"]:
            raise MissionConcurrencyConflict("source Plan hash changed before validation")
        if int(src["source_state_version"]) != int(normalized["expected_source_state_version"]):
            raise MissionConcurrencyConflict("source Mission state version changed before validation")
        if src["source_version_sha256"] != normalized["expected_source_version_sha256"]:
            raise MissionConcurrencyConflict("source Mission version hash changed before validation")

        active = self.repository.get_active_plan_version(mission_id)
        if active is None:
            raise MissionReplanValidationGuardRejected("active Plan-version head is unavailable")
        if (active["plan_version_record_id"] != src["source_plan_version_record_id"]
                or int(active["plan_version"]) != int(src["source_plan_version"])
                or active["canonical_sha256"] != src["source_plan_sha256"]):
            raise MissionConcurrencyConflict("active Plan head changed after ReplanCandidate generation")

        state = self.repository.get_state(mission_id)
        vector = self.get_mission_version_vector(mission_id)
        if state is None or vector is None:
            raise MissionReplanValidationGuardRejected("Mission state/version is unavailable")
        if (state["state"] != src["source_state"]
                or int(state["state_version"]) != int(src["source_state_version"])
                or vector["version_sha256"] != src["source_version_sha256"]):
            raise MissionConcurrencyConflict("Mission state/version changed after ReplanCandidate generation")

        validated_at = utcnow_iso()
        decision_contract = build_replan_validation_contract(
            validation_id=new_replan_validation_id(),
            mission_id=mission_id,
            request=normalized,
            request_sha256=req_hash,
            candidate_record=candidate,
            snapshot_record=snapshot,
            validated_at=validated_at,
        )
        if not verify_replan_validation_contract(decision_contract):
            raise MissionReplanValidationGuardRejected("Stage-3.7.6 ReplanValidation failed self-verification")
        stored = self.repository.store_replan_validation(
            contract=decision_contract,
            request_sha256=req_hash,
            idempotency_key=normalized["idempotency_key"],
            validated_by=normalized["validated_by"],
            reason=normalized.get("reason"),
            validated_at=validated_at,
        )
        event = self._record_replan_validation_event(stored)
        return self._replan_validation_response(stored, idempotent_replay=False, event=event)

    def get_replan_validation(self, mission_id: str, replan_validation_id: str) -> Dict[str, Any]:
        if self.repository.get_by_mission_id(mission_id) is None:
            raise MissionNotFound(mission_id)
        row = self.repository.get_replan_validation(mission_id, replan_validation_id)
        if row is None:
            raise MissionReplanValidationNotFound(replan_validation_id)
        event = self.repository.get_mission_event_by_causation(mission_id, REPLAN_VALIDATION_EVENT_TYPE, replan_validation_id)
        return self._replan_validation_response(row, idempotent_replay=False, event=event)

    def get_replan_validation_for_candidate(self, mission_id: str, replan_candidate_id: str) -> Dict[str, Any]:
        if self.repository.get_by_mission_id(mission_id) is None:
            raise MissionNotFound(mission_id)
        if self.repository.get_replan_candidate(mission_id, replan_candidate_id) is None:
            raise MissionReplanCandidateNotFound(replan_candidate_id)
        row = self.repository.get_replan_validation_by_candidate(mission_id, replan_candidate_id)
        if row is None:
            raise MissionReplanValidationNotFound(replan_candidate_id)
        event = self.repository.get_mission_event_by_causation(mission_id, REPLAN_VALIDATION_EVENT_TYPE, row["replan_validation_id"])
        return self._replan_validation_response(row, idempotent_replay=False, event=event)

    def get_replan_validation_history(self, mission_id: str) -> Dict[str, Any]:
        if self.repository.get_by_mission_id(mission_id) is None:
            raise MissionNotFound(mission_id)
        rows = self.repository.list_replan_validations(mission_id)
        decisions = []
        for row in rows:
            event = self.repository.get_mission_event_by_causation(mission_id, REPLAN_VALIDATION_EVENT_TYPE, row["replan_validation_id"])
            decisions.append(self._replan_validation_response(row, idempotent_replay=False, event=event))
        return {
            "status": "completed", "component_id": COMPONENT_ID, "control_version": CONTROL_VERSION,
            "mission_id": mission_id, "replan_validation_count": len(decisions), "replan_validations": decisions,
        }

    def get_replan_validation_definition(self, mission_id: str) -> Dict[str, Any]:
        if self.repository.get_by_mission_id(mission_id) is None:
            raise MissionNotFound(mission_id)
        return {
            "status": "completed", "component_id": COMPONENT_ID, "control_version": CONTROL_VERSION,
            "mission_id": mission_id,
            "registered_replan_validation_count": len(self.repository.list_replan_validations(mission_id)),
            "replan_candidate_validation_delta_feasibility_definition": canonical_replan_validation_definition(),
        }

    @staticmethod
    def _replan_commit_response(stored: Dict[str, Any], *, idempotent_replay: bool,
                                commit_event: Optional[Dict[str, Any]] = None,
                                supersession_event: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
        contract = stored["replan_commit_contract"]
        if not verify_replan_commit_contract(contract):
            raise RuntimeError("persisted Stage-3.7.7 ReplanCommit integrity verification failed")
        mat = contract["successor_plan_materialization"]
        boundary = contract["authority_boundary"]
        auth = contract["commit_authorization"]
        return {
            "status": "completed",
            "component_id": COMPONENT_ID,
            "control_version": CONTROL_VERSION,
            "idempotent_replay": bool(idempotent_replay),
            "mission_id": stored["mission_id"],
            "replan_commit_id": stored["replan_commit_id"],
            "replan_validation_id": stored["replan_validation_id"],
            "replan_candidate_id": stored["replan_candidate_id"],
            "replan_snapshot_id": stored["replan_snapshot_id"],
            "adaptation_episode_id": stored["adaptation_episode_id"],
            "replan_trigger_id": stored["replan_trigger_id"],
            "commit_status": stored["commit_status"],
            "governance_decision": stored["governance_decision"],
            "policy_decision_id": stored["policy_decision_id"],
            "policy_decision_hash": stored["policy_decision_hash"],
            "policy_version": int(stored["policy_version"]),
            "predecessor_plan_version_record_id": stored["predecessor_plan_version_record_id"],
            "predecessor_plan_version": int(stored["predecessor_plan_version"]),
            "successor_plan_version_record_id": stored["successor_plan_version_record_id"],
            "successor_plan_version": int(stored["successor_plan_version"]),
            "candidate_plan_generation": int(stored["candidate_plan_generation"]),
            "canonical_sha256": stored["canonical_sha256"],
            "successor_plan_sha256": stored["successor_plan_sha256"],
            "replan_commit_contract": contract,
            "commit_event": commit_event,
            "plan_supersession_event": supersession_event,
            "authoritative_governance_revalidation_performed": boundary["authoritative_governance_revalidation_performed"],
            "governance_query_performed": boundary["governance_query_performed"],
            "replan_decision_committed": boundary["replan_decision_committed"],
            "successor_plan_created": boundary["successor_plan_created"],
            "successor_plan_materialized": mat["successor_plan_materialized"],
            "active_plan_head_advanced": mat["active_head_advanced"],
            "plan_supersession_performed": boundary["plan_supersession_performed"],
            "historical_plan_mutation_performed": boundary["historical_plan_mutation_performed"],
            "mission_state_transition_performed": boundary["mission_state_transition_performed"],
            "routing_performed": boundary["routing_performed"],
            "delegation_performed": boundary["delegation_performed"],
            "dispatch_performed": boundary["dispatch_performed"],
            "target_actuation": boundary["target_actuation"],
            "authorization_operation_id": auth["operation_id"],
        }

    def _ensure_replan_commit_events(self, stored: Dict[str, Any]) -> tuple[Dict[str, Any], Dict[str, Any]]:
        contract = stored["replan_commit_contract"]
        mat = contract["successor_plan_materialization"]
        supersession = self._record_mission_event(
            stored["mission_id"],
            "MISSION_PLAN_VERSION_REPLANNED_SUPERSEDED",
            stored["successor_plan_version_record_id"],
            payload={
                "replan_id": stored["replan_trigger_id"],
                "replan_transition_id": stored["replan_commit_id"],
                "replan_commit_id": stored["replan_commit_id"],
                "replan_validation_id": stored["replan_validation_id"],
                "superseded_plan_version_record_id": stored["predecessor_plan_version_record_id"],
                "superseded_plan_version": int(stored["predecessor_plan_version"]),
                "successor_plan_version_record_id": stored["successor_plan_version_record_id"],
                "successor_plan_version": int(stored["successor_plan_version"]),
                "canonical_sha256": stored["successor_plan_sha256"],
                "planner_reinvocation_performed": False,
                "stage375_candidate_planner_bound": True,
                "authoritative_replan_commit": True,
            },
            occurred_at=stored["committed_at"],
            state_version=int(stored["source_state_version"]),
            plan_version=int(stored["successor_plan_version"]),
            policy_version=int(stored["policy_version"]),
        )
        commit_event = self._record_mission_event(
            stored["mission_id"],
            REPLAN_COMMIT_EVENT_TYPE,
            stored["replan_commit_id"],
            payload={
                "replan_commit_id": stored["replan_commit_id"],
                "replan_validation_id": stored["replan_validation_id"],
                "replan_candidate_id": stored["replan_candidate_id"],
                "replan_snapshot_id": stored["replan_snapshot_id"],
                "adaptation_episode_id": stored["adaptation_episode_id"],
                "replan_trigger_id": stored["replan_trigger_id"],
                "commit_status": stored["commit_status"],
                "governance_decision": stored["governance_decision"],
                "policy_decision_id": stored["policy_decision_id"],
                "policy_decision_hash": stored["policy_decision_hash"],
                "predecessor_plan_version_record_id": stored["predecessor_plan_version_record_id"],
                "predecessor_plan_version": int(stored["predecessor_plan_version"]),
                "successor_plan_version_record_id": stored["successor_plan_version_record_id"],
                "successor_plan_version": int(stored["successor_plan_version"]),
                "successor_plan_sha256": stored["successor_plan_sha256"],
                "materialized_task_count": int(mat["materialized_task_count"]),
                "materialized_dependency_edge_count": int(mat["materialized_dependency_edge_count"]),
                "replan_decision_committed": True,
                "successor_plan_created": True,
                "plan_supersession_performed": True,
                "mission_state_transition_performed": False,
                "dispatch_performed": False,
                "target_actuation": False,
            },
            occurred_at=stored["committed_at"],
            state_version=int(stored["source_state_version"]),
            plan_version=int(stored["successor_plan_version"]),
            policy_version=int(stored["policy_version"]),
        )
        return commit_event, supersession

    def _recover_replan_commit_policy_decision(self, mission_id: str, operation_id: str) -> Optional[Dict[str, Any]]:
        snapshot = self.governance_client.mission_correlation_snapshot(mission_id)
        matches = []
        for request in snapshot.get("authorization_requests") or []:
            context = request.get("context") or {}
            if context.get("mission_orchestrator_replan_commit_operation_id") == operation_id:
                matches.append(request)
        if len(matches) > 1:
            raise MissionGovernanceProtocolError(
                "multiple authoritative Governance authorization requests claim one Stage-3.7.7 operation id"
            )
        if not matches:
            return None
        request_id = matches[0].get("request_id")
        decisions = [item for item in (snapshot.get("policy_decisions") or []) if item.get("request_id") == request_id]
        if not decisions:
            return None
        decisions.sort(key=lambda item: int(item.get("id") or 0))
        decision = dict(decisions[-1])
        for event in snapshot.get("events") or []:
            payload = event.get("payload") or {}
            if event.get("event_type") == "POLICY_DECISION_ISSUED" and payload.get("decision_id") == decision.get("decision_id"):
                decision["governance_event_id"] = event.get("event_id") or payload.get("governance_event_id")
        return decision

    @_serialized_mission_mutation
    def commit_authorized_replan(self, mission_id: str, replan_validation_id: str, payload: Any) -> Dict[str, Any]:
        if self.repository.get_by_mission_id(mission_id) is None:
            raise MissionNotFound(mission_id)
        normalized = normalize_replan_commit_request(payload)
        if normalized["expected_replan_validation_id"] != replan_validation_id:
            raise MissionReplanCommitGuardRejected("expected_replan_validation_id does not match the ReplanValidation route")
        req_hash = replan_commit_request_fingerprint(normalized)

        replay = self.repository.get_replan_commit_by_idempotency(mission_id, normalized["idempotency_key"])
        if replay is not None:
            if replay["request_sha256"] != req_hash:
                raise MissionReplanCommitConflict("replan commit idempotency_key was already used with different request material")
            commit_event, supersession = self._ensure_replan_commit_events(replay)
            return self._replan_commit_response(replay, idempotent_replay=True, commit_event=commit_event, supersession_event=supersession)
        if self.repository.get_replan_commit_by_validation(mission_id, replan_validation_id) is not None:
            raise MissionReplanCommitConflict("ReplanValidation already has an authoritative Stage-3.7.7 commit")

        validation = self.repository.get_replan_validation(mission_id, replan_validation_id)
        if validation is None:
            raise MissionReplanValidationNotFound(replan_validation_id)
        if not verify_replan_validation_contract(validation["replan_validation_contract"]):
            raise MissionReplanCommitGuardRejected("Stage-3.7.6 ReplanValidation failed integrity verification")
        if validation["validation_status"] != REPLAN_VALIDATION_STATUS_VALIDATED or not bool(validation["feasible"]):
            raise MissionReplanCommitGuardRejected("Stage-3.7.6 decision is not VALIDATED_FOR_COMMIT")
        if validation["canonical_sha256"] != normalized["expected_replan_validation_sha256"]:
            raise MissionConcurrencyConflict("Stage-3.7.6 ReplanValidation hash changed before commit")
        if validation["replan_candidate_id"] != normalized["expected_replan_candidate_id"]:
            raise MissionConcurrencyConflict("Stage-3.7.5 ReplanCandidate identity changed before commit")

        candidate = self.repository.get_replan_candidate(mission_id, validation["replan_candidate_id"])
        if candidate is None:
            raise MissionReplanCandidateNotFound(validation["replan_candidate_id"])
        if not verify_replan_candidate_contract(candidate["replan_candidate_contract"]):
            raise MissionReplanCommitGuardRejected("Stage-3.7.5 ReplanCandidate failed integrity verification")
        if candidate["canonical_sha256"] != normalized["expected_replan_candidate_sha256"]:
            raise MissionConcurrencyConflict("Stage-3.7.5 ReplanCandidate hash changed before commit")
        if candidate["candidate_payload_sha256"] != normalized["expected_candidate_payload_sha256"]:
            raise MissionConcurrencyConflict("Stage-3.7.5 candidate payload hash changed before commit")
        if candidate["replan_snapshot_id"] != normalized["expected_replan_snapshot_id"]:
            raise MissionConcurrencyConflict("Stage-3.7.4 ReplanSnapshot identity changed before commit")

        snapshot = self.repository.get_replan_snapshot(mission_id, candidate["replan_snapshot_id"])
        if snapshot is None:
            raise MissionReplanSnapshotNotFound(candidate["replan_snapshot_id"])
        if not verify_replan_snapshot_contract(snapshot["replan_snapshot_contract"]):
            raise MissionReplanCommitGuardRejected("Stage-3.7.4 ReplanSnapshot failed integrity verification")
        if snapshot["canonical_sha256"] != normalized["expected_replan_snapshot_sha256"]:
            raise MissionConcurrencyConflict("Stage-3.7.4 ReplanSnapshot hash changed before commit")
        snapshot_contract = snapshot["replan_snapshot_contract"]

        eligibility = self.repository.get_replan_eligibility(mission_id, snapshot_contract["identity"]["eligibility_gate_id"])
        if eligibility is None:
            raise MissionReplanEligibilityGovernanceNotFound(snapshot_contract["identity"]["eligibility_gate_id"])
        if not verify_replan_eligibility_contract(eligibility["replan_eligibility_governance_contract"]):
            raise MissionReplanCommitGuardRejected("Stage-3.7.3 ReplanEligibility failed integrity verification")
        elig_body = eligibility["replan_eligibility_governance_contract"]
        if elig_body["eligibility"]["replan_eligible"] is not True or elig_body["governance_decision"]["decision"] != "ALLOW" or bool(elig_body["governance_decision"]["requires_human_approval"]):
            raise MissionReplanCommitGuardRejected("Stage-3.7.3 eligibility is not authoritatively eligible")

        src = validation["replan_validation_contract"]["source_bindings"]
        for key, expected in (
            ("source_plan_version_record_id", normalized["expected_source_plan_version_record_id"]),
            ("source_plan_sha256", normalized["expected_source_plan_sha256"]),
            ("source_version_sha256", normalized["expected_source_version_sha256"]),
        ):
            if src[key] != expected:
                raise MissionConcurrencyConflict(f"{key} changed before authoritative replan commit")
        if int(src["source_plan_version"]) != int(normalized["expected_source_plan_version"]):
            raise MissionConcurrencyConflict("source Plan version changed before authoritative replan commit")
        if int(src["source_state_version"]) != int(normalized["expected_source_state_version"]):
            raise MissionConcurrencyConflict("source Mission state version changed before authoritative replan commit")

        active = self.repository.get_active_plan_version(mission_id)
        state = self.repository.get_state(mission_id)
        vector = self.get_mission_version_vector(mission_id)
        if active is None or state is None or vector is None:
            raise MissionReplanCommitGuardRejected("current Mission state/version or active Plan head is unavailable")
        if (active["plan_version_record_id"] != src["source_plan_version_record_id"]
                or int(active["plan_version"]) != int(src["source_plan_version"])
                or active["canonical_sha256"] != src["source_plan_sha256"]):
            raise MissionConcurrencyConflict("active Plan head changed after Stage-3.7.6 validation")
        if (state["state"] != src["source_state"] or int(state["state_version"]) != int(src["source_state_version"])
                or vector["version_sha256"] != src["source_version_sha256"]):
            raise MissionConcurrencyConflict("Mission state/version changed after Stage-3.7.6 validation")

        scope_record = self.repository.get_current_scope_contract(mission_id)
        governance_binding = self.repository.get_current_governance_binding(mission_id)
        if scope_record is None:
            raise MissionScopeContractNotFound(mission_id)
        if governance_binding is None:
            raise MissionGovernanceBindingNotFound(mission_id)
        snap_scope = snapshot_contract["scope_context"]
        snap_gov = snapshot_contract["governance_context"]
        if (scope_record["snapshot_id"] != normalized["expected_scope_snapshot_id"]
                or scope_record["canonical_sha256"] != normalized["expected_scope_sha256"]
                or scope_record["snapshot_id"] != snap_scope["mission_scope_snapshot_id"]
                or scope_record["canonical_sha256"] != snap_scope["mission_scope_sha256"]):
            raise MissionConcurrencyConflict("Mission scope changed after ReplanSnapshot binding")
        if (governance_binding["binding_snapshot_id"] != normalized["expected_governance_binding_snapshot_id"]
                or int(governance_binding["binding_version"]) != int(normalized["expected_governance_binding_version"])
                or governance_binding["canonical_sha256"] != normalized["expected_governance_binding_sha256"]
                or governance_binding["binding_snapshot_id"] != snap_gov["governance_binding_snapshot_id"]
                or governance_binding["canonical_sha256"] != snap_gov["governance_binding_sha256"]):
            raise MissionConcurrencyConflict("Governance binding changed after ReplanSnapshot binding")
        if not verify_contract(scope_record["contract"]):
            raise MissionReplanCommitGuardRejected("current Mission scope failed integrity verification")
        if not verify_binding_contract(governance_binding["binding"]):
            raise MissionReplanCommitGuardRejected("current Governance binding failed integrity verification")
        if not self._binding_is_current_for_scope(governance_binding):
            raise MissionReplanCommitGuardRejected("current Governance binding is stale relative to Mission scope")
        allowed_actions = set((scope_record["contract"].get("roe") or {}).get("allowed_action_classes") or [])
        if REPLAN_COMMIT_GOVERNANCE_ACTION_CLASS not in allowed_actions:
            raise MissionReplanCommitGuardRejected("canonical Mission scope does not allow INTERNAL_REASONING replan commit authorization")

        materialized_candidate = materialize_successor_candidate_plan(candidate["replan_candidate_contract"])
        if int(materialized_candidate["candidate_plan_version"]) != int(src["candidate_plan_version"]):
            raise MissionReplanCommitGuardRejected("Stage-3.7.5 candidate successor version does not match Stage-3.7.6 decision")
        if int(materialized_candidate["task_count"]) < 1:
            raise MissionReplanCommitGuardRejected("validated replan candidate contains no successor work")

        operation_id = deterministic_replan_commit_operation_id(req_hash)
        gov = governance_binding["binding"]["governance_authority"]
        with self._governance_lock:
            external_scope = validate_governance_scope_response(
                self.governance_client.get_scope_contract(gov["governance_scope_contract_id"]),
                mission_id=mission_id,
                policy_set_id=gov["policy_set_id"],
            )
            if (external_scope["scope_contract_id"] != gov["governance_scope_contract_id"]
                    or int(external_scope["version"]) != int(gov["governance_scope_version"])
                    or external_scope["contract_hash"] != gov["governance_scope_contract_hash"]):
                raise MissionGovernanceProtocolError("authoritative Governance scope no longer matches immutable Mission binding")
            decision = self._recover_replan_commit_policy_decision(mission_id, operation_id)
            if decision is None:
                decision = self.governance_client.evaluate_authorization({
                    "mission_id": mission_id,
                    "scope_contract_id": gov["governance_scope_contract_id"],
                    "subject_component": COMPONENT_ID,
                    "action_class": REPLAN_COMMIT_GOVERNANCE_ACTION_CLASS,
                    "action_name": REPLAN_COMMIT_GOVERNANCE_ACTION_NAME,
                    "resource_type": REPLAN_COMMIT_GOVERNANCE_RESOURCE_TYPE,
                    "resource_value": mission_id,
                    "context": {
                        "mission_orchestrator_replan_commit_operation_id": operation_id,
                        "replan_validation_id": validation["replan_validation_id"],
                        "replan_validation_sha256": validation["canonical_sha256"],
                        "replan_candidate_id": candidate["replan_candidate_id"],
                        "replan_candidate_sha256": candidate["canonical_sha256"],
                        "candidate_payload_sha256": candidate["candidate_payload_sha256"],
                        "replan_snapshot_id": snapshot["replan_snapshot_id"],
                        "source_plan_version_record_id": active["plan_version_record_id"],
                        "source_plan_version": int(active["plan_version"]),
                        "target_plan_version": int(src["candidate_plan_version"]),
                        "candidate_plan_generation": int(src["candidate_plan_generation"]),
                        "authorization_purpose": "AUTHORITATIVE_REPLAN_COMMIT_AND_SUCCESSOR_PLAN_MATERIALIZATION",
                        "mission_state_transition_requested": False,
                        "dispatch_requested": False,
                        "target_actuation_requested": False,
                    },
                    "evidence_refs": [
                        f"mission://{mission_id}/replan-validations/{validation['replan_validation_id']}",
                        f"mission://{mission_id}/replan-candidates/{candidate['replan_candidate_id']}",
                        f"mission://{mission_id}/replan-snapshots/{snapshot['replan_snapshot_id']}",
                        f"mission://{mission_id}/plan-versions/{active['plan_version_record_id']}",
                    ],
                    "requested_by": normalized["requested_by"],
                })
            decision = validate_policy_decision(
                decision,
                mission_id=mission_id,
                governance_scope_contract_id=gov["governance_scope_contract_id"],
                governance_scope_version=gov["governance_scope_version"],
                policy_set_id=gov["policy_set_id"],
            )
            if decision["decision"] != "ALLOW" or bool(decision.get("requires_human_approval")):
                raise MissionReplanCommitGuardRejected(
                    "authoritative Governance did not authorize replan commit without human approval"
                )

        base_plan = self.repository.get_mission_plan(mission_id)
        if base_plan is None or not verify_plan_contract(base_plan["plan_contract"]):
            raise MissionReplanCommitGuardRejected("canonical base Plan is unavailable or failed integrity verification")
        commit_id = new_replan_commit_id()
        successor_id = new_plan_version_record_id()
        successor_version = int(active["plan_version"]) + 1
        committed_at = utcnow_iso()
        candidate_sha = candidate_plan_fingerprint(materialized_candidate)
        trigger = snapshot_contract["trigger_context"]
        replan_lineage = {
            "replan_id": candidate["replan_candidate_contract"]["identity"]["replan_trigger_id"],
            "transition_id": commit_id,
            "trigger_code": trigger.get("trigger_code"),
            "origin": "STAGE3_7_AUTHORITATIVE_REPLAN_COMMIT",
            "from_state": state["state"],
            "to_state": state["state"],
        }
        plan_contract = build_plan_version_contract(
            plan_version_record_id=successor_id,
            mission_id=mission_id,
            canonical_plan_id=base_plan["plan_id"],
            plan_version=successor_version,
            request_sha256=req_hash,
            source_state=state,
            source_version_sha256=vector["version_sha256"],
            base_plan_sha256=base_plan["canonical_sha256"],
            candidate_plan=materialized_candidate,
            candidate_plan_sha256=candidate_sha,
            planner_profile=REPLAN_PLANNER_PROFILE,
            planner_engine=REPLAN_PLANNER_ENGINE,
            planner_engine_version=REPLAN_PLANNER_ENGINE_VERSION,
            activation_type=PLAN_VERSIONING_REPLAN_ACTIVATION_TYPE,
            predecessor=active,
            plan_validation=None,
            replan=replan_lineage,
            created_by=normalized["requested_by"],
            reason=normalized.get("reason"),
            metadata={**normalized["metadata"], "stage": "3.7.7", "source_replan_validation_id": replan_validation_id},
            created_at=committed_at,
        )
        if not verify_plan_version_contract(plan_contract):
            raise MissionReplanCommitGuardRejected("Stage-3.7.7 successor Plan-version contract failed self-verification")
        successor_stub = {
            "plan_version_record_id": successor_id,
            "plan_version": successor_version,
            "canonical_sha256": plan_contract["integrity"]["canonical_sha256"],
        }
        commit_contract = build_replan_commit_contract(
            commit_id=commit_id,
            mission_id=mission_id,
            request=normalized,
            request_sha256=req_hash,
            operation_id=operation_id,
            validation_record=validation,
            candidate_record=candidate,
            snapshot_record=snapshot,
            eligibility_record=eligibility,
            scope_record=scope_record,
            governance_binding=governance_binding,
            policy_decision=decision,
            predecessor_plan=active,
            successor_plan=successor_stub,
            successor_candidate_plan=materialized_candidate,
            committed_at=committed_at,
        )
        if not verify_replan_commit_contract(commit_contract):
            raise MissionReplanCommitGuardRejected("Stage-3.7.7 ReplanCommit contract failed self-verification")
        stored = self.repository.store_replan_commit_with_successor_plan(
            commit_contract=commit_contract,
            request_sha256=req_hash,
            idempotency_key=normalized["idempotency_key"],
            authorization_operation_id=operation_id,
            plan_version_contract=plan_contract,
            plan_version_idempotency_key=f"stage377-plan-{commit_id}",
            candidate_plan_sha256=candidate_sha,
            canonical_plan_id=base_plan["plan_id"],
            expected_base_plan_sha256=base_plan["canonical_sha256"],
            expected_state=state["state"],
            expected_state_version=int(state["state_version"]),
            source_version_sha256=vector["version_sha256"],
            actor=normalized["requested_by"],
            reason=normalized.get("reason"),
            committed_at=committed_at,
        )
        commit_event, supersession = self._ensure_replan_commit_events(stored)
        return self._replan_commit_response(stored, idempotent_replay=False, commit_event=commit_event, supersession_event=supersession)

    def get_replan_commit(self, mission_id: str, replan_commit_id: str) -> Dict[str, Any]:
        if self.repository.get_by_mission_id(mission_id) is None:
            raise MissionNotFound(mission_id)
        row = self.repository.get_replan_commit(mission_id, replan_commit_id)
        if row is None:
            raise MissionReplanCommitNotFound(replan_commit_id)
        commit_event, supersession = self._ensure_replan_commit_events(row)
        return self._replan_commit_response(row, idempotent_replay=False, commit_event=commit_event, supersession_event=supersession)

    def get_replan_commit_for_validation(self, mission_id: str, replan_validation_id: str) -> Dict[str, Any]:
        if self.repository.get_by_mission_id(mission_id) is None:
            raise MissionNotFound(mission_id)
        if self.repository.get_replan_validation(mission_id, replan_validation_id) is None:
            raise MissionReplanValidationNotFound(replan_validation_id)
        row = self.repository.get_replan_commit_by_validation(mission_id, replan_validation_id)
        if row is None:
            raise MissionReplanCommitNotFound(replan_validation_id)
        commit_event, supersession = self._ensure_replan_commit_events(row)
        return self._replan_commit_response(row, idempotent_replay=False, commit_event=commit_event, supersession_event=supersession)

    def get_replan_commit_history(self, mission_id: str) -> Dict[str, Any]:
        if self.repository.get_by_mission_id(mission_id) is None:
            raise MissionNotFound(mission_id)
        rows = self.repository.list_replan_commits(mission_id)
        commits = []
        for row in rows:
            commit_event, supersession = self._ensure_replan_commit_events(row)
            commits.append(self._replan_commit_response(row, idempotent_replay=False, commit_event=commit_event, supersession_event=supersession))
        return {
            "status": "completed", "component_id": COMPONENT_ID, "control_version": CONTROL_VERSION,
            "mission_id": mission_id, "replan_commit_count": len(commits), "replan_commits": commits,
        }

    def get_replan_commit_definition(self, mission_id: str) -> Dict[str, Any]:
        if self.repository.get_by_mission_id(mission_id) is None:
            raise MissionNotFound(mission_id)
        return {
            "status": "completed", "component_id": COMPONENT_ID, "control_version": CONTROL_VERSION,
            "mission_id": mission_id,
            "registered_replan_commit_count": len(self.repository.list_replan_commits(mission_id)),
            "authoritative_replan_commit_authorization_successor_plan_materialization_definition": canonical_replan_commit_definition(),
        }

    @staticmethod
    def _replan_handoff_response(stored: Dict[str, Any], *, idempotent_replay: bool,
                                 handoff_event: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
        contract = stored["replan_handoff_contract"]
        if not verify_replan_handoff_contract(contract):
            raise RuntimeError("persisted Stage-3.7.8 ReplanHandoff integrity verification failed")
        bind = contract["atomic_commit_binding"]
        task_handoff = contract["task_handoff"]
        successor = contract["successor_handoff"]
        boundary = contract["authority_boundary"]
        return {
            "status": "completed",
            "component_id": COMPONENT_ID,
            "control_version": CONTROL_VERSION,
            "idempotent_replay": bool(idempotent_replay),
            "mission_id": stored["mission_id"],
            "replan_handoff_id": stored["replan_handoff_id"],
            "replan_commit_id": stored["replan_commit_id"],
            "adaptation_episode_id": stored["adaptation_episode_id"],
            "replan_trigger_id": stored["replan_trigger_id"],
            "handoff_status": stored["handoff_status"],
            "effective_episode_state": successor["effective_episode_state"],
            "predecessor_plan_version_record_id": stored["predecessor_plan_version_record_id"],
            "predecessor_plan_version": int(stored["predecessor_plan_version"]),
            "predecessor_effective_status": bind["predecessor_effective_status"],
            "successor_plan_version_record_id": stored["successor_plan_version_record_id"],
            "successor_plan_version": int(stored["successor_plan_version"]),
            "successor_effective_status": bind["successor_effective_status"],
            "canonical_sha256": stored["canonical_sha256"],
            "replan_handoff_contract": contract,
            "handoff_event": handoff_event,
            "task_disposition_count": int(stored["task_disposition_count"]),
            "keep_count": int(stored["keep_count"]),
            "drain_count": int(stored["drain_count"]),
            "cancel_count": int(stored["cancel_count"]),
            "supersede_count": int(stored["supersede_count"]),
            "replace_count": int(stored["replace_count"]),
            "task_dispositions": task_handoff["dispositions"],
            "next_control": successor["next_control"],
            "active_plan_head_verified": boundary["active_plan_head_verified"],
            "plan_supersession_verified": boundary["plan_supersession_verified"],
            "cancellation_io_performed": boundary["cancellation_io_performed"],
            "mission_state_transition_performed": boundary["mission_state_transition_performed"],
            "routing_performed": boundary["routing_performed"],
            "delegation_performed": boundary["delegation_performed"],
            "dispatch_performed": boundary["dispatch_performed"],
            "execution_attempt_created": boundary["execution_attempt_created"],
            "target_actuation": boundary["target_actuation"],
        }

    def _ensure_replan_handoff_event(self, stored: Dict[str, Any]) -> Dict[str, Any]:
        contract = stored["replan_handoff_contract"]
        return self._record_mission_event(
            stored["mission_id"],
            REPLAN_HANDOFF_EVENT_TYPE,
            stored["replan_handoff_id"],
            payload={
                "replan_handoff_id": stored["replan_handoff_id"],
                "replan_commit_id": stored["replan_commit_id"],
                "adaptation_episode_id": stored["adaptation_episode_id"],
                "replan_trigger_id": stored["replan_trigger_id"],
                "handoff_status": stored["handoff_status"],
                "effective_episode_state": "HANDOFF_READY",
                "predecessor_plan_version_record_id": stored["predecessor_plan_version_record_id"],
                "predecessor_plan_version": int(stored["predecessor_plan_version"]),
                "successor_plan_version_record_id": stored["successor_plan_version_record_id"],
                "successor_plan_version": int(stored["successor_plan_version"]),
                "successor_plan_sha256": stored["successor_plan_sha256"],
                "task_disposition_count": int(stored["task_disposition_count"]),
                "keep_count": int(stored["keep_count"]),
                "drain_count": int(stored["drain_count"]),
                "cancel_count": int(stored["cancel_count"]),
                "supersede_count": int(stored["supersede_count"]),
                "replace_count": int(stored["replace_count"]),
                "next_control": REPLAN_HANDOFF_NEXT_CONTROL,
                "cancellation_io_performed": False,
                "mission_state_transition_performed": False,
                "routing_performed": False,
                "dispatch_performed": False,
                "target_actuation": False,
            },
            occurred_at=stored["handed_off_at"],
            state_version=int(stored["source_state_version"]),
            plan_version=int(stored["successor_plan_version"]),
            policy_version=None,
        )

    @_serialized_mission_mutation
    def declare_replan_handoff(self, mission_id: str, replan_commit_id: str, payload: Any) -> Dict[str, Any]:
        if self.repository.get_by_mission_id(mission_id) is None:
            raise MissionNotFound(mission_id)
        normalized = normalize_replan_handoff_request(payload)
        if normalized["expected_replan_commit_id"] != replan_commit_id:
            raise MissionReplanHandoffGuardRejected("expected_replan_commit_id does not match the ReplanCommit route")
        req_hash = replan_handoff_request_fingerprint(normalized)
        replay = self.repository.get_replan_handoff_by_idempotency(mission_id, normalized["idempotency_key"])
        if replay is not None:
            if replay["request_sha256"] != req_hash:
                raise MissionReplanHandoffConflict("replan handoff idempotency_key was already used with different request material")
            event = self._ensure_replan_handoff_event(replay)
            return self._replan_handoff_response(replay, idempotent_replay=True, handoff_event=event)
        if self.repository.get_replan_handoff_by_commit(mission_id, replan_commit_id) is not None:
            raise MissionReplanHandoffConflict("ReplanCommit already has a handoff declaration")

        commit = self.repository.get_replan_commit(mission_id, replan_commit_id)
        if commit is None:
            raise MissionReplanCommitNotFound(replan_commit_id)
        if not verify_replan_commit_contract(commit["replan_commit_contract"]):
            raise MissionReplanHandoffGuardRejected("Stage-3.7.7 ReplanCommit failed integrity verification")
        if commit["commit_status"] != REPLAN_COMMIT_STATUS:
            raise MissionReplanHandoffGuardRejected("Stage-3.7.7 ReplanCommit is not COMMITTED_SUCCESSOR_PLAN")
        if commit["canonical_sha256"] != normalized["expected_replan_commit_sha256"]:
            raise MissionConcurrencyConflict("Stage-3.7.7 ReplanCommit hash changed before handoff")
        if int(commit["source_state_version"]) != int(normalized["expected_source_state_version"]):
            raise MissionConcurrencyConflict("Mission source state version does not match the committed replan")

        versions = {x["plan_version_record_id"]: x for x in self.repository.list_plan_versions(mission_id)}
        predecessor = versions.get(commit["predecessor_plan_version_record_id"])
        successor = versions.get(commit["successor_plan_version_record_id"])
        active = self.repository.get_active_plan_version(mission_id)
        state = self.repository.get_state(mission_id)
        if predecessor is None or successor is None or active is None or state is None:
            raise MissionReplanHandoffGuardRejected("predecessor/successor Plan, active head, or Mission state is unavailable")
        expected_pairs = (
            (predecessor["plan_version_record_id"], normalized["expected_predecessor_plan_version_record_id"], "predecessor Plan identity"),
            (int(predecessor["plan_version"]), int(normalized["expected_predecessor_plan_version"]), "predecessor Plan version"),
            (predecessor["canonical_sha256"], normalized["expected_predecessor_plan_sha256"], "predecessor Plan hash"),
            (successor["plan_version_record_id"], normalized["expected_successor_plan_version_record_id"], "successor Plan identity"),
            (int(successor["plan_version"]), int(normalized["expected_successor_plan_version"]), "successor Plan version"),
            (successor["canonical_sha256"], normalized["expected_successor_plan_sha256"], "successor Plan hash"),
        )
        for observed, expected, label in expected_pairs:
            if observed != expected:
                raise MissionConcurrencyConflict(f"{label} changed before handoff")
        if (active["plan_version_record_id"] != successor["plan_version_record_id"]
                or int(active["plan_version"]) != int(successor["plan_version"])
                or active["canonical_sha256"] != successor["canonical_sha256"]):
            raise MissionConcurrencyConflict("active Plan head is no longer the Stage-3.7.7 successor")
        if state["state"] != commit["source_state"] or int(state["state_version"]) != int(commit["source_state_version"]):
            raise MissionConcurrencyConflict("Mission state changed after Stage-3.7.7 commit and before handoff")
        if successor.get("predecessor_plan_version_record_id") != predecessor["plan_version_record_id"]:
            raise MissionReplanHandoffGuardRejected("successor Plan no longer binds the committed predecessor")
        if successor.get("replan_transition_id") != replan_commit_id:
            raise MissionReplanHandoffGuardRejected("successor Plan is not causally bound to the Stage-3.7.7 ReplanCommit")

        # Ensure the two Stage-3.7.7 lineage events exist before finalizing handoff.
        self._ensure_replan_commit_events(commit)
        snapshot = self.repository.get_replan_snapshot(mission_id, commit["replan_snapshot_id"])
        candidate = self.repository.get_replan_candidate(mission_id, commit["replan_candidate_id"])
        if snapshot is None or candidate is None:
            raise MissionReplanHandoffGuardRejected("Stage-3.7.4 snapshot or Stage-3.7.5 candidate is unavailable")
        dispositions = derive_task_dispositions(
            snapshot_contract=snapshot["replan_snapshot_contract"],
            candidate_contract=candidate["replan_candidate_contract"],
            execution_attempts=self.repository.list_execution_attempts(mission_id),
            execution_deliveries=self.repository.list_execution_deliveries(mission_id),
            execution_running_projections=self.repository.list_execution_running_projections(mission_id),
            execution_result_captures=self.repository.list_execution_result_captures(mission_id),
            execution_termination_controls=self.repository.list_execution_termination_controls(mission_id),
            predecessor_plan_version_record_id=predecessor["plan_version_record_id"],
        )
        handoff_id = new_replan_handoff_id()
        handed_off_at = utcnow_iso()
        contract = build_replan_handoff_contract(
            handoff_id=handoff_id, mission_id=mission_id, request=normalized, request_sha256=req_hash,
            commit_record=commit, predecessor_plan=predecessor, successor_plan=successor,
            task_dispositions=dispositions, handed_off_at=handed_off_at,
        )
        if not verify_replan_handoff_contract(contract):
            raise MissionReplanHandoffGuardRejected("Stage-3.7.8 ReplanHandoff contract failed self-verification")
        stored = self.repository.store_replan_handoff(
            contract=contract, request_sha256=req_hash, idempotency_key=normalized["idempotency_key"],
            handed_off_by=normalized["handed_off_by"], reason=normalized.get("reason"), handed_off_at=handed_off_at,
            expected_active_head_id=successor["plan_version_record_id"], expected_active_head_version=int(successor["plan_version"]),
            expected_active_head_sha256=successor["canonical_sha256"], expected_state=state["state"],
            expected_state_version=int(state["state_version"]),
        )
        event = self._ensure_replan_handoff_event(stored)
        return self._replan_handoff_response(stored, idempotent_replay=False, handoff_event=event)

    def get_replan_handoff(self, mission_id: str, replan_handoff_id: str) -> Dict[str, Any]:
        if self.repository.get_by_mission_id(mission_id) is None:
            raise MissionNotFound(mission_id)
        row = self.repository.get_replan_handoff(mission_id, replan_handoff_id)
        if row is None:
            raise MissionReplanHandoffNotFound(replan_handoff_id)
        return self._replan_handoff_response(row, idempotent_replay=False, handoff_event=self._ensure_replan_handoff_event(row))

