    @_serialized_mission_mutation
    def create_planning_recovery_checkpoint(self, mission_id: str, payload: Any) -> Dict[str, Any]:
        if self.repository.get_by_mission_id(mission_id) is None:
            raise MissionNotFound(mission_id)
        normalized = normalize_planning_recovery_request(payload)
        req_hash = planning_recovery_request_fingerprint(normalized)

        replay_row = self.repository.get_planning_recovery_checkpoint_by_idempotency(
            mission_id, normalized["idempotency_key"]
        )
        if replay_row is not None:
            if replay_row["request_sha256"] != req_hash:
                raise MissionPlanningRecoveryConflict(
                    "planning recovery idempotency_key was already used with a different canonical request"
                )
            self._record_mission_event(
                mission_id,
                PLANNING_RECOVERY_EVENT_TYPE,
                replay_row["checkpoint_id"],
                payload={
                    "checkpoint_id": replay_row["checkpoint_id"],
                    "checkpoint_version": int(replay_row["checkpoint_version"]),
                    "plan_version_record_id": replay_row["plan_version_record_id"],
                    "plan_version": int(replay_row["plan_version"]),
                    "canonical_sha256": replay_row["canonical_sha256"],
                    "source_planning_event_count": int(replay_row["source_event_count"]),
                    "source_planning_event_tip_sha256": replay_row["source_event_tip_sha256"],
                    "planner_rerun_performed": False,
                    "recovery_is_authorization": False,
                    "dispatch_performed": False,
                },
                occurred_at=replay_row["created_at"],
                state_version=int(replay_row["source_state_version"]),
                plan_version=int(replay_row["plan_version"]),
            )
            return self._planning_recovery_checkpoint_response(replay_row, idempotent_replay=True)

        state = self.repository.get_state(mission_id)
        if state is None or state["state"] not in PLANNING_RECOVERY_REQUIRED_STATES:
            raise MissionPlanningRecoveryGuardRejected(
                "Stage-3.3.9 planning recovery checkpoint requires Mission state PLANNING or REPLANNING"
            )
        if int(state["state_version"]) != int(normalized["expected_state_version"]):
            raise MissionConcurrencyConflict("planning recovery expected_state_version is stale")
        before = self.get_mission_version_vector(mission_id)
        if before["version_sha256"] != normalized["expected_version_sha256"]:
            raise MissionConcurrencyConflict("planning recovery expected_version_sha256 is stale")

        active = self.repository.get_active_plan_version(mission_id)
        if active is None:
            raise MissionPlanningRecoveryGuardRejected(
                "Stage-3.3.9 planning recovery requires an active Stage-3.3.7 Plan version"
            )
        if not verify_plan_version_contract(active["plan_version_contract"]):
            raise MissionPlanningRecoveryGuardRejected("active Plan-version contract failed integrity verification")
        if active["plan_version_record_id"] != normalized["expected_active_plan_version_record_id"]:
            raise MissionConcurrencyConflict("expected_active_plan_version_record_id does not match active Plan head")
        if int(active["plan_version"]) != int(normalized["expected_active_plan_version"]):
            raise MissionConcurrencyConflict("expected_active_plan_version does not match active Plan head")
        if active["canonical_sha256"] != normalized["expected_active_plan_sha256"]:
            raise MissionConcurrencyConflict("expected_active_plan_sha256 does not match active Plan head")

        readiness = self.repository.get_task_readiness_projection_for_plan_version(
            mission_id, int(active["plan_version"])
        )
        if readiness is None:
            raise MissionPlanningRecoveryGuardRejected(
                "Stage-3.3.9 planning recovery requires the active Stage-3.3.8 readiness projection"
            )
        if not verify_task_readiness_projection_contract(readiness["projection_contract"]):
            raise MissionPlanningRecoveryGuardRejected("active readiness projection failed integrity verification")
        if readiness["projection_id"] != normalized["expected_task_readiness_projection_id"]:
            raise MissionConcurrencyConflict("expected_task_readiness_projection_id does not match active projection")
        if readiness["canonical_sha256"] != normalized["expected_task_readiness_projection_sha256"]:
            raise MissionConcurrencyConflict("expected_task_readiness_projection_sha256 does not match active projection")
        existing = self.repository.get_planning_recovery_checkpoint_for_plan_version(
            mission_id, int(active["plan_version"])
        )
        if existing is not None:
            raise MissionPlanningRecoveryConflict(
                "active Plan version already has an immutable Stage-3.3.9 planning recovery checkpoint"
            )

        # Prove all durable artifacts and the complete Mission event hash chain before freezing recovery state.
        self._build_repository_persistence_view(mission_id)
        events = self._verified_mission_events(mission_id)
        planning_replay = build_planning_event_replay(events)
        if int(planning_replay["planning_event_count"]) != int(normalized["expected_planning_event_count"]):
            raise MissionConcurrencyConflict("expected_planning_event_count is stale")
        if planning_replay["planning_event_tip_sha256"] != normalized["expected_planning_event_tip_sha256"]:
            raise MissionConcurrencyConflict("expected_planning_event_tip_sha256 is stale")
        if not events:
            raise MissionPlanningRecoveryGuardRejected("Mission event ledger is empty")

        checkpoint_version = len(self.repository.list_planning_recovery_checkpoints(mission_id)) + 1
        checkpoint_id = new_planning_recovery_checkpoint_id()
        created_at = utcnow_iso()
        contract = build_planning_recovery_checkpoint_contract(
            checkpoint_id=checkpoint_id,
            checkpoint_version=checkpoint_version,
            mission_id=mission_id,
            request_sha256=req_hash,
            source_state=state,
            source_version_sha256=before["version_sha256"],
            active_plan=active,
            readiness_projection=readiness,
            replay=planning_replay,
            created_by=normalized["created_by"],
            reason=normalized.get("reason"),
            metadata=normalized["metadata"],
            created_at=created_at,
        )
        if not verify_planning_recovery_checkpoint_contract(contract):
            raise RuntimeError("new Stage-3.3.9 planning recovery checkpoint failed self-verification")
        stored = self.repository.store_planning_recovery_checkpoint(
            mission_id=mission_id,
            checkpoint_id=checkpoint_id,
            checkpoint_version=checkpoint_version,
            plan_version_record_id=active["plan_version_record_id"],
            plan_version=int(active["plan_version"]),
            request_sha256=req_hash,
            idempotency_key=normalized["idempotency_key"],
            recovery_checkpoint=contract,
            expected_state_version=int(normalized["expected_state_version"]),
            source_version_sha256=before["version_sha256"],
            source_event_count=int(planning_replay["planning_event_count"]),
            source_event_tip_sha256=planning_replay["planning_event_tip_sha256"],
            readiness_projection_id=readiness["projection_id"],
            readiness_projection_sha256=readiness["canonical_sha256"],
            expected_active_plan_sha256=active["canonical_sha256"],
            expected_mission_event_tip_sha256=events[-1]["canonical_sha256"],
            actor=normalized["created_by"],
            reason=normalized.get("reason"),
            created_at=created_at,
        )
        self._record_mission_event(
            mission_id,
            PLANNING_RECOVERY_EVENT_TYPE,
            stored["checkpoint_id"],
            payload={
                "checkpoint_id": stored["checkpoint_id"],
                "checkpoint_version": int(stored["checkpoint_version"]),
                "plan_version_record_id": stored["plan_version_record_id"],
                "plan_version": int(stored["plan_version"]),
                "canonical_sha256": stored["canonical_sha256"],
                "source_planning_event_count": int(stored["source_event_count"]),
                "source_planning_event_tip_sha256": stored["source_event_tip_sha256"],
                "planning_replay_sha256": contract["source_bindings"]["planning_replay_sha256"],
                "planner_rerun_performed": False,
                "recovery_is_authorization": False,
                "dispatch_performed": False,
            },
            occurred_at=stored["created_at"],
            state_version=int(stored["source_state_version"]),
            plan_version=int(stored["plan_version"]),
        )
        return self._planning_recovery_checkpoint_response(stored, idempotent_replay=False)

    def get_active_planning_recovery_checkpoint(self, mission_id: str) -> Dict[str, Any]:
        if self.repository.get_by_mission_id(mission_id) is None:
            raise MissionNotFound(mission_id)
        head = self.repository.get_plan_version_head(mission_id)
        if head is None:
            raise MissionPlanningRecoveryNotFound(mission_id)
        stored = self.repository.get_planning_recovery_checkpoint_for_plan_version(
            mission_id, int(head["active_plan_version"])
        )
        if stored is None:
            raise MissionPlanningRecoveryNotFound(mission_id)
        return self._planning_recovery_checkpoint_response(stored, idempotent_replay=False)

    def get_planning_recovery_history(self, mission_id: str) -> Dict[str, Any]:
        if self.repository.get_by_mission_id(mission_id) is None:
            raise MissionNotFound(mission_id)
        rows = self.repository.list_planning_recovery_checkpoints(mission_id)
        if not rows:
            raise MissionPlanningRecoveryNotFound(mission_id)
        return {
            "status": "completed",
            "component_id": COMPONENT_ID,
            "control_version": CONTROL_VERSION,
            "mission_id": mission_id,
            "checkpoint_count": len(rows),
            "checkpoints": [self._planning_recovery_checkpoint_response(row, idempotent_replay=False) for row in rows],
            "planner_rerun_performed": False,
            "governance_authorization_authority": "EXTERNAL_APTS_GSS",
            "target_action_dispatch_enabled": False,
            "target_actuation": False,
        }

    def recover_planning_state(self, mission_id: str) -> Dict[str, Any]:
        checkpoint = self.get_active_planning_recovery_checkpoint(mission_id)
        active = self.repository.get_active_plan_version(mission_id)
        readiness = self.repository.get_task_readiness_projection_for_plan_version(
            mission_id, checkpoint["plan_version"]
        )
        if active is None or readiness is None:
            raise MissionPlanningRecoveryGuardRejected("durable recovery artifacts are incomplete")
        recovery = checkpoint["recovery_state"]
        consistent = (
            active["plan_version_record_id"] == recovery["active_plan_version_record_id"]
            and int(active["plan_version"]) == int(recovery["active_plan_version"])
            and active["canonical_sha256"] == recovery["active_plan_sha256"]
            and readiness["projection_id"] == recovery["task_readiness_projection_id"]
            and readiness["canonical_sha256"] == recovery["task_readiness_projection_sha256"]
        )
        if not consistent:
            raise MissionPlanningRecoveryGuardRejected("durable recovery checkpoint does not match the current active Plan/readiness head")
        # Full repository + event integrity is required before exposing recovered state.
        repository = self._build_repository_persistence_view(mission_id)
        return {
            "status": "completed",
            "component_id": COMPONENT_ID,
            "control_version": CONTROL_VERSION,
            "mission_id": mission_id,
            "recovery_schema_version": PLANNING_RECOVERY_CHECKPOINT_SCHEMA_VERSION,
            "recovery_mode": PLANNING_RECOVERY_MODE,
            "checkpoint_id": checkpoint["checkpoint_id"],
            "checkpoint_version": checkpoint["checkpoint_version"],
            "recovered_state": recovery,
            "recovery_consistency": "PASS",
            "repository_integrity_status": repository["integrity_status"],
            "repository_sha256": repository["repository_sha256"],
            "recovered_from_durable_repository": True,
            "planner_rerun_performed": False,
            "external_model_invocation_performed": False,
            "external_network_io_performed": False,
            "governance_authorization_query_performed": False,
            "target_action_dispatch_enabled": False,
            "target_actuation": False,
        }

    def get_planning_event_lineage_definition(self, mission_id: str) -> Dict[str, Any]:
        if self.repository.get_by_mission_id(mission_id) is None:
            raise MissionNotFound(mission_id)
        head = self.repository.get_plan_version_head(mission_id)
        active_checkpoint = None if head is None else self.repository.get_planning_recovery_checkpoint_for_plan_version(
            mission_id, int(head["active_plan_version"])
        )
        return {
            "status": "completed",
            "component_id": COMPONENT_ID,
            "control_version": CONTROL_VERSION,
            "mission_id": mission_id,
            "active_plan_head": head,
            "active_recovery_checkpoint_registered": active_checkpoint is not None,
            "registered_checkpoint_count": len(self.repository.list_planning_recovery_checkpoints(mission_id)),
            "planning_event_lineage_definition": canonical_planning_event_lineage_definition(),
        }

    @staticmethod
    def _mission_command_payload(stored: Dict[str, Any], *, idempotent_replay: bool) -> Dict[str, Any]:
        return {
            "status": "completed" if stored["status"] == "COMPLETED" else stored["status"].lower(),
            "component_id": COMPONENT_ID,
            "control_version": CONTROL_VERSION,
            "command_schema_version": stored["schema_version"],
            "concurrency_mode": CONCURRENCY_MODE,
            "mission_id": stored["mission_id"],
            "command_id": stored["command_id"],
            "idempotency_key": stored["idempotency_key"],
            "idempotent_replay": idempotent_replay,
            "operation": stored["operation"],
            "expected_version_sha256": stored["expected_version_sha256"],
            "command_status": stored["status"],
            "before_version_vector": stored.get("before_version_vector"),
            "after_version_vector": stored.get("after_version_vector"),
            "result": stored.get("result"),
            "submitted_by": stored["submitted_by"],
            "metadata": stored.get("metadata") or {},
            "last_error": stored.get("last_error"),
            "created_at": stored["created_at"],
            "updated_at": stored["updated_at"],
        }

    @staticmethod
    def _assert_command_payload_version(operation: str, payload: Dict[str, Any], vector: Dict[str, Any]) -> None:
        versions = vector["versions"]
        if operation in {"STATE_TRANSITION", LIFECYCLE_COMMAND_OPERATION}:
            try:
                expected = int(payload.get("expected_state_version"))
            except (TypeError, ValueError) as exc:
                raise MissionConcurrencyConflict(
                    f"{operation} command payload must carry expected_state_version"
                ) from exc
            if expected != int(versions["state_version"]):
                raise MissionConcurrencyConflict(
                    f"command payload expected_state_version={expected} does not match guarded state_version={versions['state_version']}"
                )
        elif operation == "SCOPE_CONTRACT_PUT":
            try:
                expected = int(payload.get("expected_contract_version"))
            except (TypeError, ValueError) as exc:
                raise MissionConcurrencyConflict(
                    "SCOPE_CONTRACT_PUT command payload must carry expected_contract_version"
                ) from exc
            if expected != int(versions["scope_contract_version"]):
                raise MissionConcurrencyConflict(
                    "command payload expected_contract_version does not match guarded scope_contract_version"
                )
        elif operation == "GOVERNANCE_BINDING_PUT":
            try:
                expected = int(payload.get("expected_binding_version"))
            except (TypeError, ValueError) as exc:
                raise MissionConcurrencyConflict(
                    "GOVERNANCE_BINDING_PUT command payload must carry expected_binding_version"
                ) from exc
            if expected != int(versions["governance_binding_version"]):
                raise MissionConcurrencyConflict(
                    "command payload expected_binding_version does not match guarded governance_binding_version"
                )
        elif operation == "ROUTING_TASK_DISPATCH":
            task_id = payload.get("task_id")
            if not isinstance(task_id, str) or not task_id.strip():
                raise MissionConcurrencyConflict("ROUTING_TASK_DISPATCH command payload requires task_id")
            if set(payload) != {"task_id"}:
                raise MissionConcurrencyConflict("ROUTING_TASK_DISPATCH command payload only accepts task_id")

    def _execute_guarded_operation(self, mission_id: str, operation: str, payload: Dict[str, Any]) -> Dict[str, Any]:
        if operation == LIFECYCLE_COMMAND_OPERATION:
            # Validate and enforce the Stage-3.2 lifecycle guard chain at the
            # guarded-operation boundary as well, so callers of the generic /commands
            # API cannot bypass command semantics, local prerequisites, or activation
            # lineage. Version-vector/state-version checks completed before this point.
            normalized = normalize_lifecycle_operation_payload(payload)
            stored = self.repository.get_by_mission_id(mission_id)
            if stored is None:
                raise MissionNotFound(mission_id)
            state = self.repository.get_state(mission_id)
            if state is None:
                raise RuntimeError("mission exists without canonical state projection")
            state_transitions = self.repository.list_state_transitions(mission_id)
            guard = enforce_lifecycle_guard(
                mission_id=mission_id,
                envelope=stored.envelope,
                current_state=state,
                command=normalized["command"],
                target_state=normalized["target_state"],
                state_transitions=state_transitions,
                request_metadata=normalized.get("metadata") or {},
                evidence_refs=list(normalized.get("evidence_refs") or []),
                request_context_provided=True,
            )
            transition_request = lifecycle_transition_request(payload)
            activation = None
            planning_run_activation = None
            waiting_dependency = None
            waiting_dependency_resolution = None
            pause_control = None
            resume_control = None
            replan_control = None
            replan_resolution = None
            cleanup_control = None
            completion_verification = None
            terminal_control = None
            if normalized["command"] == ACTIVATION_COMMAND:
                activation = mission_activation_evidence(
                    mission_id=mission_id,
                    envelope=stored.envelope,
                    current_state=state,
                )
                if not activation["activation_ready"]:
                    # Defensive invariant. The Stage-3.2 guard should already have
                    # rejected every non-ready activation before reaching this point.
                    raise MissionLifecycleGuardRejected(
                        "BIND_PIP activation reached commit boundary without a ready Stage-3.2.3 activation contract"
                    )
                transition_request["metadata"] = dict(transition_request.get("metadata") or {})
                transition_request["metadata"]["mission_activation"] = activation
            if (
                normalized["command"] == PLANNING_ACTIVATION_COMMAND
                or (normalized["command"] == RUN_ACTIVATION_COMMAND and state["state"] == "PLANNING")
            ):
                planning_run_activation = planning_run_activation_evidence(
                    mission_id=mission_id,
                    envelope=stored.envelope,
                    current_state=state,
                    state_transitions=state_transitions,
                    command=normalized["command"],
                )
                if not planning_run_activation["activation_ready"]:
                    raise MissionLifecycleGuardRejected(
                        f"{normalized['command']} reached commit boundary without ready Stage-3.2.4 planning/run activation lineage"
                    )
                transition_request["metadata"] = dict(transition_request.get("metadata") or {})
                transition_request["metadata"]["mission_planning_run_activation"] = planning_run_activation
            if normalized["command"] in WAIT_COMMAND_KIND:
                waiting_dependency = waiting_dependency_declaration_evidence(
                    mission_id=mission_id,
                    current_state=state,
                    command=normalized["command"],
                    metadata=normalized.get("metadata") or {},
                    evidence_refs=list(normalized.get("evidence_refs") or []),
                    actor=normalized["actor"],
                )
                transition_request["metadata"] = dict(transition_request.get("metadata") or {})
                transition_request["metadata"]["mission_waiting_dependency"] = waiting_dependency
            if normalized["command"] == "START" and state["state"] in {"WAITING_EVIDENCE", "WAITING_APPROVAL"}:
                waiting_dependency_resolution = waiting_dependency_resolution_evidence(
                    mission_id=mission_id,
                    current_state=state,
                    state_transitions=state_transitions,
                    metadata=normalized.get("metadata") or {},
                    evidence_refs=list(normalized.get("evidence_refs") or []),
                )
                transition_request["metadata"] = dict(transition_request.get("metadata") or {})
                transition_request["metadata"]["mission_waiting_dependency_resolution"] = waiting_dependency_resolution
            if normalized["command"] == "PAUSE":
                pause_control = pause_control_evidence(
                    mission_id=mission_id,
                    current_state=state,
                    state_transitions=state_transitions,
                    actor=normalized["actor"],
                    reason_code=normalized["reason_code"],
                    reason=normalized.get("reason"),
                    evidence_refs=list(normalized.get("evidence_refs") or []),
                )
                transition_request["metadata"] = dict(transition_request.get("metadata") or {})
                transition_request["metadata"]["mission_pause_control"] = pause_control
            if normalized["command"] == "RESUME":
                resume_control = resume_control_evidence(
                    mission_id=mission_id,
                    envelope=stored.envelope,
                    current_state=state,
                    state_transitions=state_transitions,
                    target_state=normalized["target_state"],
                    actor=normalized["actor"],
                    evidence_refs=list(normalized.get("evidence_refs") or []),
                )
                transition_request["metadata"] = dict(transition_request.get("metadata") or {})
                transition_request["metadata"]["mission_resume_control"] = resume_control
                if normalized["target_state"] == "REPLANNING":
                    replan_control = replan_control_evidence(
                        mission_id=mission_id,
                        current_state=state,
                        state_transitions=state_transitions,
                        actor=normalized["actor"],
                        reason_code=normalized["reason_code"],
                        reason=normalized.get("reason"),
                        evidence_refs=list(normalized.get("evidence_refs") or []),
                        origin=f"RESUME_FROM_{resume_control['paused_from_state']}",
                    )
                    replan_control["abandoned_waiting_dependency"] = resume_control.get("active_waiting_dependency")
                    replan_control["continued_replan"] = resume_control.get("paused_from_state") == "REPLANNING"
                    transition_request["metadata"]["mission_replan_control"] = replan_control
            if normalized["command"] == "REPLAN":
                replan_control = replan_control_evidence(
                    mission_id=mission_id,
                    current_state=state,
                    state_transitions=state_transitions,
                    actor=normalized["actor"],
                    reason_code=normalized["reason_code"],
                    reason=normalized.get("reason"),
                    evidence_refs=list(normalized.get("evidence_refs") or []),
                )
                transition_request["metadata"] = dict(transition_request.get("metadata") or {})
                transition_request["metadata"]["mission_replan_control"] = replan_control
            if normalized["command"] == "START" and state["state"] == "REPLANNING":
                active_version = self.repository.get_active_plan_version(mission_id)
                if active_version is not None:
                    active_replan = self._active_replan_lineage(state_transitions)
                    if (
                        active_replan is None
                        or active_version.get("activation_type") != PLAN_VERSIONING_REPLAN_ACTIVATION_TYPE
                        or active_version.get("replan_id") != active_replan.get("replan_id")
                    ):
                        raise MissionLifecycleGuardRejected(
                            "Stage 3.3.7 blocks REPLANNING->RUNNING until the active replan episode has a committed successor Plan version"
                        )
                replan_resolution = replan_resolution_evidence(
                    mission_id=mission_id,
                    current_state=state,
                    state_transitions=state_transitions,
                    actor=normalized["actor"],
                    evidence_refs=list(normalized.get("evidence_refs") or []),
                )
                transition_request["metadata"] = dict(transition_request.get("metadata") or {})
                transition_request["metadata"]["mission_replan_resolution"] = replan_resolution
            if normalized["command"] == CLEANUP_COMMAND:
                cleanup_control = cleanup_control_evidence(
                    mission_id=mission_id,
                    envelope=stored.envelope,
                    current_state=state,
                    state_transitions=state_transitions,
                    actor=normalized["actor"],
                    reason_code=normalized["reason_code"],
                    reason=normalized.get("reason"),
                    evidence_refs=list(normalized.get("evidence_refs") or []),
                    metadata=normalized.get("metadata") or {},
                )
                transition_request["metadata"] = dict(transition_request.get("metadata") or {})
                transition_request["metadata"]["mission_cleanup_control"] = cleanup_control
            if normalized["command"] == COMPLETION_COMMAND:
                completion_verification = completion_verification_evidence(
                    mission_id=mission_id,
                    envelope=stored.envelope,
                    current_state=state,
                    state_transitions=state_transitions,
                    actor=normalized["actor"],
                    reason_code=normalized["reason_code"],
                    reason=normalized.get("reason"),
                    evidence_refs=list(normalized.get("evidence_refs") or []),
                    metadata=normalized.get("metadata") or {},
                )
                transition_request["metadata"] = dict(transition_request.get("metadata") or {})
                transition_request["metadata"]["mission_completion_verification"] = completion_verification
            if normalized["command"] in TERMINAL_COMMAND_TARGETS and state["state"] not in TERMINAL_STATES:
                terminal_control = terminal_control_evidence(
                    mission_id=mission_id,
                    current_state=state,
                    state_transitions=state_transitions,
                    command=normalized["command"],
                    actor=normalized["actor"],
                    reason_code=normalized["reason_code"],
                    reason=normalized.get("reason"),
                    evidence_refs=list(normalized.get("evidence_refs") or []),
                    metadata=normalized.get("metadata") or {},
                )
                transition_request["metadata"] = dict(transition_request.get("metadata") or {})
                transition_request["metadata"]["mission_terminal_control"] = terminal_control
            result = self.transition_mission_state(mission_id, transition_request)
            result["lifecycle_guard"] = guard
            if activation is not None:
                result["mission_activation"] = activation
            if planning_run_activation is not None:
                result["planning_run_activation"] = planning_run_activation
            if waiting_dependency is not None:
                result["waiting_dependency"] = waiting_dependency
            if waiting_dependency_resolution is not None:
                result["waiting_dependency_resolution"] = waiting_dependency_resolution
            if pause_control is not None:
                result["pause_control"] = pause_control
            if resume_control is not None:
                result["resume_control"] = resume_control
            if replan_control is not None:
                result["replan_control"] = replan_control
            if replan_resolution is not None:
                result["replan_resolution"] = replan_resolution
            if cleanup_control is not None:
                result["cleanup_control"] = cleanup_control
            if completion_verification is not None:
                result["completion_verification"] = completion_verification
            if terminal_control is not None:
                result["terminal_control"] = terminal_control
            return result
        if operation == "STATE_TRANSITION":
            return self.transition_mission_state(mission_id, payload)
        if operation == "SCOPE_CONTRACT_PUT":
            return self.put_mission_scope_contract(mission_id, payload)
        if operation == "GOVERNANCE_BINDING_PUT":
            return self.put_mission_governance_binding(mission_id, payload)
        if operation == "AUTHORIZATION_BINDING_CREATE":
            return self.authorize_mission_capability(mission_id, payload)
        if operation == "ROUTING_TASK_CREATE":
            return self.create_governed_routing_task(mission_id, payload)
        if operation == "ROUTING_TASK_DISPATCH":
            return self.dispatch_governed_routing_task(mission_id, payload["task_id"])
        raise MissionCommandConflict(f"unsupported guarded command operation={operation}")

    def get_mission_activation_contract(self, mission_id: str) -> Dict[str, Any]:
        stored = self.repository.get_by_mission_id(mission_id)
        if stored is None:
            raise MissionNotFound(mission_id)
        state = self.repository.get_state(mission_id)
        if state is None:
            raise RuntimeError("mission exists without canonical state projection")
        activation = mission_activation_contract(
            mission_id=mission_id,
            envelope=stored.envelope,
            current_state=state,
        )
        return {
            "status": "completed",
            "mission_id": mission_id,
            "mission_state": state,
            "mission_activation": activation,
            "governance_authorization_authority": "EXTERNAL_APTS_GSS",
            "pip_artifact_query_performed": False,
            "authority_query_performed": False,
            "target_action_dispatch_enabled": False,
            "target_actuation": False,
        }

