    def get_mission_lifecycle_automation_contract(self, mission_id: str) -> Dict[str, Any]:
        stored = self.repository.get_by_mission_id(mission_id)
        if stored is None:
            raise MissionNotFound(mission_id)
        state = self.repository.get_state(mission_id)
        if state is None:
            raise RuntimeError("mission exists without canonical state projection")
        vector = self._build_mission_version_vector(mission_id)
        contract = lifecycle_automation_contract()
        eligible = [
            event_type
            for event_type in LIFECYCLE_AUTOMATION_EVENT_TYPES
            if state["state"] in contract["event_source_states"].get(event_type, [])
        ]
        return {
            "status": "completed",
            "mission_id": mission_id,
            "mission_state": state,
            "version_vector_complete": vector["complete"],
            "version_sha256": vector["integrity"]["canonical_sha256"],
            "lifecycle_automation": {
                **contract,
                "eligible_event_types_for_current_state": eligible,
            },
            "governance_authorization_authority": "EXTERNAL_APTS_GSS",
            "external_event_delivery_enabled": False,
            "authority_query_performed": False,
            "planner_invocation_performed": False,
            "target_action_dispatch_enabled": False,
            "target_actuation": False,
        }

    def get_mission_lifecycle_command_contract(self, mission_id: str) -> Dict[str, Any]:
        stored = self.repository.get_by_mission_id(mission_id)
        if stored is None:
            raise MissionNotFound(mission_id)
        state = self.repository.get_state(mission_id)
        if state is None:
            raise RuntimeError("mission exists without canonical state projection")

        topology_targets = set(allowed_targets(state["state"]))
        state_transitions = self.repository.list_state_transitions(mission_id)
        contract = lifecycle_command_contract()
        topology_eligible: list[str] = []
        guard_eligible: list[str] = []
        guard_evaluations: list[Dict[str, Any]] = []
        guard_resume_targets: list[str] = []

        for command in LIFECYCLE_COMMANDS:
            if command == "RESUME":
                topology_resume_targets = (
                    [target for target in RESUME_TARGETS if target in topology_targets]
                    if state["state"] == "PAUSED"
                    else []
                )
                if topology_resume_targets:
                    topology_eligible.append(command)
                for target in topology_resume_targets:
                    evaluation = evaluate_lifecycle_guard(
                        mission_id=mission_id,
                        envelope=stored.envelope,
                        current_state=state,
                        command=command,
                        target_state=target,
                        state_transitions=state_transitions,
                    )
                    guard_evaluations.append(evaluation)
                    if evaluation["allowed"]:
                        guard_resume_targets.append(target)
                if guard_resume_targets:
                    guard_eligible.append(command)
                continue

            target = contract["fixed_target_states"][command]
            if target in topology_targets:
                topology_eligible.append(command)
            evaluation = evaluate_lifecycle_guard(
                mission_id=mission_id,
                envelope=stored.envelope,
                current_state=state,
                command=command,
                target_state=target,
                state_transitions=state_transitions,
            )
            guard_evaluations.append(evaluation)
            if evaluation["allowed"]:
                guard_eligible.append(command)

        return {
            "status": "completed",
            "mission_id": mission_id,
            "mission_state": state,
            "lifecycle_command_contract": contract,
            "lifecycle_guard_matrix": lifecycle_guard_matrix_contract(),
            "mission_activation": mission_activation_contract(
                mission_id=mission_id, envelope=stored.envelope, current_state=state
            ),
            "planning_run_activation": planning_run_activation_contract(
                mission_id=mission_id,
                envelope=stored.envelope,
                current_state=state,
                state_transitions=state_transitions,
            ),
            "waiting_dependency": waiting_dependency_contract(
                mission_id=mission_id,
                current_state=state,
                state_transitions=state_transitions,
            ),
            "pause_resume_replan": pause_resume_replan_contract(
                mission_id=mission_id,
                envelope=stored.envelope,
                current_state=state,
                state_transitions=state_transitions,
            ),
            "terminal_semantics": terminal_semantics_contract(
                mission_id=mission_id,
                envelope=stored.envelope,
                current_state=state,
                state_transitions=state_transitions,
            ),
            "cleanup_completion": cleanup_completion_contract(
                mission_id=mission_id,
                envelope=stored.envelope,
                current_state=state,
                state_transitions=state_transitions,
            ),
            "event_driven_lifecycle_automation": {
                **lifecycle_automation_contract(),
                "eligible_event_types_for_current_state": [
                    event_type
                    for event_type in LIFECYCLE_AUTOMATION_EVENT_TYPES
                    if state["state"] in lifecycle_automation_contract()["event_source_states"].get(event_type, [])
                ],
            },
            "topology_eligible_commands": topology_eligible,
            "guard_eligible_commands": guard_eligible,
            "guard_eligible_resume_targets": guard_resume_targets,
            "guard_evaluations": guard_evaluations,
            "eligibility_semantics": "STAGE_3_2_9_LOCAL_GUARD_ACTIVATION_WAIT_PAUSE_RESUME_REPLAN_TYPED_TERMINATION_CONTROL_VERIFIED_COMPLETION_AND_EVENT_AUTOMATION_PROPOSAL_CONTROL_NOT_GOVERNANCE_AUTHORIZATION",
            "request_specific_guard_semantics": "WAIT_DECLARATION_WAIT_RETURN_REPLAN_READINESS_AND_COMPLETION_VERIFICATION_EVIDENCE_ARE_VALIDATED_AT_EXECUTION",
            "governance_authorization_authority": "EXTERNAL_APTS_GSS",
            "authority_query_performed": False,
            "target_action_dispatch_enabled": False,
            "target_actuation": False,
        }

    @staticmethod
    def _raise_stored_lifecycle_automation_rejection(payload: Dict[str, Any]) -> None:
        message = str(payload.get("message") or "mission lifecycle automation event was previously rejected")
        error_type = str(payload.get("error_type") or "MissionCommandConflict")
        mapping = {
            "MissionConcurrencyConflict": MissionConcurrencyConflict,
            "MissionStateConflict": MissionStateConflict,
            "MissionIllegalTransition": MissionIllegalTransition,
            "MissionVersionObservationUnavailable": MissionVersionObservationUnavailable,
            "MissionLifecycleGuardRejected": MissionLifecycleGuardRejected,
            "MissionValidationError": MissionValidationError,
            "MissionCommandConflict": MissionCommandConflict,
        }
        raise mapping.get(error_type, MissionCommandConflict)(message)

    def _lifecycle_automation_response(
        self,
        *,
        mission_id: str,
        normalized: Dict[str, Any],
        signal_sha256: str,
        automation_key: str,
        command_result: Dict[str, Any],
        receipt_event: Dict[str, Any],
        outcome_event: Dict[str, Any],
        idempotent_replay: bool,
    ) -> Dict[str, Any]:
        return {
            "status": "completed",
            "component_id": COMPONENT_ID,
            "control_version": CONTROL_VERSION,
            "lifecycle_automation_schema_version": LIFECYCLE_AUTOMATION_SCHEMA_VERSION,
            "lifecycle_automation_mode": LIFECYCLE_AUTOMATION_MODE,
            "mission_id": mission_id,
            "source_event": normalized,
            "source_event_sha256": signal_sha256,
            "automation_key": automation_key,
            "idempotent_replay": bool(idempotent_replay),
            "automation_status": "APPLIED",
            "proposed_lifecycle_command": EVENT_TO_COMMAND[normalized["event_type"]],
            "lifecycle_command_result": command_result,
            "mission_state": command_result.get("mission_state"),
            "transition": command_result.get("transition"),
            "receipt_event": receipt_event,
            "outcome_event": outcome_event,
            "authority_semantics": LIFECYCLE_AUTOMATION_AUTHORITY_SEMANTICS,
            "governance_authorization_authority": "EXTERNAL_APTS_GSS",
            "governance_authorization_query_performed": False,
            "planner_invocation_performed": False,
            "target_action_dispatch_enabled": False,
            "target_actuation": False,
        }

    def process_mission_lifecycle_event(self, mission_id: str, payload: Any) -> Dict[str, Any]:
        if self.repository.get_by_mission_id(mission_id) is None:
            raise MissionNotFound(mission_id)

        normalized = normalize_lifecycle_automation_event(payload)
        signal_sha256 = lifecycle_automation_event_fingerprint(normalized)
        automation_key = lifecycle_automation_key(normalized)
        generated_command = build_lifecycle_automation_command(normalized)

        with self._concurrency_lock:
            receipt = self.repository.get_mission_event_by_causation(
                mission_id, MISSION_LIFECYCLE_EVENT_RECEIVED, automation_key
            )
            if receipt is not None:
                receipt_sha = str((receipt.get("payload") or {}).get("signal_sha256") or "")
                if receipt_sha != signal_sha256:
                    raise MissionCommandConflict(
                        "source lifecycle event identity is already bound to a different canonical event payload"
                    )

                applied = self.repository.get_mission_event_by_causation(
                    mission_id, MISSION_LIFECYCLE_EVENT_APPLIED, automation_key
                )
                if applied is not None:
                    replayed_command = self.execute_mission_lifecycle_command(mission_id, generated_command)
                    return self._lifecycle_automation_response(
                        mission_id=mission_id,
                        normalized=normalized,
                        signal_sha256=signal_sha256,
                        automation_key=automation_key,
                        command_result=replayed_command,
                        receipt_event=receipt,
                        outcome_event=applied,
                        idempotent_replay=True,
                    )

                rejected = self.repository.get_mission_event_by_causation(
                    mission_id, MISSION_LIFECYCLE_EVENT_REJECTED, automation_key
                )
                if rejected is not None:
                    self._raise_stored_lifecycle_automation_rejection(rejected.get("payload") or {})
            else:
                receipt = self._record_mission_event(
                    mission_id,
                    MISSION_LIFECYCLE_EVENT_RECEIVED,
                    automation_key,
                    payload={
                        "upstream_event_id": normalized["event_id"],
                        "upstream_source_component": normalized["source_component"],
                        "upstream_event_type": normalized["event_type"],
                        "upstream_occurred_at": normalized["occurred_at"],
                        "signal_sha256": signal_sha256,
                        "observed_state": normalized["observed_state"],
                        "observed_state_version": normalized["observed_state_version"],
                        "observed_version_sha256": normalized["observed_version_sha256"],
                        "proposed_lifecycle_command": EVENT_TO_COMMAND[normalized["event_type"]],
                        "automation_command_id": generated_command["command_id"],
                        "automation_idempotency_key": generated_command["idempotency_key"],
                        "blind_state_mutation_allowed": False,
                    },
                )

            try:
                state = self.repository.get_state(mission_id)
                if state is None:
                    raise RuntimeError("mission exists without canonical state projection")
                vector = self._build_mission_version_vector(mission_id)
                current_sha = vector["integrity"]["canonical_sha256"]
                if not vector["complete"]:
                    raise MissionVersionObservationUnavailable(
                        "mission lifecycle automation requires a complete current version vector before event application"
                    )
                if state["state"] != normalized["observed_state"]:
                    raise MissionConcurrencyConflict(
                        f"lifecycle event observed_state={normalized['observed_state']} does not match current state={state['state']}"
                    )
                if int(state["state_version"]) != int(normalized["observed_state_version"]):
                    raise MissionConcurrencyConflict(
                        f"lifecycle event observed_state_version={normalized['observed_state_version']} does not match current state_version={state['state_version']}"
                    )
                if current_sha != normalized["observed_version_sha256"]:
                    raise MissionConcurrencyConflict(
                        f"lifecycle event observed_version_sha256={normalized['observed_version_sha256']} does not match current version_sha256={current_sha}"
                    )

                command_result = self.execute_mission_lifecycle_command(mission_id, generated_command)
            except (
                MissionConcurrencyConflict,
                MissionStateConflict,
                MissionIllegalTransition,
                MissionVersionObservationUnavailable,
                MissionLifecycleGuardRejected,
                MissionValidationError,
                MissionCommandConflict,
            ) as exc:
                rejected = self._record_mission_event(
                    mission_id,
                    MISSION_LIFECYCLE_EVENT_REJECTED,
                    automation_key,
                    payload={
                        "upstream_event_id": normalized["event_id"],
                        "upstream_source_component": normalized["source_component"],
                        "upstream_event_type": normalized["event_type"],
                        "signal_sha256": signal_sha256,
                        "proposed_lifecycle_command": EVENT_TO_COMMAND[normalized["event_type"]],
                        "automation_command_id": generated_command["command_id"],
                        "error_type": exc.__class__.__name__,
                        "message": str(exc),
                        "state_mutated_by_rejected_event": False,
                    },
                )
                _ = rejected
                raise

            transition = command_result.get("transition") or {}
            applied = self._record_mission_event(
                mission_id,
                MISSION_LIFECYCLE_EVENT_APPLIED,
                automation_key,
                payload={
                    "upstream_event_id": normalized["event_id"],
                    "upstream_source_component": normalized["source_component"],
                    "upstream_event_type": normalized["event_type"],
                    "signal_sha256": signal_sha256,
                    "automation_command_id": generated_command["command_id"],
                    "lifecycle_command": command_result.get("lifecycle_command"),
                    "resolved_target_state": command_result.get("resolved_target_state"),
                    "transition_id": transition.get("transition_id"),
                    "from_state": transition.get("from_state"),
                    "to_state": transition.get("to_state"),
                    "resulting_state_version": (command_result.get("mission_state") or {}).get("state_version"),
                    "existing_command_journal_used": True,
                    "stage3_2_guard_chain_used": True,
                    "direct_state_transition_bypass_used": False,
                },
            )
            return self._lifecycle_automation_response(
                mission_id=mission_id,
                normalized=normalized,
                signal_sha256=signal_sha256,
                automation_key=automation_key,
                command_result=command_result,
                receipt_event=receipt,
                outcome_event=applied,
                idempotent_replay=bool(receipt.get("idempotent_replay")),
            )

    def execute_mission_lifecycle_command(self, mission_id: str, payload: Any) -> Dict[str, Any]:
        if self.repository.get_by_mission_id(mission_id) is None:
            raise MissionNotFound(mission_id)
        normalized = normalize_lifecycle_command_request(payload)
        guarded = build_guarded_lifecycle_command(normalized)
        command_result = self.execute_mission_command(mission_id, guarded)
        stored_result = command_result.get("result") or {}
        return {
            "status": command_result["status"],
            "component_id": COMPONENT_ID,
            "control_version": CONTROL_VERSION,
            "lifecycle_command_schema_version": LIFECYCLE_COMMAND_SCHEMA_VERSION,
            "lifecycle_command_mode": LIFECYCLE_COMMAND_MODE,
            "mission_id": mission_id,
            "command_id": normalized["command_id"],
            "idempotency_key": normalized["idempotency_key"],
            "idempotent_replay": command_result["idempotent_replay"],
            "lifecycle_command": normalized["command"],
            "resolved_target_state": normalized["target_state"],
            "command_status": command_result["command_status"],
            "mission_state": stored_result.get("mission_state"),
            "transition": stored_result.get("transition"),
            "lifecycle_guard": stored_result.get("lifecycle_guard"),
            "mission_activation": stored_result.get("mission_activation"),
            "planning_run_activation": stored_result.get("planning_run_activation"),
            "waiting_dependency": stored_result.get("waiting_dependency"),
            "waiting_dependency_resolution": stored_result.get("waiting_dependency_resolution"),
            "pause_control": stored_result.get("pause_control"),
            "resume_control": stored_result.get("resume_control"),
            "replan_control": stored_result.get("replan_control"),
            "replan_resolution": stored_result.get("replan_resolution"),
            "cleanup_control": stored_result.get("cleanup_control"),
            "completion_verification": stored_result.get("completion_verification"),
            "terminal_control": stored_result.get("terminal_control"),
            "guarded_command": command_result,
            "governance_authorization_authority": "EXTERNAL_APTS_GSS",
            "target_action_dispatch_enabled": False,
            "target_actuation": False,
        }

    def execute_mission_command(self, mission_id: str, payload: Any) -> Dict[str, Any]:
        if self.repository.get_by_mission_id(mission_id) is None:
            raise MissionNotFound(mission_id)
        normalized = normalize_command_request(payload)
        req_hash = command_request_fingerprint(normalized)

        with self._concurrency_lock:
            journal, replay = self.repository.start_mission_command(
                mission_id=mission_id,
                command_id=normalized["command_id"],
                idempotency_key=normalized["idempotency_key"],
                operation=normalized["operation"],
                request_sha256=req_hash,
                expected_version_sha256=normalized["expected_version_sha256"],
                submitted_by=normalized["submitted_by"],
                metadata=normalized["metadata"],
                created_at=utcnow_iso(),
            )
            if replay:
                if journal["status"] == "COMPLETED":
                    return self._mission_command_payload(journal, idempotent_replay=True)
                if journal["status"] == "REJECTED_STALE":
                    raise MissionConcurrencyConflict(
                        journal.get("last_error") or "mission command was rejected because its version vector was stale"
                    )
                if journal["status"] == "FAILED_OBSERVATION":
                    raise MissionVersionObservationUnavailable(
                        journal.get("last_error") or "mission version observation was unavailable"
                    )
                if journal["status"] == "PENDING":
                    raise MissionCommandConflict("mission command is already in progress")
                raise MissionCommandConflict(
                    journal.get("last_error") or f"mission command is in non-replayable status={journal['status']}"
                )

            before = self._build_mission_version_vector(mission_id)
            actual_sha = before["integrity"]["canonical_sha256"]
            if not before["complete"]:
                message = (
                    "mission version vector is incomplete because a required subsystem version observation "
                    "is unavailable or inconsistent; guarded mutation fails closed"
                )
                self.repository.update_mission_command(
                    normalized["command_id"],
                    status="FAILED_OBSERVATION",
                    before_version_vector=before,
                    last_error=message,
                    updated_at=utcnow_iso(),
                )
                raise MissionVersionObservationUnavailable(message)

            if normalized["expected_version_sha256"] != actual_sha:
                message = (
                    f"expected_version_sha256={normalized['expected_version_sha256']} does not match "
                    f"current mission version_sha256={actual_sha}"
                )
                self.repository.update_mission_command(
                    normalized["command_id"],
                    status="REJECTED_STALE",
                    before_version_vector=before,
                    last_error=message,
                    updated_at=utcnow_iso(),
                )
                raise MissionConcurrencyConflict(message)

            try:
                self._assert_command_payload_version(normalized["operation"], normalized["payload"], before)
                result = self._execute_guarded_operation(
                    mission_id, normalized["operation"], normalized["payload"]
                )
                after = self._build_mission_version_vector(mission_id)
                # The pre-command vector must be complete before mutation. If a downstream
                # observer becomes unavailable only after the operation has committed, do
                # not misreport the command as uncommitted; persist the exact result plus
                # the incomplete post-command observation for deterministic replay/audit.
                command_completed_at = utcnow_iso()
                self.repository.update_mission_command(
                    normalized["command_id"],
                    status="COMPLETED",
                    before_version_vector=before,
                    after_version_vector=after,
                    result=result,
                    last_error=None,
                    updated_at=command_completed_at,
                )
                self._record_mission_event(
                    mission_id,
                    "MISSION_COMMAND_COMPLETED",
                    normalized["command_id"],
                    payload={
                        "command_id": normalized["command_id"],
                        "operation": normalized["operation"],
                        "before_version_sha256": before["integrity"]["canonical_sha256"],
                        "after_version_sha256": after["integrity"]["canonical_sha256"],
                    },
                    occurred_at=command_completed_at,
                )
                stored_command = self.repository.get_mission_command(mission_id, normalized["command_id"])
                if stored_command is None:
                    raise RuntimeError("completed mission command cannot be read back")
                return self._mission_command_payload(stored_command, idempotent_replay=False)
            except Exception as exc:
                current = self.repository.get_mission_command(mission_id, normalized["command_id"])
                if current is not None and current["status"] == "PENDING":
                    self.repository.update_mission_command(
                        normalized["command_id"],
                        status="FAILED",
                        before_version_vector=before,
                        last_error=str(exc),
                        updated_at=utcnow_iso(),
                    )
                raise

    def get_mission_command(self, mission_id: str, command_id: str) -> Dict[str, Any]:
        if self.repository.get_by_mission_id(mission_id) is None:
            raise MissionNotFound(mission_id)
        stored = self.repository.get_mission_command(mission_id, command_id)
        if stored is None:
            raise MissionCommandNotFound(command_id)
        return self._mission_command_payload(stored, idempotent_replay=False)

    def get_mission_command_history(self, mission_id: str) -> Dict[str, Any]:
        if self.repository.get_by_mission_id(mission_id) is None:
            raise MissionNotFound(mission_id)
        commands = self.repository.list_mission_commands(mission_id)
        return {
            "status": "completed",
            "mission_id": mission_id,
            "command_count": len(commands),
            "commands": [self._mission_command_payload(x, idempotent_replay=False) for x in commands],
        }

    def _build_repository_persistence_view(self, mission_id: str) -> Dict[str, Any]:
        stored = self.repository.get_by_mission_id(mission_id)
        if stored is None:
            raise MissionNotFound(mission_id)

        state = self.repository.get_state(mission_id)
        if state is None:
            raise MissionRepositoryIntegrityError("canonical mission state row is missing")
        transitions = self.repository.list_state_transitions(mission_id)
        scope_head = self.repository.get_scope_contract_head(mission_id)
        scope_versions = self.repository.list_scope_contract_versions(mission_id)
        governance_head = self.repository.get_governance_binding_head(mission_id)
        governance_versions = self.repository.list_governance_binding_versions(mission_id)
        governance_operations = self.repository.list_governance_operations(mission_id)
        authorization_operations = self.repository.list_authorization_operations(mission_id)
        authorization_bindings = self.repository.list_authorization_bindings(mission_id)
        routed_tasks = self.repository.list_routed_tasks(mission_id)
        dispatch_attempts = []
        for task in routed_tasks:
            dispatch_attempts.extend(self.repository.list_task_dispatch_attempts(task["task_id"]))
        commands = self.repository.list_mission_commands(mission_id)
        plan = self.repository.get_mission_plan(mission_id)
        planner_input_snapshot = self.repository.get_planner_input_snapshot(mission_id)
        task_decomposition = self.repository.get_task_decomposition(mission_id)
        planned_tasks = self.repository.list_planned_tasks(mission_id)
        task_dependency_graph = self.repository.get_task_dependency_graph(mission_id)
        task_dependency_edges = self.repository.list_task_dependency_edges(mission_id)
        planner_invocation = self.repository.get_planner_invocation(mission_id)
        generated_plan = self.repository.get_generated_plan(mission_id)
        plan_validation = self.repository.get_plan_validation(mission_id)
        plan_version_head = self.repository.get_plan_version_head(mission_id)
        plan_versions = self.repository.list_plan_versions(mission_id)
        task_readiness_projections = self.repository.list_task_readiness_projections(mission_id)
        planning_recovery_checkpoints = self.repository.list_planning_recovery_checkpoints(mission_id)
        task_routing_intents = self.repository.list_task_routing_intents(mission_id)
        task_routing_eligibility_gates = self.repository.list_task_routing_eligibility_gates(mission_id)
        task_route_decisions = self.repository.list_task_route_decisions(mission_id)
        delegation_authorizations = self.repository.list_delegation_authorizations(mission_id)
        task_delegations = self.repository.list_task_delegations(mission_id)
        delegation_deliveries = self.repository.list_delegation_deliveries(mission_id)
        delegation_recovery_controls = self.repository.list_delegation_recovery_controls(mission_id)
        routing_delegation_recovery_checkpoints = self.repository.list_routing_delegation_recovery_checkpoints(mission_id)
        execution_dispatch_contracts = self.repository.list_execution_dispatch_contracts(mission_id)
        dispatch_eligibility_gates = self.repository.list_dispatch_eligibility_gates(mission_id)
        pre_dispatch_revalidations = self.repository.list_pre_dispatch_revalidations(mission_id)
        execution_attempts = self.repository.list_execution_attempts(mission_id)
        execution_deliveries = self.repository.list_execution_deliveries(mission_id)
        execution_running_projections = self.repository.list_execution_running_projections(mission_id)
        execution_result_captures = self.repository.list_execution_result_captures(mission_id)
        execution_termination_controls = self.repository.list_execution_termination_controls(mission_id)
        execution_outcome_propagations = self.repository.list_execution_outcome_propagations(mission_id)
        execution_recovery_checkpoints = self.repository.list_execution_recovery_checkpoints(mission_id)
        task_outcomes = self.repository.list_task_outcomes(mission_id)
        task_terminality_eligibility_gates = self.repository.list_task_terminality_eligibility_gates(mission_id)
        task_evidence_binding_verifications = self.repository.list_task_evidence_binding_verifications(mission_id)
        task_completion_commits = self.repository.list_task_completions(mission_id)
        mission_outcome_aggregations = self.repository.list_mission_outcome_aggregations(mission_id)
        mission_success_criteria_evaluations = self.repository.list_mission_success_evaluations(mission_id)
        mission_completion_readiness_decisions = self.repository.list_completion_readiness_decisions(mission_id)
        mission_verified_completion_declarations = self.repository.list_verified_completion_declarations(mission_id)
        outcome_recovery_checkpoints = self.repository.list_outcome_recovery_checkpoints(mission_id)
        adaptation_replans = self.repository.list_adaptation_replans(mission_id)
        adaptation_trigger_classifications = self.repository.list_adaptation_trigger_classifications(mission_id)
        replan_eligibility_governance_gates = self.repository.list_replan_eligibility_gates(mission_id)
        replan_snapshots = self.repository.list_replan_snapshots(mission_id)
        replan_candidates = self.repository.list_replan_candidates(mission_id)
        replan_validations = self.repository.list_replan_validations(mission_id)
        replan_commits = self.repository.list_replan_commits(mission_id)
        replan_handoffs = self.repository.list_replan_handoffs(mission_id)
        replan_recovery_checkpoints = self.repository.list_replan_recovery_checkpoints(mission_id)
        events = self.repository.list_mission_events(mission_id)
        record_counts = self.repository.get_repository_record_counts(mission_id)
        metadata = self.repository.get_repository_metadata()

        checks: list[Dict[str, Any]] = []

        def check(name: str, ok: bool, detail: str) -> None:
            checks.append({"check": name, "status": "PASS" if ok else "FAIL", "detail": detail})

        # Repository schema metadata is an explicit Stage-3.1.7 contract.
        check(
            "repository_schema_metadata",
            metadata.get("schema_version") == REPOSITORY_SCHEMA_VERSION
            and int(metadata.get("migration_level", -1)) == REPOSITORY_MIGRATION_LEVEL
            and metadata.get("storage_model") == REPOSITORY_MODEL,
            f"schema={metadata.get('schema_version')} migration_level={metadata.get('migration_level')}",
        )

        envelope_ok = verify_envelope(stored.envelope)
        try:
            env_identity = stored.envelope["identity"]
            envelope_ok = envelope_ok and env_identity["mission_id"] == mission_id
            envelope_ok = envelope_ok and env_identity["envelope_id"] == stored.identity["envelope_id"]
            envelope_ok = envelope_ok and int(env_identity["envelope_version"]) == int(stored.identity["envelope_version"])
        except Exception:
            envelope_ok = False
        check("immutable_envelope_hash", envelope_ok, "canonical mission envelope hash and identity binding")

        # Canonical state projection must be exactly reconstructable from the append-only ledger.
        ledger_ok = True
        expected_state = "CREATED"
        expected_version = 1
        last_transition_id = None
        for transition in transitions:
            if (
                int(transition["from_state_version"]) != expected_version
                or int(transition["to_state_version"]) != expected_version + 1
                or transition["from_state"] != expected_state
                or not is_legal_transition(transition["from_state"], transition["to_state"])
            ):
                ledger_ok = False
                break
            expected_version += 1
            expected_state = transition["to_state"]
            last_transition_id = transition["transition_id"]
        ledger_ok = ledger_ok and int(state["state_version"]) == expected_version
        ledger_ok = ledger_ok and state["state"] == expected_state
        ledger_ok = ledger_ok and bool(state["terminal"]) == is_terminal(expected_state)
        ledger_ok = ledger_ok and state.get("last_transition_id") == last_transition_id
        check(
            "state_projection_from_append_only_ledger",
            ledger_ok,
            f"state={state['state']} state_version={state['state_version']} transitions={len(transitions)}",
        )

        scope_ok = True
        for expected, version in enumerate(scope_versions, 1):
            scope_ok = scope_ok and int(version["contract_version"]) == expected
            scope_ok = scope_ok and verify_contract(version["contract"])
            scope_ok = scope_ok and version["canonical_sha256"] == version["contract"]["integrity"]["canonical_sha256"]
        if scope_versions:
            latest = scope_versions[-1]
            scope_ok = scope_ok and scope_head is not None
            if scope_head is not None:
                scope_ok = scope_ok and int(scope_head["current_version"]) == int(latest["contract_version"])
                scope_ok = scope_ok and scope_head["current_snapshot_id"] == latest["snapshot_id"]
                scope_ok = scope_ok and scope_head["current_sha256"] == latest["canonical_sha256"]
        else:
            scope_ok = scope_head is None
        check("scope_version_store_and_head", scope_ok, f"versions={len(scope_versions)}")

        scope_by_snapshot = {x["snapshot_id"]: x for x in scope_versions}
        scope_by_version = {int(x["contract_version"]): x for x in scope_versions}
        governance_ok = True
        for expected, version in enumerate(governance_versions, 1):
            governance_ok = governance_ok and int(version["binding_version"]) == expected
            governance_ok = governance_ok and verify_binding_contract(version["binding"])
            governance_ok = governance_ok and version["canonical_sha256"] == version["binding"]["integrity"]["canonical_sha256"]
            scope_ref = scope_by_snapshot.get(version["mission_scope_snapshot_id"])
            governance_ok = governance_ok and scope_ref is not None
            if scope_ref is not None:
                governance_ok = governance_ok and scope_ref["canonical_sha256"] == version["mission_scope_sha256"]
        if governance_versions:
            latest = governance_versions[-1]
            governance_ok = governance_ok and governance_head is not None
            if governance_head is not None:
                governance_ok = governance_ok and int(governance_head["current_version"]) == int(latest["binding_version"])
                governance_ok = governance_ok and governance_head["current_binding_snapshot_id"] == latest["binding_snapshot_id"]
                governance_ok = governance_ok and governance_head["current_scope_snapshot_id"] == latest["mission_scope_snapshot_id"]
        else:
            governance_ok = governance_head is None
        check("governance_binding_version_store_and_head", governance_ok, f"versions={len(governance_versions)}")

        governance_by_version = {int(x["binding_version"]): x for x in governance_versions}
        authorization_ok = True
        for binding in authorization_bindings:
            authorization_ok = authorization_ok and verify_authorization_binding(binding["authorization_binding"])
            authorization_ok = authorization_ok and binding["canonical_sha256"] == binding["authorization_binding"]["integrity"]["canonical_sha256"]
            authorization_ok = authorization_ok and int(binding["governance_binding_version"]) in governance_by_version
            authorization_ok = authorization_ok and int(binding["scope_version"]) in scope_by_version
        check("authorization_binding_store", authorization_ok, f"bindings={len(authorization_bindings)}")

        routing_ok = True
        task_ids = set()
        for task in routed_tasks:
            routing_ok = routing_ok and verify_task_contract(task["task_contract"])
            routing_ok = routing_ok and task["canonical_sha256"] == task["task_contract"]["integrity"]["canonical_sha256"]
            routing_ok = routing_ok and task["task_id"] not in task_ids
            task_ids.add(task["task_id"])
        attempts_by_task: Dict[str, list[Dict[str, Any]]] = {}
        for attempt in dispatch_attempts:
            attempts_by_task.setdefault(attempt["task_id"], []).append(attempt)
            routing_ok = routing_ok and attempt["task_id"] in task_ids
        for task_id, attempts in attempts_by_task.items():
            numbers = [int(x["attempt_no"]) for x in attempts]
            routing_ok = routing_ok and numbers == list(range(1, len(numbers) + 1))
        check("routing_task_and_dispatch_store", routing_ok, f"tasks={len(routed_tasks)} attempts={len(dispatch_attempts)}")

        command_ok = True
        for command in commands:
            before = command.get("before_version_vector")
            after = command.get("after_version_vector")
            if before is not None:
                command_ok = command_ok and verify_version_vector(before)
            if after is not None:
                command_ok = command_ok and verify_version_vector(after)
            if command["status"] == "COMPLETED":
                command_ok = command_ok and after is not None and command.get("result") is not None
        check("command_journal_persisted_vectors", command_ok, f"commands={len(commands)}")

        plan_ok = True
        if plan is not None:
            plan_ok = verify_plan_contract(plan["plan_contract"])
            plan_ok = plan_ok and int(plan["plan_version"]) == PLAN_VERSION_INITIAL
            plan_ok = plan_ok and plan["canonical_sha256"] == plan["plan_contract"]["integrity"]["canonical_sha256"]
            plan_ok = plan_ok and int(plan["source_state_version"]) == int(plan["plan_contract"]["planning_activation_binding"]["state_version"])
            plan_ok = plan_ok and plan["source_transition_id"] == plan["plan_contract"]["planning_activation_binding"]["planning_transition_id"]
        check("canonical_plan_contract_store", plan_ok, f"plan_registered={plan is not None}")

        planner_input_ok = True
        if planner_input_snapshot is not None:
            planner_input_ok = verify_planner_input_snapshot(planner_input_snapshot["snapshot"])
            planner_input_ok = planner_input_ok and plan is not None
            if plan is not None:
                planner_input_ok = planner_input_ok and planner_input_snapshot["plan_id"] == plan["plan_id"]
