    def get_subsystem_capability(self, subsystem_id: str, capability_id: str) -> Dict[str, Any]:
        self._verified_subsystem_registry()
        normalized_subsystem = normalize_subsystem_id(subsystem_id)
        if self.repository.get_canonical_subsystem(normalized_subsystem) is None:
            raise SubsystemNotFound(normalized_subsystem)
        normalized_capability = normalize_capability_id(capability_id)
        capability = self.repository.get_subsystem_capability_contract(normalized_capability)
        if capability is None or capability["identity"]["subsystem_id"] != normalized_subsystem:
            raise SubsystemCapabilityNotFound(normalized_capability)
        return {
            "status": "completed",
            "component_id": COMPONENT_ID,
            "control_version": CONTROL_VERSION,
            "subsystem_id": normalized_subsystem,
            "capability": capability,
            "capability_is_authorization": False,
            "route_selection_performed": False,
            "delegation_performed": False,
            "governance_query_performed": False,
            "target_action_dispatch_enabled": False,
            "target_actuation": False,
        }

