    def _verified_observability_diagnostic_bundle(self, mission_id: str):
        """Read and bind Stage 3.8 sources once for diagnostics and metrics."""
        from .observability_diagnostics import (
            build_integrity_gap_consistency_diagnostics,
            verify_integrity_gap_consistency_diagnostics,
        )

        # Establish canonical Mission/trace identity before inspecting sources;
        # an unknown Mission still returns 404 and a corrupt envelope fails closed.
        trace_id = self.get_observability_trace_identity(mission_id)["trace_id"]
        sources = {}
        errors = {}
        readers = {
            "normalized_events": (self.get_normalized_observability_events, "events"),
            "causal_graph": (self.get_global_causal_lineage_graph, "graph"),
            "decision_trace": (self.get_decision_governance_evidence_trace, "projection"),
            "timeline": (self.get_deterministic_mission_timeline, "timeline"),
            "live_projection": (self.get_live_mission_state_execution_projection, "projection"),
        }
        for name, (reader, field) in readers.items():
            if name != "normalized_events" and sources.get("normalized_events") is None:
                errors[name] = "NORMALIZED_LEDGER_UNAVAILABLE"
                sources[name] = None
                continue
            if name in ("decision_trace", "timeline", "live_projection") and sources.get("causal_graph") is None:
                errors[name] = "CAUSAL_GRAPH_UNAVAILABLE"
                sources[name] = None
                continue
            try:
                result = reader(mission_id)
                if result["trace_id"] != trace_id:
                    raise ValueError("source trace changed during diagnostic read")
                sources[name] = result[field]
            except (MissionEventIntegrityError, RuntimeError, ValueError) as exc:
                # A source failure is diagnostic evidence, never a successful read.
                errors[name] = type(exc).__name__
                sources[name] = None

        report = build_integrity_gap_consistency_diagnostics(
            mission_id=mission_id, trace_id=trace_id,
            normalized_events=sources["normalized_events"], causal_graph=sources["causal_graph"],
            decision_trace=sources["decision_trace"], timeline=sources["timeline"],
            live_projection=sources["live_projection"], source_errors=errors,
        )
        if not verify_integrity_gap_consistency_diagnostics(report):
            raise RuntimeError("derived Mission observability diagnostics failed verification")
        return trace_id, sources, report

    def get_integrity_gap_consistency_diagnostics(self, mission_id: str) -> Dict[str, Any]:
        trace_id, _, report = self._verified_observability_diagnostic_bundle(mission_id)
        return {"status": "completed", "control_version": CONTROL_VERSION,
                "mission_id": mission_id, "trace_id": trace_id,
                "diagnostics": report, "integrity_status": "PASS", "read_only": True,
                "external_network_io_performed": False, "telemetry_export_performed": False,
                "dispatch_performed": False, "target_actuation": False}

