    def get_forensic_evidence_bundle(self, mission_id: str) -> Dict[str, Any]:
        from .observability_forensics import (
            build_forensic_evidence_bundle, read_forensic_records,
            verify_forensic_evidence_bundle,
        )
        trace = self.get_observability_trace_identity(mission_id)
        trace_id = trace["trace_id"]
        contract = trace["observability_trace_identity"]
        observed_trace, sources, diagnostics = self._verified_observability_diagnostic_bundle(mission_id)
        if observed_trace != trace_id:
            raise RuntimeError("forensic trace identity changed")
        records = None
        reason = None
        if diagnostics["status"] == "PASS":
            try:
                events = self._verified_mission_events(mission_id)
                stored = self.repository.get_by_mission_id(mission_id)
                records = read_forensic_records(
                    self.repository, mission_id, stored.identity, stored.envelope, events)
                # Existing repository reads are not an atomic snapshot. Compare both
                # complete inventories and the verified source projections on exit.
                again = read_forensic_records(
                    self.repository, mission_id, stored.identity, stored.envelope,
                    self._verified_mission_events(mission_id))
                if records != again:
                    reason = "RECORD_SNAPSHOT_DRIFT"
                later_trace, later_sources, later_diagnostics = self._verified_observability_diagnostic_bundle(mission_id)
                if (later_trace, later_sources, later_diagnostics) != (trace_id, sources, diagnostics):
                    reason = "OBSERVABILITY_SNAPSHOT_DRIFT"
                if self.get_observability_trace_identity(mission_id)["observability_trace_identity"] != contract:
                    reason = "CANONICAL_CONTRACT_DRIFT"
            except (MissionEventIntegrityError, RuntimeError, ValueError, MissionRepositoryIntegrityError):
                reason = "RECORD_SOURCE_UNAVAILABLE"
        bundle = build_forensic_evidence_bundle(
            mission_id=mission_id, trace_id=trace_id, trace_contract=contract,
            diagnostics=diagnostics, sources=sources if reason is None else None,
            records=records if reason is None else None, reason_code=reason)
        if not verify_forensic_evidence_bundle(bundle):
            raise RuntimeError("derived forensic evidence bundle failed verification")
        return {"status": "completed", "control_version": CONTROL_VERSION,
                "mission_id": mission_id, "trace_id": trace_id,
                "bundle": bundle, "integrity_status": "PASS", "read_only": True,
                "external_network_io_performed": False, "governance_query_performed": False,
                "dispatch_performed": False, "target_actuation": False}

    def get_forensic_reconstruction(self, mission_id: str) -> Dict[str, Any]:
        from .observability_forensics import reconstruct_forensic_mission
        bundle = self.get_forensic_evidence_bundle(mission_id)["bundle"]
        return {"status": "completed", "control_version": CONTROL_VERSION,
                "mission_id": mission_id, "trace_id": bundle["trace_id"],
                "result": reconstruct_forensic_mission(bundle), "read_only": True}

    def query_forensic_mission(self, mission_id: str, *, scope: str,
                               reference: str | None = None) -> Dict[str, Any]:
        from .observability_forensics import QUERY_KINDS, forensic_query
        if scope not in QUERY_KINDS or (reference is not None and (not reference or len(reference) > 256)):
            raise MissionValidationError("invalid forensic query scope or reference")
        bundle = self.get_forensic_evidence_bundle(mission_id)["bundle"]
        return {"status": "completed", "control_version": CONTROL_VERSION,
                "mission_id": mission_id, "trace_id": bundle["trace_id"],
                "result": forensic_query(bundle, scope=scope, reference=reference),
                "read_only": True}

