    def get_e2e_dispatch_execution_evidence_qualification(self, mission_id: str) -> Dict[str, Any]:
        stored = self.repository.get_by_mission_id(mission_id)
        if stored is None:
            raise MissionNotFound(mission_id)
        # Reconstruct the complete existing repository manifest first. Checking
        # execution rows alone would miss drift in the predecessor plan graph.
        try:
            repository_integrity_status = self.get_mission_repository(mission_id)["integrity_status"]
        except MissionRepositoryIntegrityError:
            repository_integrity_status = "FAIL"
        state = self.repository.get_state(mission_id)
        if state is None:
            raise MissionRepositoryIntegrityError("canonical mission state row is missing")
        active_plan = self.repository.get_active_plan_version(mission_id)
        readiness = None
        if active_plan is not None:
            readiness = self.repository.get_task_readiness_projection_for_plan_version(
                mission_id, int(active_plan["plan_version"])
            )
        event_view = self.get_mission_events(mission_id)
        # Stage 3.5.9 builds both views exclusively from the verified event ledger.
        # Neither view contacts Governance or a downstream runtime.
        lineage = self.get_execution_event_lineage(mission_id)
        replay = self.get_execution_event_replay(mission_id)
        qualification = evaluate_dispatch_execution_evidence_qualification(
            mission_id=mission_id, envelope=stored.envelope, state=state,
            active_plan=active_plan, readiness=readiness,
            scope=self.repository.get_current_scope_contract(mission_id),
            binding=self.repository.get_current_governance_binding(mission_id),
            routing_intents=self.repository.list_task_routing_intents(mission_id),
            routes=self.repository.list_task_route_decisions(mission_id),
            authorizations=self.repository.list_delegation_authorizations(mission_id),
            delegations=self.repository.list_task_delegations(mission_id),
            handoffs=self.repository.list_delegation_deliveries(mission_id),
            dispatches=self.repository.list_execution_dispatch_contracts(mission_id),
            gates=self.repository.list_dispatch_eligibility_gates(mission_id),
            revalidations=self.repository.list_pre_dispatch_revalidations(mission_id),
            attempts=self.repository.list_execution_attempts(mission_id),
            deliveries=self.repository.list_execution_deliveries(mission_id),
            running_projections=self.repository.list_execution_running_projections(mission_id),
            results=self.repository.list_execution_result_captures(mission_id),
            events=event_view["events"],
            repository_counts=self.repository.get_repository_record_counts(mission_id),
            event_integrity_status=event_view["integrity_status"],
            repository_integrity_status=repository_integrity_status,
            execution_lineage=lineage, execution_replay=replay,
        )
        return {
            "status": "completed", "control_version": CONTROL_VERSION,
            "mission_id": mission_id, "qualification": qualification,
            "read_only": True, "mission_state_transition_performed": False,
            "governance_query_performed": False, "runtime_io_performed": False,
            "dispatch_redelivery_performed": False, "new_execution_attempt_created": False,
            "task_completion_performed": False, "mission_completion_performed": False,
            "target_actuation": False,
        }

