    def list_missions(
        self,
        *,
        state: Optional[str] = None,
        source_system: Optional[str] = None,
        query: Optional[str] = None,
        terminal: Optional[bool] = None,
        visibility: str = "ALL",
        limit: int = 50,
        offset: int = 0,
    ) -> Dict[str, Any]:
        from .archive_mission import validate_visibility
        visibility = validate_visibility(visibility)
        projection = self.repository.list_mission_console_rows(
            state=state,
            source_system=source_system,
            query=query,
            terminal=terminal,
            visibility=visibility,
            limit=limit,
            offset=offset,
        )
        return {
            "status": "completed",
            "component_id": "APTS-MO01",
            "control_version": CONTROL_VERSION,
            "read_only": True,
            "mission_count": projection["total"],
            "visibility": visibility,
            "limit": projection["limit"],
            "offset": projection["offset"],
            "missions": projection["items"],
        }

    def get_dashboard_summary(self) -> Dict[str, Any]:
        counts = self.repository.mission_console_state_counts()
        archived = self.repository.mission_archive_counts()["archived"]
        source_counts = self.repository.mission_console_source_counts()
        total = sum(counts.values())
        terminal_states = {"COMPLETED", "ABORTED", "FAILED", "EXPIRED"}
        terminal_count = sum(counts.get(state, 0) for state in terminal_states)
        attention = {
            "waiting_approval": counts.get("WAITING_APPROVAL", 0),
            "waiting_evidence": counts.get("WAITING_EVIDENCE", 0),
            "paused": counts.get("PAUSED", 0),
            "failed": counts.get("FAILED", 0),
            "replanning": counts.get("REPLANNING", 0),
        }
        return {
            "status": "completed",
            "component_id": "APTS-MO01",
            "control_version": CONTROL_VERSION,
            "read_only": True,
            "mission_counts": {
                "total": total,
                "historical_total": total + archived,
                "archived": archived,
                "active": total - terminal_count,
                "terminal": terminal_count,
                "by_state": counts,
            },
            "attention": attention,
            "source_counts": source_counts,
            "health_path": "/health",
            "missions_path": "/api/missions",
        }

    def get_operator_attention(self, *, limit: int = 50) -> Dict[str, Any]:
        limit = max(1, min(int(limit or 50), 200))
        states = ["WAITING_APPROVAL", "WAITING_EVIDENCE", "FAILED", "PAUSED", "REPLANNING"]
        items = []
        for state in states:
            remaining = limit - len(items)
            if remaining <= 0:
                break
            result = self.repository.list_mission_console_rows(state=state, visibility="ACTIVE", limit=remaining, offset=0)
            for row in result["items"]:
                row = dict(row)
                row["attention_reason"] = state
                items.append(row)
        items.sort(key=lambda item: item.get("updated_at") or item.get("created_at") or "", reverse=True)
        return {
            "status": "completed",
            "component_id": "APTS-MO01",
            "control_version": CONTROL_VERSION,
            "read_only": True,
            "attention_count": len(items[:limit]),
            "items": items[:limit],
        }

    # ------------------------------------------------------------------
    # Phase 3 Advanced Operations read-models
    # ------------------------------------------------------------------
    @staticmethod
    def _phase3_plan_record_by_version(versions: list[Dict[str, Any]], plan_version: int) -> Dict[str, Any]:
        for item in versions:
            if int(item.get("plan_version", -1)) == int(plan_version):
                return item
        raise MissionPlanVersioningNotFound(f"plan version {plan_version}")

    @staticmethod
    def _phase3_plan_step_changes(before: Dict[str, Any], after: Dict[str, Any]) -> list[Dict[str, Any]]:
        fields = (
            "objective", "task_type", "required_subsystem", "required_capability", "priority",
            "dependency_task_keys", "preconditions", "expected_outputs", "evidence_requirements",
            "success_criteria", "planning_layer", "step_index",
        )
        changes = []
        for field in fields:
            if before.get(field) != after.get(field):
                changes.append({"field": field, "before": before.get(field), "after": after.get(field)})
        return changes

    def get_plan_version_diff(self, mission_id: str, *, from_version: int, to_version: int) -> Dict[str, Any]:
        if self.repository.get_by_mission_id(mission_id) is None:
            raise MissionNotFound(mission_id)
        versions = self.repository.list_plan_versions(mission_id)
        if not versions:
            raise MissionPlanVersioningNotFound(mission_id)
        before_record = self._phase3_plan_record_by_version(versions, int(from_version))
        after_record = self._phase3_plan_record_by_version(versions, int(to_version))
        before_plan = before_record["plan_version_contract"].get("candidate_plan") or {}
        after_plan = after_record["plan_version_contract"].get("candidate_plan") or {}
        before_steps = {str(x.get("task_key")): x for x in before_plan.get("plan_steps", []) if x.get("task_key")}
        after_steps = {str(x.get("task_key")): x for x in after_plan.get("plan_steps", []) if x.get("task_key")}
        before_keys = set(before_steps)
        after_keys = set(after_steps)
        added_keys = sorted(after_keys - before_keys)
        removed_keys = sorted(before_keys - after_keys)
        modified = []
        unchanged = []
        for key in sorted(before_keys & after_keys):
            changes = self._phase3_plan_step_changes(before_steps[key], after_steps[key])
            if changes:
                modified.append({"task_key": key, "changes": changes})
            else:
                unchanged.append(key)
        def edge_set(plan: Dict[str, Any]):
            return {
                (str(e.get("from_task_key")), str(e.get("to_task_key")))
                for e in plan.get("dependency_edges", [])
                if e.get("from_task_key") is not None and e.get("to_task_key") is not None
            }
        before_edges = edge_set(before_plan)
        after_edges = edge_set(after_plan)
        added_edges = sorted(after_edges - before_edges)
        removed_edges = sorted(before_edges - after_edges)
        return {
            "status": "completed",
            "component_id": COMPONENT_ID,
            "control_version": CONTROL_VERSION,
            "read_only": True,
            "mission_id": mission_id,
            "from": {
                "plan_version": int(before_record["plan_version"]),
                "plan_version_record_id": before_record["plan_version_record_id"],
                "canonical_sha256": before_record["canonical_sha256"],
                "candidate_plan_sha256": before_record["candidate_plan_sha256"],
            },
            "to": {
                "plan_version": int(after_record["plan_version"]),
                "plan_version_record_id": after_record["plan_version_record_id"],
                "canonical_sha256": after_record["canonical_sha256"],
                "candidate_plan_sha256": after_record["candidate_plan_sha256"],
            },
            "summary": {
                "plan_content_equal": before_record["candidate_plan_sha256"] == after_record["candidate_plan_sha256"],
                "added_task_count": len(added_keys),
                "removed_task_count": len(removed_keys),
                "modified_task_count": len(modified),
                "unchanged_task_count": len(unchanged),
                "added_dependency_count": len(added_edges),
                "removed_dependency_count": len(removed_edges),
            },
            "tasks": {
                "added": [{"task_key": key, "after": after_steps[key]} for key in added_keys],
                "removed": [{"task_key": key, "before": before_steps[key]} for key in removed_keys],
                "modified": modified,
                "unchanged": unchanged,
            },
            "dependencies": {
                "added": [{"from_task_key": a, "to_task_key": b} for a, b in added_edges],
                "removed": [{"from_task_key": a, "to_task_key": b} for a, b in removed_edges],
            },
            "governance_authorization_performed": False,
            "dispatch_performed": False,
            "target_actuation": False,
        }

    def get_mission_event_stream_snapshot(
        self, mission_id: str, *, after_event_id: Optional[str] = None, limit: int = 200
    ) -> Dict[str, Any]:
        history = self.get_mission_events(mission_id)
        events = list(history.get("events") or [])
        start = 0
        cursor_found = after_event_id is None
        if after_event_id:
            for index, event in enumerate(events):
                if event.get("event_id") == after_event_id:
                    start = index + 1
                    cursor_found = True
                    break
        limit = max(1, min(int(limit or 200), 1000))
        items = events[start:start + limit] if cursor_found else events[-limit:]
        latest = events[-1].get("event_id") if events else None
        return {
            "status": "completed",
            "component_id": COMPONENT_ID,
            "control_version": CONTROL_VERSION,
            "read_only": True,
            "mission_id": mission_id,
            "cursor_found": cursor_found,
            "after_event_id": after_event_id,
            "latest_event_id": latest,
            "event_count": len(items),
            "events": items,
            "history_event_count": len(events),
            "external_network_io_performed": False,
            "dispatch_performed": False,
            "target_actuation": False,
        }

    @staticmethod
    def _phase3_record_timestamp(record: Dict[str, Any]) -> Optional[str]:
        for key in (
            "created_at", "recorded_at", "occurred_at", "captured_at", "verified_at", "decided_at",
            "completed_at", "committed_at", "declared_at", "evaluated_at", "started_at", "terminated_at",
        ):
            value = record.get(key)
            if value:
                return str(value)
        return None

    @staticmethod
    def _phase3_record_identifier(record: Dict[str, Any]) -> Optional[str]:
        preferred = (
            "verification_id", "result_capture_id", "task_outcome_id", "aggregation_id", "declaration_id",
            "execution_attempt_id", "completion_id", "event_id", "id", "canonical_sha256",
        )
        for key in preferred:
            value = record.get(key)
            if value is not None:
                return str(value)
        return None

    def get_evidence_browser(self, mission_id: str, *, limit: int = 250) -> Dict[str, Any]:
        bundle_response = self.get_forensic_evidence_bundle(mission_id)
        bundle = bundle_response.get("bundle") or {}
        records = bundle.get("records") or {}
        groups = (
            ("RESULT_CAPTURE", "result_captures"),
            ("EVIDENCE_BINDING", "evidence_binding_verifications"),
            ("TASK_OUTCOME", "task_outcomes"),
            ("MISSION_OUTCOME", "outcome_aggregations"),
            ("COMPLETION", "completion_declarations"),
            ("EXECUTION", "execution_attempts"),
        )
        items = []
        counts = {}
        for category, key in groups:
            value = records.get(key) or []
            if isinstance(value, dict):
                value = [value]
            if not isinstance(value, list):
                value = []
            counts[category] = len(value)
            for record in value:
                if not isinstance(record, dict):
                    continue
                task_ref = (
                    record.get("planned_task_id") or record.get("task_id") or record.get("task_key")
                    or (record.get("contract") or {}).get("planned_task_id")
                )
                items.append({
                    "category": category,
                    "record_type": key,
                    "record_id": self._phase3_record_identifier(record),
                    "task_ref": task_ref,
                    "timestamp": self._phase3_record_timestamp(record),
                    "canonical_sha256": record.get("canonical_sha256") or (record.get("integrity") or {}).get("canonical_sha256"),
                    "record": record,
                })
        items.sort(key=lambda item: item.get("timestamp") or "", reverse=True)
        limit = max(1, min(int(limit or 250), 1000))
        items = items[:limit]
        return {
            "status": "completed",
            "component_id": COMPONENT_ID,
            "control_version": CONTROL_VERSION,
            "read_only": True,
            "mission_id": mission_id,
            "trace_id": bundle_response.get("trace_id"),
            "bundle_id": bundle.get("bundle_id"),
            "bundle_status": bundle.get("status"),
            "integrity_status": bundle_response.get("integrity_status"),
            "category_counts": counts,
            "evidence_count": len(items),
            "items": items,
            "forensic_bundle_path": f"/api/missions/{mission_id}/forensic-evidence-bundle",
            "governance_query_performed": False,
            "dispatch_performed": False,
            "target_actuation": False,
        }

    def compare_missions(self, left_mission_id: str, right_mission_id: str) -> Dict[str, Any]:
        def snapshot(mission_id: str) -> Dict[str, Any]:
            identity = self.get_mission(mission_id)["mission"]
            envelope = self.get_envelope(mission_id)["envelope"]
            state = self.get_mission_state(mission_id).get("mission_state") or {}
            row_result = self.repository.list_mission_console_rows(query=mission_id, limit=200, offset=0)
            row = next((x for x in row_result.get("items", []) if x.get("mission_id") == mission_id), {})
            try:
                metrics = (self.get_observability_metrics_health(mission_id).get("report") or {})
            except Exception:
                metrics = {}
            live = (metrics.get("metrics") or {}).get("live_snapshot") or {}
            health = metrics.get("observability_health") or {}
            operator = metrics.get("operator_diagnostics") or {}
            mission_contract = envelope.get("mission") or {}
            return {
                "mission_id": mission_id,
                "source_system": identity.get("source_system"),
                "created_at": identity.get("created_at"),
                "mission_kind": mission_contract.get("mission_kind"),
                "objective": mission_contract.get("objective"),
                "state": state.get("state"),
                "state_version": state.get("state_version"),
                "terminal": state.get("terminal"),
                "active_plan_version": row.get("active_plan_version"),
                "plan_version_count": live.get("plan_version_count", row.get("plan_version_count")),
                "planned_task_count": live.get("planned_task_count", row.get("planned_task_count")),
                "completed_task_count": live.get("completed_task_count", row.get("completed_task_count")),
                "event_count": (metrics.get("metrics") or {}).get("event_count", row.get("event_count")),
                "execution_attempt_count": live.get("execution_attempt_count"),
                "replan_commit_count": live.get("replan_commit_count"),
                "observability_health": health.get("status"),
                "diagnostics_status": operator.get("status"),
                "blocking_finding_count": operator.get("blocking_finding_count"),
                "latest_event": row.get("latest_event"),
            }
        left = snapshot(left_mission_id)
        right = snapshot(right_mission_id)
        numeric_keys = (
            "state_version", "active_plan_version", "plan_version_count", "planned_task_count",
            "completed_task_count", "event_count", "execution_attempt_count", "replan_commit_count",
            "blocking_finding_count",
        )
        deltas = {}
        for key in numeric_keys:
            lv, rv = left.get(key), right.get(key)
            deltas[key] = None if lv is None or rv is None else rv - lv
        return {
            "status": "completed",
            "component_id": COMPONENT_ID,
            "control_version": CONTROL_VERSION,
            "read_only": True,
            "left": left,
            "right": right,
            "comparison": {
                "same_mission": left_mission_id == right_mission_id,
                "same_state": left.get("state") == right.get("state"),
                "same_source_system": left.get("source_system") == right.get("source_system"),
                "same_objective": left.get("objective") == right.get("objective"),
                "same_observability_health": left.get("observability_health") == right.get("observability_health"),
                "deltas_right_minus_left": deltas,
            },
            "governance_authorization_performed": False,
            "dispatch_performed": False,
            "target_actuation": False,
        }

    def get_operator_attention_advanced(self, *, limit: int = 100) -> Dict[str, Any]:
        base = self.get_operator_attention(limit=min(max(int(limit or 100) * 2, 20), 200))
        severity_rank = {"CRITICAL": 4, "HIGH": 3, "MEDIUM": 2, "LOW": 1, "INFO": 0}
        state_policy = {
            "FAILED": ("CRITICAL", "Inspect terminal failure lineage and forensic reconstruction."),
            "WAITING_APPROVAL": ("HIGH", "Review the authoritative aptsGSS approval queue."),
            "WAITING_EVIDENCE": ("HIGH", "Inspect missing evidence and task evidence-binding status."),
            "PAUSED": ("MEDIUM", "Confirm whether the mission should remain contained or resume."),
            "REPLANNING": ("MEDIUM", "Inspect replan lineage and compare plan versions."),
        }
        items = []
        for row in base.get("items", []):
            item = dict(row)
            mission_id = item.get("mission_id")
            state_name = item.get("attention_reason") or item.get("state") or "UNKNOWN"
            severity, action = state_policy.get(state_name, ("LOW", "Inspect mission state and diagnostics."))
            reason_codes = [f"STATE_{state_name}"]
            blocking = 0
            health = None
            diagnostics = None
            try:
                report = (self.get_observability_metrics_health(mission_id).get("report") or {})
                health = (report.get("observability_health") or {}).get("status")
                operator = report.get("operator_diagnostics") or {}
                diagnostics = operator.get("status")
                blocking = int(operator.get("blocking_finding_count") or 0)
                if blocking:
                    severity = "CRITICAL"
                    reason_codes.append("BLOCKING_INTEGRITY_FINDING")
                    action = "Inspect blocking observability/integrity findings before any operator continuation."
                elif health not in {None, "HEALTHY"}:
                    if severity_rank[severity] < severity_rank["HIGH"]:
                        severity = "HIGH"
                    reason_codes.append("OBSERVABILITY_UNHEALTHY")
            except Exception:
                reason_codes.append("OBSERVABILITY_UNAVAILABLE")
            item.update({
                "severity": severity,
                "priority_score": severity_rank[severity] * 100 + (10 if blocking else 0),
                "reason_codes": reason_codes,
                "recommended_operator_action": action,
                "blocking_finding_count": blocking,
                "observability_health": health,
                "diagnostics_status": diagnostics,
            })
            items.append(item)
        items.sort(
            key=lambda x: (int(x.get("priority_score") or 0), x.get("updated_at") or x.get("created_at") or ""),
            reverse=True,
        )
        limit = max(1, min(int(limit or 100), 200))
        items = items[:limit]
        counts = {level: sum(1 for x in items if x.get("severity") == level) for level in severity_rank}
        return {
            "status": "completed",
            "component_id": COMPONENT_ID,
            "control_version": CONTROL_VERSION,
            "read_only": True,
            "attention_count": len(items),
            "severity_counts": counts,
            "items": items,
            "governance_authorization_performed": False,
            "dispatch_performed": False,
            "target_actuation": False,
        }
